In order to establish an unconditional stability result for \eqref{BDF2NS1}-\eqref{BDF2NS2}, we need the following result about the Stokes pressure introduced in \cite{liuCPAM}. For any $\bm u \in H^2(\Omega, \mathbb{R}^N)$, the Stokes pressure $p_s=p_s(\bm u)$ is defined as
\begin{equation}\label{stokespredef}
\nabla p_s(\bm u)=(\Delta \mathcal{P}-\mathcal{P} \Delta) \bm u,
\end{equation}
 where $\mathcal{P}$ is the Leray-Helmholtz projection operator onto divergence-free fields with zero normal component, providing the Helmholtz decomposition $\bm u =\mathcal{P} \bm u+\nabla \phi$, where
\begin{equation}
\big( \mathcal{P}\bm u, \nabla q \big)=\big(\bm u-\nabla \phi, \nabla q \big)=0, \quad \forall q \in H^1(\Omega).
\end{equation}
Then it is proved in \cite{liuCPAM} that
\begin{lemma}\label{stokespre}
Let $\Omega \subset \mathbb{R}^N (N\ge 2)$ be a connected bounded domain with $C^3$ boundary. Then for any $\varepsilon>0$, there exists $C \ge 0$ such that for all vector fields $\bm u \in H^2 \cap H_0^1(\Omega, \mathbb{R}^N)$,
\begin{equation}\label{stokespre2}
\int_{\Omega}|(\Delta \mathcal{P}-\mathcal{P}\Delta) \bm u|^2 \le \big(\frac{1}{2}+\varepsilon \big)\int_{\Omega}|\Delta \bm u|^2+C\int_{\Omega}|\nabla \bm u|^2.
\end{equation}
\end{lemma}

In order to make use of the energy techniques to conduct stability and error analysis, we need to find suitable multipliers with the help of following lemma from Dahlquist's G-stability theory \cite{dahlquist1978g}.
\begin{lemma}\label{Gstability}
Let $\alpha(\zeta)=\alpha_q\zeta^q+...+\alpha_0$ and $\mu(\zeta)=\mu_q\zeta^q+...+\mu_0$ be polynomials of degree at most $q$ (and at least one of them of degree $q$) that have no common divisors. Let $(\cdot, \cdot)$ be an inner product with associated norm $|\cdot|$. If
\begin{equation}
\text{Re}\frac{\alpha(\zeta)}{\mu(\zeta)}>0 \quad \text{for} \, |\zeta|>1,
\end{equation}
then there exists a symmetric positive definite matrix $G=(g_{ij}) \in \mathbb{R}^{q\times q}$ and real $\delta_0,...,\delta_q$ such that for $\upsilon^0,...,\upsilon^q$ in the inner product space,
\begin{equation}
\big(\sum_{i=0}^q \alpha_i \upsilon^i, \sum_{j=0}^q \mu_j \upsilon^j \big)=\sum_{i,j=1}^{q}g_{ij}(\upsilon^i,\upsilon^j)-\sum_{i,j=1}^{q}g_{ij}(\upsilon^{i-1},\upsilon^{j-1})+\big |\sum_{i=0}^q\delta_i \upsilon^i \big|^2.
\end{equation}

\end{lemma}


\section{Higher-order  consistent splitting scheme for the time dependent Stokes equations}
We shall first present   generalized  BDF  consistent splitting schemes based on the Taylor expansion at time $t^{n+\beta}$, and then  show that the $k$-th ($k=2,3,4$) order with suitable $\beta$s are unconditionally stable in the strong norm.
\subsection{The generalized BDF  schemes}
We note that we constructed  in \cite{HS2024} generalized  BDF schemes  based on the Taylor expansion at time $t^{n+\beta}$ for general parabolic type equations.   Following  \cite{HS2024}, we can construct  generalized  BDF  consistent splitting schemes as follows.
%We can derive the coefficients for the $k$-th order schemes as follows.
Given an integer $k\ge 2$, denote $t^n= n\delta t$, it follows from the Taylor expansion at time $t^{n+\beta}$ that
\begin{equation}\label{Taylor}
\phi(t^{n+1-i})=\sum_{m=0}^{k-1}[(1-i-\beta)\delta t]^m \frac{\phi^{(m)}(t^{n+\beta})}{m!}+\mathcal{O}(\delta t^{k}),\quad \forall i \ge 0.
\end{equation}
Therefore we have
\begin{equation}\label{TaylorA}
\frac{1}{\delta t}\sum_{q=0}^{k}a_{k,q}(\beta)\phi(t^{n+1-k+q})=\partial_t\phi(t^{n+\beta})+\mathcal{O}(\delta t^k),
\end{equation}
with $a_{k,q}(\beta)$ can be obtained by solving the linear system:
\begin{equation}\label{solve_akq}
{\left[
\begin{array}{ccccc}
1&1&...&...&1\\
\beta-1&\beta&...&...&\beta+k-1\\
(\beta-1)^2&\beta^2&...&...&(\beta+k-1)^2\\
\vdots&\vdots&\vdots&\vdots&\vdots\\
(\beta-1)^k&\beta^k&...&...&(\beta+k-1)^k
\end{array}
\right]}{\left[
\begin{array}{c}
a_{k,k}(\beta)\\a_{k,k-1}(\beta)\\a_{k,k-2}(\beta)\\ \vdots \\a_{k,0}(\beta)
\end{array}
\right]}=
{\left[
\begin{array}{c}
0\\-1\\0\\ \vdots \\0
\end{array}
\right]};
\end{equation}
and
\begin{equation}\label{TaylorB}
\sum_{q=0}^{k-1}b_{k,q}(\beta)\phi(t^{n+2-k+q})=\phi(t^{n+\beta})+\mathcal{O}(\delta t^k),
\end{equation}
with $b_{k,q}(\beta)$ can be obtained by solving the linear system:
\begin{equation}\label{solve_bkq}
{\left[
\begin{array}{ccccc}
1&1&...&...&1\\
\beta-1&\beta&...&...&\beta+k-2\\
\vdots &\vdots&\vdots&\vdots&\vdots\\
(\beta-1)^{k-1}&\beta^{k-1}&...&...&(\beta+k-2)^{k-1}
\end{array}
\right]}{\left[
\begin{array}{c}
b_{k,k-1}(\beta)\\b_{k,k-2}(\beta)\\\vdots\\b_{k,0}(\beta)
\end{array}
\right]}=
{\left[
\begin{array}{c}
1\\0\\\vdots\\0
\end{array}
\right]};
\end{equation}
and finally
\begin{equation}\label{TaylorC}
\sum_{q=0}^{k-1}c_{k,q}(\beta)\phi(t^{n+1-k+q})=\phi(t^{n+\beta})+\mathcal{O}(\delta t^k),
\end{equation}
with $c_{k,q}(\beta)$ can be obtained by solving the linear system:
\begin{equation}\label{solve_ckq}
{\left[
\begin{array}{ccccc}
1&1&...&...&1\\
\beta&\beta+1&...&...&\beta+k-1\\
\vdots &\vdots&\vdots&\vdots&\vdots\\
\beta^{k-1}&(\beta+1)^{k-1}&...&...&(\beta+k-1)^{k-1}
\end{array}
\right]}{\left[
\begin{array}{c}
c_{k,k-1}(\beta)\\c_{k,k-2}(\beta)\\\vdots\\c_{k,0}(\beta)
\end{array}
\right]}=
{\left[
\begin{array}{c}
1\\0\\\vdots\\0
\end{array}
\right]}.
\end{equation}
Next, we would like to introduce the following notations to simplify the presentation below,
\begin{equation}\label{ABC_def}
\quad A_k^{\beta}(\phi^{i})=\sum_{q=0}^{k}a_{k,q}(\beta)\phi^{i-k+q},\,\quad B_k^{\beta}(\phi^{i})=\sum_{q=0}^{k-1}b_{k,q}(\beta)\phi^{i-k+1+q},\,\quad C_k^{\beta}(\phi^{i})=\sum_{q=0}^{k-1}c_{k,q}(\beta) \phi^{i-k+1+q}.
\end{equation}
Now, with the above notations,  the generalized $k$-th order BDF type schemes with explicit treatment of the pressure for the time dependent Stokes equation (in the absence of $\bm f$ and nonlinear term in \eqref{NS})  are as follows:
\begin{subequations}\label{scheme_stoke}
\begin{align}
&\frac{A_k^{\beta}(\bm u^{n+1})}{\delta t}-\nu \Delta B_k^{\beta}(\bm u^{n+1})+\nabla C_k^{\beta}(p^{n})=0, \label{scheme_stoke1}\\
&(\nabla p^{n+1},\nabla q)=-\nu(\nabla\times\nabla\times \bm u^{n+1},\nabla q),\quad\forall q\in H^1(\Omega).\label{scheme_stoke2}
\end{align}
\end{subequations}
\subsection{Linear stability regions}
Before providing the stability proof for the new schemes \eqref{scheme_stoke}, we would like to first investigate the linear stability regions of the new BDF type schemes. For the test equation $\phi_t= \lambda\phi$, by performing the Taylor expansions at $t^{n+\beta}$, a more  general BDF type method can be written as
\begin{equation}\label{genBDF}
\frac{A_k^{\beta}(\phi^{n+1})}{\delta t}=\lambda B_k^{\beta}(\phi^{n+1}).
\end{equation}
In order to study the stability region for  $\beta \ne 1$, we set $\phi^n=\mu^n$ and ${z=\lambda\delta t}$ in \eqref{genBDF} to obtain its characteristic polynomial
\begin{equation}\label{eq:chara}
\sum_{q=0}^k (a_{k,q}(\beta)- b_{k,q-1}(\beta)z)\mu^q=0,
\end{equation}
where $a_{k,q}(\beta)$ and $b_{k,q}(\beta)$ are defined in \eqref{solve_akq} and \eqref{solve_bkq} respectively and we further define $b_{k,-1}=0$ in \eqref{eq:chara}.
