\subsection{A uniform multiplier}
To conduct the stability and error analysis,  we need to choose a suitable $\beta$ for schemes of different orders. In the following, we choose $\beta=\beta_k$ as follows:
\begin{equation}\label{betak}
\beta_2=3,\,\beta_3=6,\,\beta_4=9.
\end{equation}
These choices of $\beta$ are sufficient for our purposes, but not necessarily the smallest possible. We recall that as $\beta$ increases, so does the truncation error. So it is desirable to choose $\beta$ as small as possible while maintaining stability.
 For the rest of the paper, we fix $\beta_k$ as \eqref{betak} and then the explicit expression of \eqref{scheme_stoke1} becomes:

\noindent $k=2$, $\beta=3$:
\begin{small}
\begin{equation}
\frac{7\bm u^{n+1}-12\bm u^n+5\bm u^{n-1}}{2\delta t}-\nu \Delta(3\bm u^{n+1}-2\bm u^n)+\nabla (4p^n-3p^{n-1})=0;
\end{equation}
\end{small}\noindent $k=3$, $\beta=6$:
\begin{small}
\begin{equation}
\frac{146\bm u^{n+1}-393\bm u^n+354\bm u^{n-1}-107\bm u^{n-2}}{6\delta t}-\nu \Delta(21\bm u^{n+1}-35\bm u^n+15\bm u^{n-1})+\nabla (28p^n-48p^{n-1}+21p^{n-2})=0;
\end{equation}
\end{small}\noindent $k=4$, $\beta=9$:
\begin{small}
\begin{equation}
\begin{split}
\frac{2289\bm u^{n+1}-8432\bm u^n+11700\bm u^{n-1}-7248\bm u^{n-2}+1691\bm u^{n-3}}{12\delta t}&-\nu \Delta(165\bm u^{n+1}-440\bm u^n+396\bm u^{n-1}-120\bm u^{n-2})\\
+&\nabla (220p^n-594p^{n-1}+540p^{n-2}-165p^{n-3})=0;
\end{split}
\end{equation}
\end{small}
%{\color{black} $\eta_k$ should be specified below!} {\color{black}We already fixed it as 0.71 in the line after \eqref{deltak}? }

A key step in the proof  is to properly split $B_k^{\beta_k}(\bm u^{n+1})$ into three parts as follows:
\begin{equation}\label{splitB}
B_k^{\beta_k}(\bm u^{n+1})=\eta_k C_k^{\beta_k}(\bm u^{n+1})+D_k^{\beta_k}(\bm u^{n+1})+F_k^{\beta_k}(\bm u^{n+1}),\quad k=2,3,4,
\end{equation}
with $\eta_k$ being a suitable positive number to be specified, and
\begin{subequations}\label{fkq}
\begin{align}
& F_2^{\beta_2}(\bm u^{n+1}):=\sum_{q=0}^{1}f_{2,q}(\beta_2) \bm u^{n+q}=\frac{1}{100}\bm u^{n+1}+0\bm u^{n},\\
& F_3^{\beta_3}(\bm u^{n+1}):=\sum_{q=0}^{2}f_{3,q}(\beta_3) \bm u^{n-1+q}=\frac{1}{100}(27\bm u^{n+1}-21\bm u^{n})+0\bm u^{n-1},\\
& F_4^{\beta_4}(\bm u^{n+1}):=\sum_{q=0}^{3}f_{4,q}(\beta_4) \bm u^{n-2+q}=\frac{2}{10^5}(215\bm u^{n+1}-375\bm u^{n}+165\bm u^{n-1})+0\bm u^{n-2},
\end{align}
\end{subequations}
and
\begin{equation}\label{dkq}
d_{k,q}(\beta_k)=b_{k,q}(\beta_k)-\eta_k c_{k,q}(\beta_k)-f_{k,q}(\beta_k),\quad D_k^{\beta_k}(\bm u^{n+1}):=\sum_{q=0}^{k-1}d_{k,q}(\beta_k) \bm u^{n-k+2+q}.
\end{equation}
The reasons for the above splitting will become clear later. In the above,
 $\eta_k$ should be chosen such that $\eta_k>\frac{\sqrt{2}}{2}\approx 0.7071$, the reason will be given in \eqref{etak_cond} below.

By choosing $F_k^{\beta_k}$ as in \eqref{fkq}, we have the following inequalities,  which are useful in the next section. The explicit telescoping terms given in appendix \ref{app1} imply there exits $U_k(\bm u^{i},...,\bm u^{i+2-k})\ge 0,\,k=2,3,4$ such that
\begin{equation}\label{Fk_ineq}
\big(F_k^{\beta_k}(\bm u^{n+1}), C_k^{\beta_k}(\bm u^{n+1}) \big) \ge \kappa_k \|\bm u^{n+1}\|^2+U_k(\bm u^{n+1},...,\bm u^{n+3-k})-U_k(\bm u^{n},...,\bm u^{n+2-k}),
\end{equation}
with
\begin{equation}\label{deltak}
\kappa_2=\frac{1}{100},\quad \kappa_3=\frac{3}{50},\quad \kappa_4=\frac{1}{10^4}.
\end{equation}


In the following, we fix $\eta_k=0.71$ and  $\beta_k$  as in \eqref{betak}  for $k=2,3,4$. Then, we can establish two important lemmas which play  key roles in the stability and error analysis. To this end, we introduce some polynomials with coefficients appearing in \eqref{ABC_def} and \eqref{dkq},
\begin{equation}\label{ACD_poly}
\tilde{A}_k^{\beta_k}(\zeta)=\sum_{q=0}^{k}a_{k,q}(\beta_k)\zeta^q,\,\quad \tilde{C}_k^{\beta_k}(\zeta)=\sum_{q=0}^{k-1}c_{k,q}(\beta_k)\zeta^q,\,\quad \tilde{D}_k^{\beta_k}(\zeta^q)=\sum_{q=0}^{k-1}d_{k,q}(\beta_k) \zeta^q.
\end{equation}
\begin{lemma}\label{AC_lemma}
Given $\tilde{A}^{\beta_k}_k(\zeta), \tilde{C}^{\beta_k}_k(\zeta)$ defined in \eqref{ACD_poly} and $\beta_k$ as in \eqref{betak}, we have
\begin{equation}\label{AC_lemma1}
\rm{gcd}\big(\tilde{A}^{\beta_k}_k(\zeta),\zeta\tilde{C}^{\beta_k}_k(\zeta)\big)=1,\,k=2,3,4,
\end{equation}
 i.e. they have no common divisor, and
\begin{equation}\label{AC_lemma2}
\text{Re}\frac{\tilde{A}_k^{\beta_k}(\zeta)}{\zeta\tilde{C}_k^{\beta_k}(\zeta)}\,>0, \quad \text{for}\, |\zeta|>1,\,k=2,3,4.
\end{equation}
\end{lemma}
%\begin{proof}
The proof of the above lemma in a more general form was given in \cite{HS2024} (Theorem 1), which shows  \eqref{AC_lemma1} and \eqref{AC_lemma2} are true for all $\beta_k > 1$. % {\color{black} We can also provide the proof in Appendix and the proof should be concise if we fix $\beta_2=3,\,\beta_3=6,\,\beta_4=9$ since every term will become explicit number.}
%\end{proof}
\begin{lemma}\label{DC_lemma}
Given $\tilde{D}^{\beta_k}_k(\zeta), \tilde{C}^{\beta_k}_k(\zeta)$ defined in \eqref{ACD_poly}, $\beta_k$ as in \eqref{betak} and $\eta_k=0.71$, we have
\begin{equation}
\rm{gcd}\big(\tilde{D}^{\beta_k}_k(\zeta),\tilde{C}^{\beta_k}_k(\zeta)\big)=1,\, k=2,3,4,
\end{equation}
 i.e. they have no common divisor, and
\begin{equation}
\text{Re}\frac{\tilde{D}_k^{\beta_k}(\zeta)}{\tilde{C}_k^{\beta_k}(\zeta)}\,>0, \quad \text{for}\, |\zeta|>1,\,k=2,3,4.
\end{equation}
\end{lemma}
%\begin{proof}
We shall defer   the proof to  Appendix \ref{app2}.

%\end{proof}
Several remarks are in order.
\begin{itemize}
\item One may choose other forms of  $F_k^{\beta_k}$ in \eqref{fkq}. As long as \eqref{Fk_ineq} with $\kappa_k>0$ and Lemma \ref{DC_lemma} are still true.
%\item In Lemma \ref{DC_lemma}, for the $k$-th ($k=2,3,4$) order schemes, we choose $\beta_k=3, 6, 9$ respectively, which are the minimal integers we can use when fixing $\eta_k(\beta_k)=0.71$ based on our numerical results.
\item {\color{black} For larger values of $\eta_k$, a larger $\beta$ may be required to prove Lemma \ref{DC_lemma}, which in turn introduces a larger truncation error in the scheme. Therefore, we complete the proof by choosing $\eta_k = 0.71$-as small as possible while still satisfying $\eta_k > \frac{\sqrt{2}}{2}$.}
\item $\beta_k$ can also be non-integer, for example, one can prove the above two lemmas by the same processes by choosing $\beta_2=2.9$ for the second order scheme.
\end{itemize}

\subsection{Unconditional stability}
With the help of Lemma \ref{stokespre}--Lemma \ref{DC_lemma}, we can prove the following results for the scheme \eqref{scheme_stoke}.

%We are now ready to state our stability result for \eqref{BDF2NS1}-\eqref{BDF2NS2}.
\begin{theorem} {\color{black} Suppose $\Omega$ satisfies the conditions in Lemma \ref{stokespre}} and given  $\bm u^{i},\, i=1,..,k-1$ such that $\|\nabla \bm u^{i}\|^2+\delta t \|\Delta \bm u^{i}\|^2\le C \|\nabla \bm u^0\|^2,\, i=1,..,k-1$.
The scheme \eqref{scheme_stoke} with {\color{black} $\beta = \beta_k$ }chosen as in \eqref{betak} is unconditionally stable in the sense that, {\color{black} for all $n \ge 0$, we have}
\begin{equation}
\|\nabla \bm u^{n+1}\|^2+\delta t\sum_{i=k-1}^{n}\|\Delta C_k^{\beta_k}(\bm u^{i+1})\|^2+\delta t\sum_{i=0}^{n}\|\Delta \bm u^{i+1}\|^2 +\delta t \sum_{i=0}^{n} \|\nabla p^{i+1}\|^2 \le C,\,k=2,3,4,
\end{equation}
where $C$ is a constant independent of the time step $\delta t$ and $n$.
\end{theorem}

\begin{proof}
%	{\color{black} To simplify the presentation, we shall consider only $\beta= \beta_k$. It is straighforward to extend the results to the cases with $\beta> \beta_k$. {\color{black} remove it?}}

  Taking the inner product of \eqref{scheme_stoke1} with $-\Delta C_k^{\beta_k}(\bm u^{n+1})$, we deal with the three terms as follows. First, we split $B_k^{\beta_k}$ as in \eqref{splitB},
\begin{small}
\begin{equation}\label{eq1}
	\begin{split}
		& \big(-\nu\Delta B_k^{\beta_k}(\bm u^{n+1}),-\Delta C_k^{\beta_k}(\bm u^{n+1}) \big) =\nu \Big(\Delta (\eta_kC_k^{\beta_k}(\bm u^{n+1})+D_k^{\beta_k}(\bm u^{n+1})+F_k^{\beta_k}(\bm u^{n+1})), \Delta C_k^{\beta_k}(\bm u^{n+1}) \Big)\\
		&= \eta_k\nu \|\Delta C_k^{\beta_k}(\bm u^{n+1}) \|^2+\nu \big(\Delta D_k^{\beta_k}(\bm u^{n+1}),\Delta C_k^{\beta_k}(\bm u^{n+1})\big)+\nu \big(\Delta F_k^{\beta_k}(\bm u^{n+1}),\Delta C_k^{\beta_k}(\bm u^{n+1}) \big).
	\end{split}
\end{equation}
\end{small}If we choose $\eta_k=0.71$, it follows from Lemma \ref{Gstability} and Lemma \ref{DC_lemma} that there exists a symmetric positive definite matrix $H_k=(h_{ij})\in \mathbb{R}^{(k-1)\times (k-1)}$ such that
\begin{small}
\begin{equation}
\big(\Delta D_k^{\beta_k}(\bm u^{n+1}),\Delta C_k^{\beta_k}(\bm u^{n+1}) \big) \ge \sum_{i,j=1}^{k-1}h_{ij}(\Delta \bm u^{n+2+i-k},\Delta \bm u^{n+2+j-k})-\sum_{i,j=1}^{k-1}h_{ij}(\Delta \bm u^{n+1+i-k},\Delta \bm u^{n+1+j-k}),
\end{equation}
\end{small}
and \eqref{Fk_ineq} implies that
\begin{small}
\begin{equation}
\big(\Delta F_k^{\beta_k}(\bm u^{n+1}),\Delta C_k^{\beta_k}(\bm u^{n+1}) \big) \ge \kappa_k\|\Delta \bm u^{n+1}\|^2+U_k(\Delta \bm u^{n+1},...,\Delta \bm u^{n+3-k})-U_k(\Delta \bm u^{n},...,\Delta \bm u^{n+2-k}).
\end{equation}
\end{small}For the pressure term,
\begin{equation}\label{eq2}
		\big(\nabla C_k^{\beta_k}(p^n),\Delta C_k^{\beta_k}(\bm u^{n+1})  \big)
		 \le \frac{\gamma}{2\nu} \|\nabla C_k^{\beta_k}(p^n)\|^2+\frac{\nu}{2\gamma}\|\Delta C_k^{\beta_k}(\bm u^{n+1})\|^2,
\end{equation}
with $\gamma$ can be any positive number.
A key step is to deal with the first term in the above using Lemma \ref{stokespre}.
We recall from \cite{liuCPAM} that
\begin{equation}\label{stokesp}
(\nabla p_s(\bm u^n),\nabla q)=-(\nabla\times\nabla\times \bm u^n,\nabla q),
\end{equation}
where $p_s(\bm u^n)$ is the Stokes pressure associated with $\bm u^n$ and it follows from \eqref{scheme_stoke2} that
{\color{black}\begin{equation}\label{BDF2NS3}
\big(\nabla C_k^{\beta_k}(p^n),\nabla q\big)=-\nu\big(\nabla\times\nabla\times C_k^{\beta_k}(\bm u^n),\nabla q\big),\quad\forall q\in H^1(\Omega).
\end{equation}}
Taking $q=C_k^{\beta_k}(p^n)$ in \eqref{BDF2NS3} and in \eqref{stokesp}, we find from \eqref{stokesp} with $\bm u=C_k^{\beta_k}(\bm u^n)$ that
{\color{black}
\begin{equation}\label{stokesp2}
 \|\nabla C_k^{\beta_k}(p^n)\|\le\nu \|\nabla p_s(C_k^{\beta_k}(\bm u^n))\|.
\end{equation}}
Now, we can use \eqref{stokesp2} and \eqref{stokespre2} to bound the first term as follows
\begin{equation}\label{eq3}
\frac{\gamma}{2\nu}	\|\nabla  C_k^{\beta_k}(p^n)\|^2 \le \frac{\gamma\nu}{2} \|\nabla  p_s(C_k^{\beta_k}(\bm u^n))\|^2
	\le \gamma\nu (\frac{1}{4}+\frac{\varepsilon}{2})\| \Delta C_k^{\beta_k}(\bm u^n)\|^2 +C\gamma\nu \|\nabla C_k^{\beta_k}(\bm u^n)\|^2,
\end{equation}
with $\varepsilon >0$ which can be  arbitrarily small.
We observe from \eqref{eq1}-\eqref{eq3} that to ensure stability, we need
\begin{equation}\label{etak_cond}
	\eta_k \ge \mathop{\rm {min}}\limits_{\gamma>0}\big(\frac{1}{2\gamma}+\gamma(\frac{1}{4}+\frac{\varepsilon}{2})\big)\overset{\gamma=\sqrt{2}}{=}\frac{\sqrt{2}}{2}+\frac{\sqrt{2}\varepsilon}{2}.
\end{equation}
As $\varepsilon$ can be chosen arbitrarily small, we only need to choose $\eta_k>\frac{\sqrt{2}}{2}\approx 0.7071$ to ensure \eqref{etak_cond} and that is why we fix $\eta_k=0.71$.
It remains to deal with the last term:
\begin{equation}
	\frac1{\delta t}\big(A_k^{\beta_k}(\bm u^{n+1}),-\Delta C_k^{\beta_k}(\bm u^{n+1}) \big).
\end{equation}
Again, it follows from Lemma \ref{Gstability} and Lemma \ref{AC_lemma} that there exists symmetric positive definite matrix $G_k=(g_{ij})\in \mathbb{R}^{k\times k}$ such that
\begin{equation}\label{eq4}
\big(A_k^{\beta_k}(\bm u^{n+1}),-\Delta C_k^{\beta_k}(\bm u^{n+1}) \big) \ge \sum_{i,j=1}^{k}g_{ij}(\nabla \bm u^{n+1+i-k},\nabla \bm u^{n+1+j-k})-\sum_{i,j=1}^{k}g_{ij}(\nabla \bm u^{n+i-k},\nabla \bm u^{n+j-k}).
\end{equation}


With $\gamma=\sqrt{2}$ and $\eta_k=0.71$, summing up $\delta t(\eqref{eq1}+\eqref{eq2})$  and \eqref{eq4}, using the estimates above,  we find
\begin{small}
\begin{equation}\label{tosumA}
\begin{split}
& \sum_{i,j=1}^{k}g_{ij}(\nabla \bm u^{n+1+i-k},\nabla \bm u^{n+1+j-k})-\sum_{i,j=1}^{k}g_{ij}(\nabla \bm u^{n+i-k},\nabla \bm u^{n+j-k})+\nu \delta t\sum_{i,j=1}^{k-1}h_{ij}(\Delta \bm u^{n+2+i-k},\Delta \bm u^{n+2+j-k})\\
&-\nu\delta t\sum_{i,j=1}^{k-1}h_{ij}(\Delta \bm u^{n+1+i-k},\Delta \bm u^{n+1+j-k})+0.71\nu \delta t\|\Delta C_k^{\beta_k}(\bm u^{n+1}) \|^2+\nu \kappa_k\delta t\|\Delta \bm u^{n+1}\|^2\\
& +\delta t \nu U_k(\Delta \bm u^{n+1},...,\Delta \bm u^{n+3-k})-\delta t \nu U_k(\Delta \bm u^{n},...,\Delta \bm u^{n+2-k})\\
 \le&\frac{\sqrt{2}\nu\delta t}{4}\|\Delta C_k^{\beta_k}(\bm u^{n+1})\|^2+ (\frac{\sqrt{2}}{4}+\frac{\sqrt{2}\varepsilon}{2})\nu\delta t\| \Delta C_k^{\beta_k}(\bm u^n)\|^2 +\sqrt{2}C\nu \delta t\|\nabla C_k^{\beta_k}(\bm u^n)\|^2.
\end{split}
\end{equation}
\end{small}
Now, we can choose $\varepsilon$ small enough such that
\begin{equation}
0.71-\frac{\sqrt{2}}{2}-\frac{\sqrt{2}\varepsilon}{2}=\rho>0,
\end{equation}
 and take the sum of $n$ from $k-1$ to $m\le \frac T{\delta t}-1$ on \eqref{tosumA}. Dropping some unnecessary terms, we obtain
{\color{black} \begin{equation*}
\begin{split}
&  \sum_{i,j=1}^{k}g_{ij}(\nabla \bm u^{m+1+i-k},\nabla \bm u^{m+1+j-k})+ \nu \delta t\sum_{i,j=1}^{k-1}h_{ij}(\Delta \bm u^{m+2+i-k},\Delta \bm u^{n+2+j-k})\\
&+\rho\nu\delta t\sum_{n=k-1}^m\|\Delta C_k^{\beta_k}(\bm u^{n+1})\|^2 +\nu\kappa_k\delta t\sum_{n=k-1}^m\|\Delta \bm u^{n+1}\|^2\\
\le& C \nu \delta t \sum_{n=k-1}^{m} \|\nabla C_k^{\beta_k}(\bm u^{n})\|^2 +C_I\\
\le&C \nu \delta t \sum_{n=0}^{m} \|\nabla \bm u^n\|^2+C_{II},
\end{split}
\end{equation*}
where $C_I$ is a constant depending on $\|\nabla \bm u^{i}\|^2$ and $\delta t \|\Delta \bm u^{i}\|^2,\,i=0,1,...,k-1$.  By the assumption on the initial $k$ steps, we have that $C_{II}$ only depends on $\bm u^0$. One the other hand, let  $\lambda^g_k$ and $\lambda^h_k$ are the smallest eigenvalues of $G_k=(g_{ij})$ and $H_k=(h_{ij})$ respectively, then we have
\begin{small}
\begin{equation*}
\sum_{i,j=1}^{k}g_{ij}(\nabla \bm u^{m+1+i-k},\nabla \bm u^{m+1+j-k})+ \nu \delta t\sum_{i,j=1}^{k-1}h_{ij}(\Delta \bm u^{m+2+i-k},\Delta \bm u^{n+2+j-k}) \ge \lambda^{g}_k\|\nabla \bm u^{m+1}\|^2+\lambda^h_k \nu \delta t \|\Delta \bm u^{m+1}\|^2.
\end{equation*}
\end{small}
Combining the above two inequalities, we have
\begin{equation*}
\begin{split}
&\lambda^{g}_k\|\nabla \bm u^{m+1}\|^2+\lambda^h_k \nu \delta t \|\Delta \bm u^{m+1}\|^2++\rho\nu\delta t\sum_{n=k-1}^m\|\Delta C_k^{\beta_k}(\bm u^{n+1})\|^2 +\nu\kappa_k\delta t\sum_{n=k-1}^m\|\Delta \bm u^{n+1}\|^2\\
\le& C \nu \delta t \sum_{n=0}^{m} \|\nabla \bm u^n\|^2+C_{II}.
\end{split}
\end{equation*}}We can then obtain the desired bound on the velocity by applying Lemma \ref{Gron2} to the above. Finally the bound on the pressure can be derived  by taking $q=p^{n+1}$ in \eqref{BDF2NS2} and {\color{black} using Lemma \ref{stokespre}}.
\end{proof}

%\section{A generalized SAV second-order consistent splitting scheme}
\begin{rem}
	The above theorem provides the first unconditional stability results for any decoupled schemes of third- or higher-order for  time-dependent Stokes equations. It also improves the previous result in \cite{HS2023} for the second-order scheme with $\beta=5$ to $\beta= 3$.
\end{rem}
\section{The BDF-IMEX schemes and  error analysis}
In this section, we construct the $k$-th order  BDF-IMEX schemes  for the Navier-Stokes equations and carry out global-in-time error analysis up to fourth order scheme by induction.

\subsection{A general form of  BDF-IMEX schemes}

 Combining the new BDF type scheme with the consistent splitting schemes in \cite{Shen03JCP}, using the notations introduced in \eqref{ABC_def} and choosing $\beta_k$ as \eqref{betak}, we construct the  $k$-th $(k=2,3,4)$ order schemes for  \eqref{NS} as follows:
 \begin{subequations}\label{scheme_NS}
\begin{align}
&\frac{A_k^{\beta_k}(\bm u^{n+1})}{\delta t}-\nu \Delta B_k^{\beta_k}(\bm u^{n+1})+\nabla C_k^{\beta_k}(p^{n})+C_k^{\beta_k}(\bm u^n)\cdot \nabla C_k^{\beta_k}(\bm u^n)=\bm f^{n+\beta_k}, \label{scheme_NS1}\\
&(\nabla p^{n+1},\nabla q)=(\bm f^{n+1}-\bm u^{n+1} \cdot \nabla \bm u^{n+1}-\nu \nabla\times\nabla\times \bm u^{n+1},\nabla q),\quad\forall q\in H^1(\Omega).\label{scheme_NS2}
\end{align}
\end{subequations}






\subsection{Error analysis}

To simplify the presentation, we take $\nu=1$ in \eqref{scheme_NS1} and denote
\begin{equation*}
t^n=n\,\delta t,\quad  \bm e^n=\bm u^n-\bm u(\cdot, t^n),\quad e_p^n=p^n-p(\cdot,t^n).
\end{equation*}


\begin{theorem}\label{ThmNS}
Let {\color{black} $\Omega \subset \mathbb{R}^d$ satisfies the conditions in Lemma \ref{stokespre},} $d=2,3$, $T>0$, $\bm u_0\in \mathbb{V} \cap \bm H_0^2$ and $\bm u$ be the solution of \eqref{NS}. Assuming that $\|\bm f(\cdot,t)\| \le C_f, \, \forall t \in[0, T]$ and  $\bm u^{i}$ are computed  such that $\|\nabla \bm e^{i}\|^2+\delta t \|\Delta \bm e^{i}\|^2\le C\delta t^{2k} \|\nabla \bm u^0\|^2,\, {\color{black}i=0,..,k-1}$.
Let $\bm u^j \,(j\ge k)$ be the solution of  \eqref{scheme_NS} with {\color{black} $\beta= \beta_k$} chosen as in \eqref{betak}, and
  assume that the exact solutions are sufficiently smooth such that
\begin{equation}\label{NScond2}
\bm u \in L^2(0,T;H^2),\quad \frac{\partial ^{k} \bm u}{\partial t^{k}} \in L^2(0,T;H^2),\quad \frac{\partial ^{k+1} \bm u}{\partial t^{k+1}} \in L^2(0,T;L^2),\quad \frac{\partial ^{k} p}{\partial t^{k}} \in L^2(0,T;H^1).
\end{equation}
Then for  $n+1 \le T/\delta t$ with $\delta t$ sufficiently small, we have
\begin{equation}\label{Thmerror}
\|\nabla \bm e^{n+1}\|^2+\delta t \sum_{i=0}^{n+1}(\|\Delta {\bm e}^i\|^2+\|\nabla e_p^i\|^2 ) \le C\delta t^{2k},
\end{equation}
where the constants  $C$ are dependent on $T,\, \Omega$ and  the exact solution $\bm u$, but are independent of $\delta t$.

\end{theorem}
\begin{proof}
%		{\color{black} As in the previous section, we shall consider only $\beta= \beta_k$. It is straightforward to extend the results to the cases with $\beta> \beta_k$. {\color{black} remove it?}}

Since our focus is on the error analysis for the semi-discrete scheme,  we assume $\bm f^i=\bm f(t^i) \;\forall i,$ and $\bm u^i,\, p^i,\,i\le k-1$ are  computed with proper initialization procedure such that \eqref{Thmerror} holds {\color{black} for $n \le k-1$}.

Firstly, we denote
\begin{equation}\label{C0def}
C_{H^1}:= \mathop{\rm max}\limits_{0\le t \le T} \|\nabla \bm u(\cdot,t)\|\,\, {\rm and} \,\, C_0:=C_{H^1}+1.
\end{equation}
We need to prove a uniform bound of $\|\nabla \bm u^n\|$ by induction,
\begin{equation}\label{C0}
\|\nabla \bm u^i\| \le C_0, \quad  \forall  i\le T/{\delta t},
\end{equation}
 In the following, we shall use $C$ to denote a positive constant independent of  $\delta t$, % {\color{black} (Actually, $C$ can also depend on $C_0$ since we have explicitly defined $C_0$)},
  which can change from one step to another and we use $\varepsilon>0$ to denote a constant which can be arbitrarily small.

Under the assumption,  \eqref{C0} certainly holds for $i=0$. Now
suppose we have
\begin{equation}\label{H1boundpre}
\|\nabla \bm u^i\| \le C_0,\,\, \forall i \le n,
\end{equation}
we shall prove below
\begin{equation}\label{H1bound}
\|\nabla \bm u^{n+1}\| \le C_0,
\end{equation}
for the same constant $C_0$.

\textbf{Step 1: Bounds for $\delta t \sum_{q=0}^i \|\Delta \bm u^q\|^2$,  $\forall i\le n$.}
Considering \eqref{scheme_NS1} at step $i+1 \le n$ and taking the inner product with $-\delta t \Delta C_k^{\beta_k}({\bm u}^{i+1})$. For the first term on the left hand side, it follows from Lemma \ref{Gstability} and Lemma \ref{AC_lemma} that there exists a symmetric positive definite matrix $G_k=(g_{lj})\in \mathbb{R}^{k\times k}$ such that
\begin{equation}\label{AC_error}
\big(A_k^{\beta_k}({\bm u}^{i+1}),-\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big) \ge \sum_{l,j=1}^{k}g_{lj}(\nabla {\bm u}^{i+1+l-k},\nabla {\bm u}^{i+1+j-k})-\sum_{l,j=1}^{k}g_{lj}(\nabla {\bm u}^{i+l-k},\nabla {\bm u}^{i+j-k}).
\end{equation}

For the second term, we split $B_k^{\beta_k}({\bm u}^{i+1})$ as \eqref{splitB} and choose $\eta_k=0.71$, then we have
\begin{equation}\label{B_error}
\begin{split}
\delta t \big(-\Delta B_k^{\beta_k}({\bm u}^{i+1}),-\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big)
& = 0.71\delta t \|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2+\delta t\big(\Delta D_k^{\beta_k}({\bm u}^{i+1}),\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big)\\
& + \delta t\big(\Delta F_k^{\beta_k}({\bm u}^{i+1}),\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big),
\end{split}
\end{equation}
and for $\big(\Delta D_k^{\beta_k}({\bm u}^{i+1}),\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big) $, thanks to Lemma \ref{Gstability} and Lemma \ref{DC_lemma}, there exists a symmetric positive definite matrix $H_k=(h_{lj})\in \mathbb{R}^{(k-1)\times (k-1)}$ such that
\begin{equation}\label{DC_error}
\big(\Delta D_k^{\beta_k}({\bm u}^{i+1}),\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big) \ge \sum_{l,j=1}^{k-1}h_{lj}(\Delta {\bm u}^{i+2+l-k},\Delta {\bm u}^{i+2+j-k})-\sum_{l,j=1}^{k-1}h_{lj}(\Delta {\bm u}^{i+1+l-k},\Delta {\bm u}^{i+1+j-k}),
\end{equation}
and for $\big(\Delta F_k^{\beta_k}({\bm u}^{i+1}),\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big)$, \eqref{Fk_ineq} implies
\begin{equation}\label{Fk_error}
\big(\Delta F_k^{\beta_k}({\bm u}^{i+1}),\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big) \ge \kappa_k \|\Delta {\bm u}^{i+1}\|^2+U_k(\Delta {\bm u}^{i+1},...,\Delta {\bm u}^{i+3-k})-U_k(\Delta {\bm u}^{i},...,\Delta {\bm u}^{i+2-k}).
\end{equation}
For the term with $C_k^{\beta_k}(\bm u^i) \cdot \nabla C_k^{\beta_k}(\bm u^i) $, making use of \eqref{eq:ineq2d} and the Poincar\'e type inequality, we have
\begin{equation}\label{NL2D}
\begin{split}
&\big(C_k^{\beta_k}(\bm u^i) \cdot \nabla C_k^{\beta_k}(\bm u^i) , \Delta C_k^{\beta_k}({\bm u}^{i+1}) \big)  \\
\le &\Big| \big(C_k^{\beta_k}({\bm u}^i)\cdot \nabla C_k^{\beta_k}({\bm u}^i), \Delta C_k^{\beta_k}({\bm u}^{i+1}) \big)\Big| \\
\le& c\|C_k^{\beta_k}({\bm u}^i)\|_1 \|C_k^{\beta_k}({\bm u}^i)\|_1^{1/2}\|C_k^{\beta_k}({\bm u}^i)\|_2^{1/2}\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|\\
\le &C(\varepsilon)\|C_k^{\beta_k}({\bm u}^i)\|_1^2\|C_k^{\beta_k}({\bm u}^i)\|_1\|C_k^{\beta_k}({\bm u}^i)\|_2+\varepsilon\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2\\
\le &C(\varepsilon)\|\nabla C_k^{\beta_k}({\bm u}^i)\|^6+\varepsilon\|\Delta C_k^{\beta_k}({\bm u}^{i})\|^2+\varepsilon\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2,
\end{split}
\end{equation}where we used  $\|C_k^{\beta_k}({\bm u}^i)\|_2^2 \le C\|\Delta C_k^{\beta_k}({\bm u}^i)\|^2$ in the last step.

For the term with $C_k^{\beta_k}(p^i)$, we have
\begin{equation}\label{eq:pterm}
\Big|\big( \nabla C_k^{\beta_k}(p^i), -\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big)\Big| \le \|\nabla C_k^{\beta_k}(p^i)\|\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|.
\end{equation}

To estimate $\|\nabla C_k^{\beta_k}(p^i)\|$, we  follow a similar procedure as in \cite{liuCPAM}: first rewriting \eqref{scheme_NS2} as
\begin{equation}\label{NSb22}
\big(\nabla p^{i}, \nabla q \big)=\big(\bm f^{i}-{\bm u}^{i} \cdot \nabla {\bm u}^{i}, \nabla q \big)+ \big( \nabla p_s({\bm u}^{i}), \nabla q \big), \quad \forall i \le n,
\end{equation}
where $p_s({\bm u}^{i})$ is the Stokes pressure associated with ${\bm u}^{i}$ and hence
\begin{equation}\label{pressure}
\big(\nabla C_k^{\beta_k}(p^i), \nabla q \big)=\big(C_k^{\beta_k}(\bm f^i)-C_k^{\beta_k}({\bm u}^i\cdot \nabla {\bm u}^i), \nabla q \big)+ \big( \nabla p_s(C_k^{\beta_k}({\bm u}^i)), \nabla q \big).
\end{equation}
Now, taking $q=C_k^{\beta_k}(p^i)$, we have
\begin{equation}
    \|\nabla C_k^{\beta_k}(p^i)\|  \le \|C_k^{\beta_k}(\bm f^i)-C_k^{\beta_k}({\bm u}^i\cdot \nabla {\bm u}^i)\|+\|\nabla p_s(C_k^{\beta_k}({\bm u}^i))\|.
\end{equation}

It follows from  the Sobolev inequality and the elliptic regularity estimate that
\begin{equation}\label{fNL2D}
\begin{split}
 \|C_k^{\beta_k}(\bm f^i)-C_k^{\beta_k}({\bm u}^i\cdot \nabla {\bm u}^i)\|^2
& \le C\sum_{q=0}^{k-1}\|{\bm f}^{i-q}\|^2+C\sum_{q=0}^{k-1}\|{\bm u}^{i-q}\cdot \nabla {\bm u}^{i-q}\|^2\\
& \le C\sum_{q=0}^{k-1}\|{\bm f}^{i-q}\|^2+C\sum_{q=0}^{k-1}\|\nabla {\bm u}^{i-q}\|^3\| \nabla {\bm u}^{i-q}\|_1\\
& \le C\sum_{q=0}^{k-1}\|{\bm f}^{i-q}\|^2+C(\varepsilon)\sum_{q=0}^{k-1}\|\nabla {\bm u}^{i-q}\|^6+\varepsilon\sum_{q=0}^{k-1}\|\Delta {\bm u}^{i-q}\|^2,
\end{split}
\end{equation}
{\color{black} where  we used the following inequality (cf. section 4 in \cite{liuCPAM}),
\begin{equation*}
\|\bm u^i\cdot \nabla \bm u^i\|^2\le \|\bm u^i\|^2_{L^6}\|\nabla \bm u^i\|^2_{L^3} \le C\|\nabla \bm u^i\|^3\|\nabla \bm u^i\|_1, \quad d=2,3.
\end{equation*}}
As a result,  by making use of Lemma \ref{stokespre}, we can estimate \eqref{eq:pterm} as
\begin{equation}
\begin{split}
& \big(\nabla C_k^{\beta_k}(p^i), -\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big) \\
\le &\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|\big( \|C_k^{\beta_k}(\bm f^i)-C_k^{\beta_k}({\bm u}^i\cdot \nabla {\bm u}^i)\|+\|\nabla p_s(C_k^{\beta_k}({\bm u}^i))\| \big) \\
\le &C(\varepsilon)\|C_k^{\beta_k}(\bm f^i)-C_k^{\beta_k}({\bm u}^i\cdot \nabla {\bm u}^i)\|^2+\varepsilon\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2 +\frac{\gamma}{2}\|\nabla p_s(C_k^{\beta_k}({\bm u}^i))\|^2+\frac{1}{2\gamma}\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2\\
\le & C(\varepsilon) \sum_{q=0}^{k-1}\big(\|{\bm f}^{i-q}\|^2+\|\nabla {\bm u}^{i-q}\|^6 \big)+\varepsilon( \sum_{q=0}^{k-1}\|\Delta {\bm u}^{i-q}\|^2+\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2)\\
& +\gamma(\frac{1}{4}+\frac{\varepsilon}{2})\|\Delta C_k^{\beta_k}({\bm u}^i)\|^2+C(\varepsilon)\|\nabla C_k^{\beta_k}({\bm u}^i)\|^2+\frac{1}{2\gamma}\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2.
\end{split}
\end{equation}
with $\gamma$ can be any positive number.

Finally, for the right hand side of \eqref{scheme_NS1}, we have
\begin{equation}\label{rhs1}
\big( \bm f^{i+\beta_k}, -\Delta C_k^{\beta_k}({\bm u}^{i+1}) \big ) \le C(\varepsilon) \|\bm f^{i+\beta_k}\|^2+\varepsilon\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2.
\end{equation}

Combining \eqref{AC_error} to \eqref{rhs1} and choosing $\gamma=\sqrt{2}$ as before, we obtain
\begin{small}
\begin{equation}\label{tosum}
\begin{split}
& \sum_{l,j=1}^{k}g_{lj}(\nabla {\bm u}^{i+1+l-k},\nabla {\bm u}^{i+1+j-k})-\sum_{l,j=1}^{k}g_{lj}(\nabla {\bm u}^{i+l-k},\nabla {\bm u}^{i+j-k})+\delta t\sum_{l,j=1}^{k-1}h_{lj}(\Delta {\bm u}^{i+2+l-k},\Delta {\bm u}^{i+2+j-k})\\
&-\delta t\sum_{l,j=1}^{k-1}h_{lj}(\Delta {\bm u}^{i+1+l-k},\Delta {\bm u}^{i+1+j-k})+0.71 \delta t\|\Delta C_k^{\beta_k}({\bm u}^{i+1}) \|^2 +\kappa_k \delta t\|\Delta {\bm u}^{i+1}\|^2\\
& +\delta tU_k(\Delta {\bm u}^{i+1},...,\Delta {\bm u}^{i+3-k})-\delta tU_k(\Delta {\bm u}^{i},...,\Delta {\bm u}^{i+2-k})\\
 \le &C(\varepsilon)\delta t \Big(\sum_{q=0}^{k-1}\big(\|{\bm f}^{i-q}\|^2+\|\nabla {\bm u}^{i-q}\|^6 \big)+\|\bm f^{i+\beta_k}\|^2 +\|\nabla C_k^{\beta_k}({\bm u}^i)\|^2+\|\nabla C_k^{\beta_k}({\bm u}^i)\|^6\Big)\\
&+\delta t \varepsilon( \sum_{q=0}^{k-1}\|\Delta {\bm u}^{i-q}\|^2+\|\Delta C_k^{\beta_k}({\bm u}^{i})\|^2+\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2)
+(\frac{\sqrt{2}}{4}+\frac{\sqrt{2}\varepsilon}{2})\delta t \|\Delta C_k^{\beta_k}({\bm u}^i)\|^2\\
&+\frac{\sqrt{2}}{4}\delta t\|\Delta C_k^{\beta_k}({\bm u}^{i+1})\|^2.
\end{split}
\end{equation}
\end{small}

%{\color{black}We can see the reason why we need to split $B_k^{\beta_k}$ like \eqref{splitB} from \eqref{tosum}: $\|\Delta C_k^{\beta_k}(\bm u^i)\|^2 $ is not enough to control $\varepsilon\|\Delta \bm u^i\|^2$ even $\varepsilon$ can be arbitrarily small and hence the term with coefficient $\kappa_k$ is necessary.}

Now, we can choose $\varepsilon$ small enough such that there exists $\rho>0$ such that
\begin{equation}\label{epsilon}
0.71  -( \frac{\sqrt{2}}{2}+\frac{\sqrt{2}\varepsilon}{2}+2\varepsilon) \ge \rho>0 \quad \text{and} \quad \kappa_k- k\varepsilon \ge \rho>0.
\end{equation}
Then taking the sum on \eqref{tosum} for $i$ from $k-1$ to $m-1$ with $m \le n$ and dropping some unnecessary terms, we can obtain:
\begin{small}
\begin{equation}\label{eq:sum}
\begin{split}
& \lambda_k^g\|\nabla {\bm u}^{m}\|^2+\rho \delta t \sum_{i=k}^{m}(\|\Delta C_k^{\beta_k}({\bm u}^i)\|^2+\|\Delta {\bm u}^{i}\|^2) \\
\le &C\delta t \sum_{i=k-1}^{m-1}\big(\|\nabla {\bm u}^i\|^6+\|\nabla C_{k}^{\beta_k}({\bm u}^i)\|^{\color{black}6}\big)+C\delta t \sum_{i=k-1}^{m-1}\|\nabla C_k^{\beta_k}({\bm u}^i)\|^2 +C\delta t\sum_{i=k-1}^{m-1} (\|\bm f^i\|^2+\|\bm f^{i+\beta_k}\|^2)+M_0\\
\le & C\delta t \sum_{i=0}^{m-1}\|\nabla {\bm u}^i\|^6+C\delta t \sum_{i=0}^{m-1}\|\nabla {\bm u}^i\|^2+CTC_f^2+M_0,\quad \forall m \le n,
\end{split}
\end{equation}
\end{small}where $\lambda_k^g>0$ is the smallest eigenvalue of $G_k=(g_{lj})$, $M_0$ is a constant only depends on the data from initial $k-1$ steps and we used $\|\bm f(\cdot,t)\| \le C_f, \, \forall t \in[0, T]$. Next, noting that $\|\nabla {\bm u}^i\| \le C_0,\,\forall i \le n$ under the induction assumption {\color{black} and $C_0>1$ from \eqref{C0def}}, we can obtain from \eqref{eq:sum}:
\begin{equation}\label{H2bound}
\|\nabla {\bm u}^{m}\|^2+\delta t \sum_{i=k}^{m}(\|\Delta C_k^{\beta_k}({\bm u}^i)\|^2+\|\Delta {\bm u}^{i}\|^2) \le CT(C_0^6+C_f^2)+M_0, \quad \forall m\le n.
\end{equation}

\textbf{Step 2: Error estimate for $\|\nabla {\bm e}^{n+1}\|$.}
From \eqref{NS} and \eqref{scheme_NS}, we can write down the error equation for ${\bm u}^{i+1}$ and $p^{i+1}$ as
\begin{equation}\label{NSerror}
\begin{split}
& A_k^{\beta_k}({\bm e}^{i+1})-\delta t\Delta B_k^{\beta_k}({\bm e}^{i+1})+\delta t(C_k^{\beta_k}({\bm u}^i) \cdot \nabla C_k^{\beta_k}({\bm u}^i)-C_k^{\beta_k}[{\bm u}(t^{i})]\cdot \nabla C_k^{\beta_k}[{\bm u}(t^{i})])+\delta t\nabla C_k^{\beta_k}({e}_p^i)\\
&=\delta t P_k^i+\delta tQ_k^i+R_k^i+\delta tS_k^i,
\end{split}
\end{equation}
where $P_k^i$, $Q_k^i$, $R_k^i$ $S_k^i$ are given by
\begin{equation}\label{P}
P_k^i= \nabla p(t^{i+\beta_k})-\nabla C_k^{\beta_k}(p(t^i))=\frac{1}{(k-1)!}\sum_{q=0}^{k-1}c_{k,q}(\beta_k)\int_{t^{i+1+q-k}}^{t^{i+\beta_k}}(t^{i+1+q-k}-s)^{k-1}\nabla \frac{\partial^k p}{\partial t^k}(s)ds,
\end{equation}
with $c_{k,q}(\beta_k)$ defined in \eqref{TaylorC} and
\begin{equation}\label{Q}
Q_k^i=- \Delta \bm u (t^{i+\beta_k})+\Delta B_k^{\beta_k} (\bm u(t^{i+1}))
=\frac{-1}{(k-1)!}\sum_{q=0}^{k-1}b_{k,q}(\beta_k)\int_{t^{i+2+q-k}}^{t^{i+\beta_k}}(t^{i+2+q-k}-s)^{k-1}\Delta  \frac{\partial^k \bm u}{\partial t^k}(s)ds,
\end{equation}
\begin{equation}\label{R}
\begin{split}
R_k^i=\delta t \bm u_t(t^{i+\beta_k})-A_k^{\beta_k}(\bm u(t^{i+1}))=\frac{1}{k!}\sum_{q=0}^{k}a_{k,q}(\beta_k)\int_{t^{i+1+q-k}}^{t^{i+\beta_k}}(t^{i+1+q-k}-s)^{k} \frac{\partial^{k+1} \bm u}{\partial t^{k+1}}(s)ds,
\end{split}
\end{equation}
and
\begin{equation}\label{S}
\begin{split}
S_k^i& =\bm u(t^{i+\beta_{k}})\cdot \nabla \bm u(t^{i+\beta_k})-C_k^{\beta_k}[\bm u(t^i)] \cdot \nabla C_k^{\beta_k}[\bm u(t^i)]\\
&=\bm u(t^{i+\beta_k})\cdot \nabla (\bm u(t^{i+\beta_k})-C_k^{\beta_k}[{\bm u}(t^i)])-(C_k^{\beta_k}[{\bm u}(t^i)]-\bm u(t^{i+\beta_k})) \cdot \nabla C_k^{\beta_k}[\bm u(t^i)].
\end{split}
\end{equation}
Next, we take the inner product of  \eqref{NSerror} with $-\Delta C_k^{\beta_k}({\bm e}^{i+1})$. For the first term on the left hand side, same as \eqref{AC_error}, we have
\begin{equation}\label{AC_error2}
\big(A_k^{\beta_k}({\bm e}^{i+1}),-\Delta C_k^{\beta_k}({\bm e}^{i+1}) \big) \ge \sum_{l,j=1}^{k}g_{lj}(\nabla {\bm e}^{i+1+l-k},\nabla {\bm e}^{i+1+j-k})-\sum_{l,j=1}^{k}g_{lj}(\nabla {\bm e}^{i+l-k},\nabla {\bm e}^{i+j-k}).
\end{equation}
We handle the term  with $B_k^{\beta_k}({\bm e}^{i+1})$ similarly  as in  \eqref{B_error}-\eqref{Fk_error} to obtain,
\begin{equation}\label{BC_error}
\begin{split}
&\delta t\big(-\Delta B_k^{\beta_k}({\bm e}^{i+1}) ,-\Delta C_k^{\beta_k}({\bm e}^{i+1}) \big) \\
 \ge & 0.71\delta t\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|{\color{black}^2}+\kappa_k \delta t\|\Delta {\bm e}^{i+1}\|^2 + \delta t\sum_{l,j=1}^{k-1}h_{lj}(\Delta {\bm e}^{i+2+l-k},\Delta {\bm e}^{i+2+j-k})\\
&-\delta t\sum_{l,j=1}^{k-1}h_{lj}(\Delta {\bm e}^{i+1+l-k},\Delta {\bm e}^{i+1+j-k})+\delta tU_k(\Delta {\bm e}^{i+1},...,\Delta {\bm e}^{i+3-k})-\delta t U_k(\Delta {\bm e}^{i},...,\Delta {\bm e}^{i+2-k}).
\end{split}
\end{equation}
For the third term on the left hand side of \eqref{NSerror}, we rewrite it as
\begin{equation}\label{eq:split}
\begin{split}
& C_k^{\beta_k}({\bm u}^i) \cdot \nabla C_k^{\beta_k}({\bm u}^i)-C_k^{\beta_k}[{\bm u}(t^{i})]\cdot \nabla C_k^{\beta_k}[{\bm u}(t^{i})] \\ =&C_k^{\beta_k}({\bm u}^i) \cdot \nabla C_k^{\beta_k}({\bm u}^i)-C_k^{\beta_k}[{\bm u}(t^{i})] \cdot \nabla C_k^{\beta_k}({\bm u}^i)+C_k^{\beta_k}[{\bm u}(t^{i})]\cdot \nabla C_k^{\beta_k}({\bm u}^i)-C_k^{\beta_k}[{\bm u}(t^{i})]\cdot \nabla C_k^{\beta_k}[{\bm u}(t^{i})]\\
=& C_k^{\beta_k}({\bm e}^i) \cdot \nabla C_k^{\beta_k}({\bm u}^i)+ C_k^{\beta_k}[{\bm u}(t^{i})] \cdot \nabla C_k^{\beta_k}({\bm e}^i).
\end{split}
\end{equation}
Therefore, it follows from \eqref{eq:ineq2} that
\begin{equation}
\begin{split}
&\big(C_k^{\beta_k}({\bm u}^i) \cdot \nabla C_k^{\beta_k}({\bm u}^i)-C_k^{\beta_k}[{\bm u}(t^{i})]\cdot \nabla C_k^{\beta_k}[{\bm u}(t^{i})], -\Delta C_k^{\beta_k}({\bm e}^{i+1}) \big)\\
=&\big(C_k^{\beta_k}({\bm e}^i) \cdot \nabla C_k^{\beta_k}({\bm u}^i),  -\Delta C_k^{\beta_k}({\bm e}^{i+1})  \big)+\big(C_k^{\beta_k}[{\bm u}(t^{i})] \cdot \nabla C_k^{\beta_k}({\bm e}^i), -\Delta C_k^{\beta_k}({\bm e}^{i+1})  \big)\\
 \le& C\|\nabla C_k^{\beta_k}({\bm e}^i)\|\|C_k^{\beta_k}({\bm u}^i)\|_2\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|+C\|C_k^{\beta_k}[{\bm u}(t^{i})]\|_2\|\nabla C_k^{\beta_k}({\bm e}^i)\|\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|\\
\le& C(\varepsilon)\|\nabla C_k^{\beta_k}({\bm e}^i)\|^2\|\Delta C_k^{\beta_k}({\bm u}^i)\|^2+C(\varepsilon)\|C_k^{\beta_k}[{\bm u}(t^{i})]\|_2^2\|\nabla C_k^{\beta_k}({\bm e}^i)\|^2+\varepsilon\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2.\\
\end{split}
\end{equation}

For the term with $C_k^{\beta_k}({e}_p^i)$, we have
\begin{equation}\label{ep1}
\big(\nabla C_k^{\beta_k}({e}_p^i), -\Delta  C_k^{\beta_k}({\bm e}^{i+1}) \big) \le  \|\nabla C_k^{\beta_k}({e}_p^i)\|\|\Delta  C_k^{\beta_k}({\bm e}^{i+1})\|.
\end{equation}
To estimate $\|\nabla C_k^{\beta_k}({e}_p^i)\|$, same as in the last step, we make use of the Stokes pressure. First, from \eqref{scheme_NS2}, the error equation for $e_p^i$ can be rewritten as
\begin{equation}\label{errorp0}
(\nabla {e}_p^{i}, \nabla q)=\big({\bm u}(t^{i}) \cdot \nabla {\bm u}(t^{i})-{\bm u}^{i}\cdot \nabla {\bm u}^{i}, \nabla q \big)+ (\nabla p_s( {\bm e}^{i}), \nabla q),
\end{equation}
and hence,
\begin{equation}\label{errorp}
(\nabla C_k^{\beta_k}({e}_p^i), \nabla q)=\Big(C_k^{\beta_k}\big({\bm u}(t^{i}) \cdot \nabla {\bm u}(t^{i})-{\bm u}^{i}\cdot \nabla {\bm u}^{i}\big), \nabla q\Big)+ (\nabla p_s(C_k^{\beta_k}({\bm e}^{i})), \nabla q),
\end{equation}
where $p_s(C_k^{\beta_k}({\bm e}^{i}))$ is the Stokes pressure associated with $C_k^{\beta_k}({\bm e}^{i})$. We let $q=C_k^{\beta_k}({e}_p^i)$ in the above to obtain
\begin{equation}\label{ep}
\|\nabla C_k^{\beta_k}({e}_p^i)\| \le \|C_k^{\beta_k}({\bm u}(t^{i}) \cdot \nabla {\bm u}(t^{i})-{\bm u}^{i}\cdot \nabla {\bm u}^{i})\|+\|\nabla p_s(C_k^{\beta_k}({\bm e}^{i}))\|.
\end{equation}
Similarly as in \eqref{eq:split}, we  rewrite
\begin{equation}
{\bm u}(t^{i}) \cdot \nabla {\bm u}(t^{i})-{\bm u}^{i}\cdot \nabla {\bm u}^{i}=- {\bm e}^i \cdot \nabla {\bm u}^i-\bm u(t^i) \cdot \nabla {\bm e}^i,
\end{equation}
then it follows from the Sobolev inequality and the Poincar\'e type inequality that
\begin{equation}\label{pnon1}
 \|C_k^{\beta_k}({\bm u}(t^{i}) \cdot \nabla {\bm u}(t^{i})-{\bm u}^{i}\cdot \nabla {\bm u}^{i})\|^2 \le C \sum_{q=0}^{k-1}(\|\nabla {\bm e}^{i-q}\|^2\|\Delta {\bm u}^{i-q}\|^2+\|\bm u(t^{i-q})\|_2^2\|\nabla {\bm e}^{i-q}\|^2).
\end{equation}
Now, combining \eqref{ep1} to \eqref{pnon1} and making use of Lemma \ref{stokespre} for the Stokes pressure, we can bound the term with $C_k^{\beta_k}({e}_p^i)$ as
\begin{equation}\label{ptermbound}
\begin{split}
& \big(\nabla C_k^{\beta_k}({e}_p^i), -\Delta  C_k^{\beta_k}({\bm e}^{i+1}) \big) \\
\le &\|C_k^{\beta_k}\big({\bm u}(t^{i}) \cdot \nabla {\bm u}(t^{i})-{\bm u}^{i}\cdot \nabla {\bm u}^{i}\big)\|\|\Delta  C_k^{\beta_k}({\bm e}^{i+1})\|+  \|\nabla p_s(C_k^{\beta_k}({\bm e}^{i}))\|\|\Delta  C_k^{\beta_k}({\bm e}^{i+1})\| \\
\le& C(\varepsilon)\|C_k^{\beta_k}({\bm u}(t^{i}) \cdot \nabla {\bm u}(t^{i})-{\bm u}^{i}\cdot \nabla {\bm u}^{i})\|^2+\varepsilon\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2+ \frac{\gamma}{2}\|\nabla p_s(C_k^{\beta_k}({\bm e}^{i}))\|^2+\frac{1}{2\gamma}\|\Delta  C_k^{\beta_k}({\bm e}^{i+1})\|^2\\
 \le& C(\varepsilon)\sum_{q=0}^{k-1}\|\nabla {\bm e}^{i-q}\|^2(\|\Delta {\bm u}^{i-q}\|^2+\|\bm u(t^{i-q})\|_2^2)
 +(\varepsilon+\frac{1}{2\gamma})\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2+\gamma(\frac{1}{4}+\frac{\varepsilon}{2})\|\Delta C_k^{\beta_k}({\bm e}^{i})\|^2\\
 &+C(\varepsilon)\|\nabla C_k^{\beta_k}({\bm e}^{i})\|^2.
\end{split}
\end{equation}
For the right hand side of \eqref{NSerror}, we derive from \eqref{P}-\eqref{R} that
\begin{equation}\label{Pbound}
\begin{split}
(P_k^i, -\Delta  C_k^{\beta_k}({\bm e}^{i+1})) & \le C(\varepsilon)\|P_k^i\|^2+\varepsilon\|\Delta  C_k^{\beta_k}({\bm e}^{i+1})\|^2 \\
& \le C(\varepsilon)\delta t^{2k-1} \int_{t^{i+1-k}}^{t^{i+\beta_k}}\Big{\|}\nabla \frac{\partial ^k p}{\partial t^k}(s)\Big{\|}^2 ds+\varepsilon\|\Delta  C_k^{\beta_k}({\bm e}^{i+1})\|^2,
\end{split}
\end{equation}
and similarly,
\begin{equation}\label{Qbound}
(Q_k^i, -\Delta  C_k^{\beta_k}({\bm e}^{i+1})) \le C(\varepsilon)\delta t^{2k-1}\int_{t^{i+2-k}}^{t^{i+\beta_k}}\Big{\|}\Delta \frac{\partial ^k \bm u}{\partial t^k}(s)\Big{\|}^2 ds+\varepsilon\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2,
\end{equation}
\begin{equation}\label{Rbound}
\begin{split}
(R_k^i, -\Delta  C_k^{\beta_k}({\bm e}^{i+1})) & \le \frac{C(\varepsilon)}{\delta t}\|R_k^i\|^2+\varepsilon \delta t\| \Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2 \\
&\le  C(\varepsilon)\delta t^{2k} \int_{t^{i+1-k}}^{t^{i+\beta_k}}\Big{\|}\frac{\partial ^{k+1} \bm u}{\partial t^{k+1}}\Big{\|}^2 ds+\varepsilon\delta t \|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2.
\end{split}
\end{equation}
For the term with $S_k^i$, it follows from \eqref{eq:ineq2} and \eqref{S} that
\begin{equation}\label{Sbound}
\begin{split}
&(S_k^i, -\Delta  C_k^{\beta_k}({\bm e}^{i+1})) \\
 \le &C \|\bm u(t^{i+\beta_k})\|_2\|\nabla(\bm u(t^{i+\beta_k})-C_k^{\beta_k}[{\bm u}(t^i)]\|\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|\\
& + C \|C_k^{\beta_k}[{\bm u}(t^{i})]\|_2\|\nabla(\bm u(t^{i+\beta_k})-C_k^{\beta_k}[\bm u(t^i)])\|\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|\\
\le& C(\varepsilon)(\|\bm u(t^{i+\beta_k})\|_2^2+\|C_k^{\beta_k}[\bm u(t^i)]\|_2^2)\|\nabla(\bm u(t^{i+\beta_k})-C_k^{\beta_k}[\bm u(t^i)]\|^2+\varepsilon \|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2\\
\le &C(\varepsilon)\delta t^{2k-1}\int_{t^{i+1-k}}^{t^{i+\beta_k}}\Big{\|} \nabla \frac{\partial ^k \bm u}{\partial t^k}(s)\Big{\|}^2 ds+\varepsilon \|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2.
\end{split}
\end{equation}
Now, we combine \eqref{AC_error2} to \eqref{Sbound}, choose $\gamma=\sqrt{2}$ and drop some unnecessary terms to obtain
\begin{small}
\begin{equation}\label{tosum2}
\begin{split}
& \sum_{l,j=1}^{k}g_{lj}(\nabla {\bm e}^{i+1+l-k},\nabla {\bm e}^{i+1+j-k})-\sum_{l,j=1}^{k}g_{lj}(\nabla {\bm e}^{i+l-k},\nabla {\bm e}^{i+j-k})+\delta t\sum_{l,j=1}^{k-1}h_{lj}(\Delta {\bm e}^{i+2+l-k},\Delta {\bm e}^{i+2+j-k})\\
&-\delta t\sum_{l,j=1}^{k-1}h_{lj}(\Delta {\bm e}^{i+1+l-k},\Delta {\bm e}^{i+1+j-k})+0.71 \delta t\|\Delta C_k^{\beta_k}({\bm e}^{i+1}) \|^2 +\kappa_k \delta t\|\Delta {\bm e}^{n+1}\|^2\\
& +\delta tU_k(\Delta {\bm e}^{i+1},...,\Delta {\bm e}^{i+3-k})-\delta tU_k(\Delta {\bm e}^{i},...,\Delta {\bm e}^{i+2-k})\\
\le &C(\varepsilon)\delta t\|\nabla C_k^{\beta_k}({\bm e}^i)\|^2(\|\Delta C_k^{\beta_k}({\bm u}^i)\|^2+\|C_k^{\beta_k}[{\bm u} (t^i)]\|_2^2+1)+(\varepsilon+\frac{\sqrt{2}}{4})\delta t\|\Delta C_k^{\beta_k}({\bm e}^{i+1})\|^2\\
&+(\frac{\sqrt{2}}{4}+\frac{\sqrt{2}\varepsilon}{2})\delta t\|\Delta C_k^{\beta_k}({\bm e}^i)\|^2
+C(\varepsilon)\delta t\sum_{q=0}^{k-1}\|\nabla {\bm e}^{i-q}\|^2(\|\Delta {\bm u}^{i-q}\|^2+\|\bm u(t^{i-q})\|_2^2)\\
& + C(\varepsilon)\delta t^{2k} \int_{t^{i+1-k}}^{t^{i+\beta_k}}\Big(\Big{\|}\nabla \frac{\partial ^k p}{\partial t^k}(s)\Big{\|}^2+\Big{\|}\Delta \frac{\partial ^k \bm u}{\partial t^k}(s)\Big{\|}^2+\Big{\|}\frac{\partial ^{k+1} \bm u}{\partial t^{k+1}}\Big{\|}^2+\Big{\|} \nabla \frac{\partial ^k \bm u}{\partial t^k}(s)\Big{\|}^2\Big)ds.
\end{split}
\end{equation}
\end{small}
Thanks to \eqref{epsilon}, we have
\begin{equation}
0.71-\frac{\sqrt{2}}{2}-\varepsilon-\frac{\sqrt{2}\varepsilon}{2}  >0.
\end{equation}
Taking the sum of \eqref{tosum2} for $i$ from $k-1$ to $n$.  Under the assumption \eqref{NScond2} on the exact solution and the initial steps $\bm u^i,\, \forall i \le k-1$, we can obtain the following after dropping some unnecessary terms:
\begin{small}
\begin{equation}\label{eq:sum2}
\begin{split}
&\lambda_k^g\|\nabla {\bm e}^{n+1}\|^2+\kappa_k\delta t \sum_{i=k}^{n+1}\|\Delta {\bm e}^{i}\|^2\\
 \le & C\delta t \sum_{i=k-1}^{n}\|\nabla {\bm e}^i\|^2(\|\Delta {\bm u}^i\|^2+\|{\bm u}(t^i)\|_2^2)+C\delta t \sum_{i=k-1}^{n}\|\nabla C_k^{\beta_k}({\bm e}^i)\|^2(\|\Delta C_k^{\beta_k}({\bm u}^i)\|^2+\|C_k^{\beta_k}[{\bm u}(t^i)]\|_2^2+1) +CT\delta t^{2k}\\
\le& C\delta t\sum_{i=k-1}^{n}\|\nabla {\bm e}^i\|^2 \Big(\|\Delta {\bm u}^i\|^2+\|{\bm u}(t^i)\|_2^2+\sum_{q=0}^{{\rm min}\{k-1,n-i\}}(\|\Delta C_k^{\beta_k}({\bm u}^{i+q})\|^2+\|C_k^{\beta_k}[{\bm u}(t^{i+q})]\|_2^2+1) \Big)+CT\delta t^{2k}
\end{split}
\end{equation}
\end{small}where $\lambda_k^g>0$ is the smallest eigenvalue of $G_k=(g_{lj})$.
We can then derive from \eqref{H2bound} and assumptions on the exact solution that there exists $C_1>1$, which is independent of $C_0$ and $\delta t$ such that
\begin{subequations}\label{H2bound2}
\begin{align}
\delta t \sum_{i=0}^{m}\|\Delta {\bm u}^i\|^2,\,\delta t \sum_{i=k-1}^{m}\|\Delta C_k^{\beta_k}({\bm u}^i)\|^2 & \le  C_1(C_0^6+1),\, \forall m \le n;\\
\|C_k^{\beta_k}[{\bm u}(t^i)]\|_2^2,\,\|{\bm u}(t^i)\|_2^2 &\le C_1,\, \forall t\le T.
\end{align}
\end{subequations}
Then noting that the assumption on the initial steps $\bm u^i,\,  i=0,..., k-1$ and applying the Gronwall Lemma \ref{Gron2} on \eqref{eq:sum2}, we obtain
\begin{equation}\label{ebarerror}
\|\nabla {\bm e}^{n+1}\|^2+\delta t \sum_{i=0}^{n+1}\|\Delta {\bm e}^{i}\|^2 \le CT\delta t^{2k}\exp(CC_1(C_0^6+1)+T)=: C_{\bm u}^2 \delta t^{2k},
\end{equation}
where $C_{\bm u}$ is a constant independent of $\delta t$. Moreover, since
\begin{equation}
\|\nabla \bm u^{n+1}\| \le \|\nabla \bm u(\cdot, t^{n+1})\|+\|\nabla {\bm e}^{n+1}\|,
\end{equation}
it follows from the definition of $C_0$ in \eqref{C0def} that \eqref{H1bound} is obviously true if we choose
\begin{equation}
\delta t \le {\rm min}\{1, \frac{1}{C_{\bm u}}\},
\end{equation}
and hence the induction process is completed.




\textbf{Step 3: Error estimate for the pressure}. Let $q=e_p^i$ in \eqref{errorp0}, by using  Lemma \ref{stokespre} and the Sobolev inequality, we have
\begin{equation}\label{errorp2}
\begin{split}
\|\nabla e_p^i \|^2 & \le 2\|\bm u(t^i) \cdot \nabla \bm u(t^i)-{\bm u}^i\cdot \nabla {\bm u}^i\|^2+2\|\nabla p_s({\bm e}^i)\|^2\\
& \le C\|\nabla {\bm e}^i\|^2(\|\Delta {\bm u}^i\|^2+\|\bm u(t^i)\|_2^2)+2\|\Delta {\bm e}^i\|^2+C\|\nabla {\bm e}^i\|^2.
\end{split}
\end{equation}
Now, take the sum on \eqref{errorp2}, then \eqref{H2bound2} and \eqref{ebarerror} together imply
\begin{equation}\label{errorp3}
\delta t \sum_{i=0}^{n+1} \|\nabla e_p^i\|^2 \le C\delta t^{2k}.
\end{equation}
Finally, we complete the proof by combining \eqref{ebarerror} and \eqref{errorp3}.

 \end{proof}



\section{Numerical validation and concluding remarks}
We  provide two numerical examples to show that  (i) the higher-order consistent splitting  schemes based on the usual BDF are not unconditionally stable but the new schemes with suitable $\beta$ are, and (ii)  the new schemes with suitable $\beta$ achieve the expected  convergence rates,  followed by some concluding remarks.
\subsection{Numerical results}

\textit{Example 1.} In the first example, we first consider the stokes problem (in the absence of $\bm f$ and the nonlinear term in \eqref{NS}) in $\Omega=(-1,1)\times (-1,1)$ with no-slip boundary condition, and the initial conditions are given as
\begin{subequations}\label{initial}
	\begin{align}
		& u_1(x,y,0)=\sin(2\pi y)\sin^2(\pi x);\\
		& u_2(x,y,0)=-\sin(2\pi x)\sin^2(\pi y).
	\end{align}
\end{subequations}
We set $\nu=0.005$ and use the third- and fourth- order version of \eqref{scheme_stoke}. We use the Legendre-Galerkin method  \cite{STWbook} with $Nx=Ny=128$ modes in space. In Figure \ref{fig:stoke}, we plot the energy evolution obtained from the third- and fourth- order schemes. In both cases, we  observe that the  high-order schemes based on the usual BDF (with $\beta=1$) are unstable even with an extremely small time step ($\delta t=0.0005$ for the third order scheme and $\delta t=0.0002$ for the fourth order scheme), while we can obtain  correct solutions with large time step $\delta t=0.05$ by choosing suitable $\beta$ as specified in previous sections.  We also observe that  these schemes are still stable with  $\delta t=1 $ although the solutions are no longer correct with such large time step.
