& +\frac{2}{10^5}\big(215\bm u^{n+1}-375\bm u^{n}+165\bm u^{n-1}, 215\bm u^{n+1}-590\bm u^n+540\bm u^{n-1}-165\bm u^{n-2} \big)\\
 =&\frac{2}{10^5}\big(210\bm u^{n+1}-375\bm u^{n}+165\bm u^{n-1}, 5\bm u^{n+1}-4\bm u^n \big)+\frac{2}{10^5}\big(5\bm u^{n+1}, 5\bm u^{n+1}-4\bm u^n \big)\\
& +\frac{1}{10^5}\big(\|215\bm u^{n+1}-375\bm u^{n}+165\bm u^{n-1} \|^2-\|215\bm u^{n}-375\bm u^{n-1}+165\bm u^{n-2} \|^2\big)\\
&+\frac{1}{10^5}\| 215\bm u^{n+1}-590\bm u^n+540\bm u^{n-1}-165\bm u^{n-2}\|^2,\\
=&\frac{2}{10^5}\big(210\bm u^{n+1}-375\bm u^{n}+165\bm u^{n-1}, 5\bm u^{n+1}-4\bm u^n \big)+\frac{1}{10^4}\|\bm u^{n+1}\|^2\\
&+\frac{2}{10^4}\big( \|\bm u^{n+1}\|^2-\|\bm u^n\|^2+\|\bm u^{n+1}-\bm u^n\|^2\big)\\
&+\frac{1}{10^5}\big(\|215\bm u^{n+1}-375\bm u^{n}+165\bm u^{n-1} \|^2-\|215\bm u^{n}-375\bm u^{n-1}+165\bm u^{n-2} \|^2\big)\\
&+\frac{1}{10^5}\| 215\bm u^{n+1}-590\bm u^n+540\bm u^{n-1}-165\bm u^{n-2}\|^2,
\end{split}
\end{equation}
and finally, for the term $\big(210\bm u^{n+1}-375\bm u^{n}+165\bm u^{n-1}, 5\bm u^{n+1}-4\bm u^n \big)$, we have
\begin{equation}
\begin{split}
&\big(210\bm u^{n+1}-375\bm u^{n}+165\bm u^{n-1}, 5\bm u^{n+1}-4\bm u^n \big)\\
&=a\|\bm u^{n+1}\|^2-a\|\bm u^{n}\|^2+\|b\bm u^{n+1}+c\bm u^n\|^2-\|b\bm u^{n}+c\bm u^{n-1}\|^2
+\|d\bm u^{n+1}+e\bm u^n+f\bm u^{n-1}\|^2.
\end{split}
\end{equation}
with
\begin{small}
\begin{equation}
 e=-\sqrt{\frac{3375}{2}},\,f=\frac{-\sqrt{37.5}+\sqrt{1687.5}}{2},\,c=f,\,d=\sqrt{37.5}+f,\,b=\frac{660+2ef}{2c},\,a=1050-b^2-d^2\approx 0.2188.
\end{equation}
\end{small}
\section{Proof of Lemma \ref{DC_lemma}}\label{app2}
\end{appendix}
\begin{proof}
The proof follows the basic process as in \cite{akrivis2021energy}. We consider the case $k=2,3,4$ separately.\\
\textbf{Case I: k=2.} With $c_{2,q}$ obtained from \eqref{solve_ckq} and $d_{2,q}$ defined in \eqref{dkq} and $\beta_2=3$, $\eta_k=0.71$, the explicit form of $\tilde{C}_2^3(\zeta)$ and $\tilde{D}_2^3(\zeta)$ are given as
\begin{equation}
\tilde{C}_2^3(\zeta)=4\zeta-3,\quad \tilde{D}_2^3(\zeta)=\frac{3}{20}\zeta+\frac{13}{100},
\end{equation}
which imply $\tilde{C}_2^3(\frac{3}{4})=0$ and $ \tilde{D}_2^3(\frac{-13}{15})=0$. Hence $\tilde{C}_2^3(\zeta)$, $\tilde{D}_2^3(\zeta)$ have no common divisor and $\frac{\tilde{D}_2^3(\zeta)}{\tilde{C}_2^3(\zeta)}$ is holomorphic outside the unit disk. Moreover, we have
\begin{equation}
\lim_{|\zeta| \rightarrow \infty}\frac{\tilde{D}_2^3(\zeta)}{ \tilde{C}_2^3(\zeta)}=\frac{3}{80}>0.
\end{equation}
Therefore, it follows from the maximum principle for harmonic functions, $\text{Re}\frac{\tilde{D}_2^3(\zeta)}{\tilde{C}_2^3(\zeta)}>0,\quad \forall |\zeta|>1$ is equivalent to
\begin{equation}\label{A10}
\text{Re} \frac{\tilde{D}_2^3(\zeta)}{\tilde{C}_2^3(\zeta)}\ge 0, \quad \forall \zeta \in \mathbb{S}^1,
\end{equation}
with $\mathbb{S}^1$ is the unit circle in the complex plane and \eqref{A10} is equivalent to
\begin{equation}\label{A11}
Re[\tilde{D}_2^3(e^{i\theta})\tilde{C}_2^3(e^{-i\theta})] \ge 0, \quad \theta \in [0, 2\pi).
\end{equation}
Denote $y:=\cos(\theta)$, then \eqref{A11} is equivalent to
\begin{equation}
Re[\tilde{D}_2^3(e^{i\theta})\tilde{C}_2^3(e^{-i\theta})]=\frac{7}{100}y+\frac{21}{100} \ge 0, \quad  \forall y \in [-1, 1],
\end{equation}
which is obvious true and hence we proved Lemma \ref{DC_lemma} with $k=2$.\\
\textbf{Case II: k=3.} With $k=3$ and $\beta_3=6$, the explicit form of $\tilde{C}_3^6(\zeta)$ and $\tilde{D}_3^6(\zeta)$ are given as
\begin{equation}
\tilde{C}_3^6(\zeta)=28\zeta^2-48\zeta+21,\quad \tilde{D}_3^6(\zeta)=\frac{17}{20}\zeta^2-\frac{71}{100}\zeta+\frac{9}{100},
\end{equation}
and the zeros of $\tilde{C}_3^6(\zeta)$ are $\frac{12 \pm \sqrt{3}i}{14}$, the zeros of $\tilde{D}_3^6(\zeta)$ are $\frac{71 \pm \sqrt{1981}}{170}$, which imply $\tilde{C}_3^6(\zeta)$, $\tilde{D}_3^6(\zeta)$ have no common divisor and $|\frac{12 \pm \sqrt{3}i}{14}|<1$ implies $\frac{\tilde{D}_3^6(\zeta)}{\tilde{C}_3^6(\zeta)}$ is holomorphic outside the unit disk. Following the same process as the second order case, one can easily show $\text{Re}\frac{\tilde{D}_3^6(\zeta)}{\tilde{C}_3^6(\zeta)}>0,\quad \forall |\zeta|>1$ is equivalent to
\begin{equation}
f_3(y):=\frac{2037}{50}y^2-\frac{7991}{100}y+\frac{197}{5} \ge 0, \quad  \forall y \in [-1, 1],
\end{equation}
which is true since
\begin{equation}
\mathop{\rm {min}}\limits_{y \in [-1,1]} f_3(y)=f_3(\frac{7991}{8148})\approx 0.214874>0.
\end{equation}
\textbf{Case III: k=4.} With $k=4$ and $\beta_4=9$, the explicit form of $\tilde{C}_4^9(\zeta)$ and $\tilde{D}_4^9(\zeta)$ are given as
\begin{subequations}
\begin{align}
&\tilde{C}_4^9(\zeta)=220\zeta^3-594\zeta^2+540\zeta-165,\\
&\tilde{D}_4^9(\zeta)=\frac{1}{10^4}(87957\zeta^3-182525\zeta^2+125967\zeta-28500),
\end{align}
\end{subequations}
and the zeros of $\tilde{C}_4^9(\zeta)$ (with six decimal places) are
\begin{equation}
\zeta_{C1}=0.858473,\,\zeta_{C2}=0.920763+0.160745i,\,\zeta_{C3}=0.920763-0.160745i,
\end{equation}
and the zeros of $\tilde{D}_4^9(\zeta)$ (with six decimal places) are
\begin{equation}
\zeta_{D1}=0.517951,\,\zeta_{D2}=0.778605+0.139132i,\,\zeta_{D3}=0.778605-0.139132i,
\end{equation}
 which imply $\tilde{C}_4^9(\zeta)$, $\tilde{D}_4^9(\zeta)$ have no common divisor and $|\zeta_{Ci} |<1,\,i=1,2,3$ implies $\frac{\tilde{D}_4^9(\zeta)}{\tilde{C}_4^9(\zeta)}$ is holomorphic outside the unit disk. Following the same process as the second order case, one can easily show $\text{Re}\frac{\tilde{D}_4^9(\zeta)}{\tilde{C}_4^9(\zeta)}>0,\quad \forall |\zeta|>1$ is equivalent to
\begin{equation}\label{f4}
f_4(y):=\alpha_3y^3+\alpha_2y^2+\alpha_1y+\alpha_0 \ge 0, \quad  \forall y \in [-1, 1],
\end{equation}
with
\begin{equation}
\alpha_3=-\frac{429\times9689}{500},\,\alpha_2=\frac{9\times2716781}{1000},\,\alpha_1=-\frac{241\times62141}{625},\,\alpha_0=\frac{53\times3^{10}}{400}.
\end{equation}
\eqref{f4} is true since
\begin{equation}
\mathop{\rm {min}}\limits_{y \in [-1,1]} f_4(y)=f_4(y^*) \approx 3.000376\times 10^{-4} >0.
\end{equation}
with $y^*=\frac{-\alpha_2+\sqrt{\alpha_2^2-3\alpha_1\alpha_3}}{3\alpha_3} \approx  0.959828$.
The proof for all the cases is completed.
\end{proof}


