	\subsection{Notations and definitions}
	Given a positive integer \(M\),  $[M]$ {stands for the set} $\{0,1,\ldots,M-1\}$. 
	The \(l_2\)-norm is {written as} %denoted by 
    \(\|\cdot\|\), and \({\mathrm{co}}(\mathcal{X})\) represents the closed convex hull of a set \(\mathcal{X}\).  
	We use \(\mathrm{Proj}\), \(\mathrm{Prob}\), and \(\mathrm{dist}\) to denote operators of the projection, the probability, and the distance, respectively.
	The directional derivative of a convex function \(\phi\) at \(\vx\) along a direction \(\vv\) is written as \(\phi^{\prime}(\vx ; \vv)\), and it is defined as $\phi^{\prime}(\vx ; \vv) := \lim_{s \downarrow 0} \frac{\phi(\vx + s\vv) - \phi(\vx)}{s}.$
	By~\cite[Proposition 2.1.5(a)]{clarke1990optimization}, it holds that 
	\begin{equation}\label{eq:low-bd-dd}
	\phi^{\prime}(\vx ; \vv) \geq \vv^\top \vgamma, \text{ for any }\vgamma \in \partial \phi(\vx).
	\end{equation}

	\begin{definition}[Moreau Envelope~\cite{drusvyatskiy2019efficiency}]\label{def:weak-cvx} 
	For a \(\rho_{\phi}\)-weakly convex function \(\phi\), the Moreau envelope and the proximal mapping for any \(t \in (0, \frac{1}{\rho_{\phi}})\) are defined by
	$
	\phi_t({\vx}) :=\min_{\vz}\left\{\phi({\vz})+\frac{1}{2 t}\|{\vz}-{\vx}\|^2\right\}
	$ and $\operatorname{Prox}_{t \phi}({\vx}) :=\argmin_\vz\{\phi({\vz})+\frac{1}{2 t}\|{\vz}-{\vx}\|^2\}.
	$
	\end{definition}


	We give the definition of stationarity as follows.  In deterministic cases—where randomness is not involved—the expectation operator \(\mathbb{E}\) should be removed from the definitions below.
	\begin{definition}[Stationarity]
	\label{def:nearkkt}
	Let $\epsilon>0$ and $\delta>0$, and suppose $\psi$ and $\phi$ are  $\rho_\psi$- and $\rho_\phi$-weakly convex functions.
	\\
	$\mathrm{(a)}$ We call $\vx^*$ a \textit{near-$\epsilon$ stationary point} of $\min_{\vx} \phi(\vx)$ in expectation, if $\vx^*\in\dom(\phi)$, and there exists $0<t<\frac{1}{\rho_{\phi}}$, such that 
	$
	\mathbb{E}[\|\nabla \phi_{t}(\vx^*)\|^2] =\mathbb{E}[\| \frac{1}{t}(	\operatorname{Prox}_{t \phi}({\vx^*})-\vx^*) \|^2] \leq~\epsilon^2.
	$
	%Here, we denote \(\rho_{\phi}\) as the weakly convex parameter of \(\phi\), and  \(\frac{1}{0} = +\infty\).
	\\
	$\mathrm{(b)}$ We call $\vx^*$  an \textit{$\epsilon$-KKT point} of problem $\min_{\vx: \psi(\vx)\leq 0} \phi(\vx)$ in expectation, if it holds that $\vx^*\in\dom(\phi)\cap \dom(\psi)$, and there exists $\lb_{\vx^*}\ge0$ such that
	\begin{align*}
		\mathbb{E}\left[\dist(\vzero,\partial \phi(\vx^*) + \lb_{\vx^*} \partial \psi(\vx^*))\right] \leq \epsilon,\,\, \mathbb{E}\left[\psi(\vx^*)\right]\leq \epsilon, \text{ and }  |\lb_{\vx^*} \psi(\vx^*)|\leq \epsilon.
	\end{align*}
	$\mathrm{(c)}$ We call $\vx^*$  a \textit{$(\delta, \epsilon)$-KKT point} of problem $\min_{\vx: \psi(\vx)\leq 0} \phi(\vx)$ in expectation, if it holds that $\vx^*\in\dom(\phi)\cap \dom(\psi)$, and $\mathbb{E}[\|\vx^*-\widetilde{\vx}^*\|]\leq \delta$ with $\widetilde{\vx}^*$ being an $\epsilon$-KKT point of problem $\min_{\vx: \psi(\vx)\leq 0} \phi(\vx)$ in expectation.  
	\end{definition}


	\subsection{Organizations}

	The rest of this paper is organized as follows.~\Cref{sec:exact} introduces the exact penalty models. In~\Cref{sec:algorithm}, we propose a single-loop SPIDER-type stochastic subgradient method and establish its iteration complexity results. Numerical experiments are presented in~\Cref{sec:numer}, showcasing the performance of our method. Finally,~\Cref{sec:conclu} concludes the paper.

