		\begin{assumption}[{sharpness}]
			\label{ass:errorbound}
			There exist $\theta>0$ and $B_g>0$ such that for any $\vx$ satisfying $0 < g(\vx)\leq B_g$, it holds $\theta \dist(\vx, \Omega)\leq g_+(\vx)$. 
		\end{assumption}

		\begin{assumption}[(uniformly)  gradient-away]
			\label{ass:exact2}
			There exist $\theta>0$ and $B_g>0$ such that for any $\vx$ satisfying $0< g(\vx)\leq B_g$,  it holds
			$
			\min _{\boldsymbol{\vzeta}_g\in \partial g(\mathbf{x})}\left\|\boldsymbol{\vzeta}_g\right\| \geq \theta.
			$
		\end{assumption}

		\begin{lemma}
			\label{lem:1}
			Suppose~\Cref{ass:problemsetup} and~\Cref{ass:errorbound} hold, and $g$ is convex.
			Given $\epsilon>0$, let $\beta>\frac{1}{\theta} (l_f +\epsilon)$. 
			If $\vx^*$ satisfying $g(\vx^*)\leq B_g$ is an $\epsilon$-KKT point of problem~\cref{eq:penaltymodel}, % satisfying $\dist^2(\vx, \Omega)\leq \delta$, 
			then $\vx^*\in\Omega$, i.e., $\vx^*$ is a feasible point of problem~\cref{eq:model}, and~$\vx^*$ is an $\epsilon$-KKT point of problem~\cref{eq:model}.
		\end{lemma}

		\begin{proof}
			Since $\vx^*$ is an $\epsilon$-KKT point of problem~\cref{eq:penaltymodel}, there exist %According to~\cref{eq:epsta}, 
			$\vgamma\in\partial f(\vx^*)$ and $\vzeta\in\partial g_+(\vx^*)$ such that 
						\vspace{-1mm}
			\begin{equation}
				\label{eq:KKTe}
				\|\vgamma+\beta \vzeta\|\leq  \epsilon.
			\end{equation}
			We then derive that for any $\vv\in \RR^d$, 
			\begin{equation}
				\label{eq:dderivegeq0epsilon}
				\begin{aligned}
					F^{\prime}(\vx^*;\vv)= f^{\prime}(\vx^*;\vv)+\beta g_+^{\prime}(\vx^*;\vv) \geq \vv\zz\vgamma +\beta\vv\zz \vzeta \geq -\epsilon\|\vv\|,
				\end{aligned}
			\end{equation}
			where the first inequality follows from~\cref{eq:low-bd-dd}, %\cite[Proposition 2.1.5(a)]{clarke1990optimization}, 
			and the second inequality is by~\cref{eq:KKTe}.

			Second, 
			we let $\vx^+ := \mathrm{Proj}_{\Omega}(\vx^*)$, and 
			$
			\overline{\vv}:=\vx^+ -\vx^*.
			$
			For any $0<s<1$, we derive 
			\begin{equation}
				%\small
				\label{eq:geq}
				\begin{aligned}
					g_+(\vx^*+s\overline{\vv}) -g_+(\vx^*)  &\leq (1-s)g_+(\vx^*)+s g_+(\vx^*+\overline{\vv}) -g_+(\vx^*) \\&= -sg_+(\vx^*)%-{\rho_g}s(1-s)(\vx^*)\zz(\vx^*+\overline{\vv})-s g_+(\vx^*)
					\leq  -{s\theta}{} \dist(\vx^*, \Omega), %-{\rho_g}s(1-s)(\vx^*)\zz(\vx^*+\overline{\vv}),
				\end{aligned}
			\end{equation}
			where the first inequality follows from the convexity of $g$, and the second inequality holds %comes from $\theta \dist(\vx^*, \Omega)\leq g_+(\vx^*)$ 
			by~\Cref{ass:errorbound} and $\dist(\vx^*, \Omega)=0$ if $g(\vx^*)\le 0$. 
			In addition, we   have $f(\vx^*+s\overline{\vv}) -f(\vx^*) \leq l_f s\|\overline{\vv}\| = l_f s \dist(\vx^*, \Omega)$. % by~\Cref{ass:problemsetup}(c). 
            Combining this with~\cref{eq:geq}, we arrive at 
			%{This together with \eqref{eq:geq} imply}
			$
			\frac{1}{s} \left(F(\vx^*+s\overline{\vv}) -F(\vx^*)\right) \leq - \beta\theta \dist(\vx^*, \Omega) + l_f  \dist(\vx^*, \Omega)%-\beta{\rho_g}(1-s)(\vx^*)\zz(\vx^*+\overline{\vv}) 
			$. %by~\cref{eq:geq}.
			%Taking the limit of the left-hand side of the inequality above as 
			Letting $s\downarrow 0$, we obtain %know from $\vx^*+\overline{\vv}=\vx^+$ and~\cref{eq:dderivegeq0epsilon} that		
			\vspace{-3mm}
			\begin{align}
				\label{eq:vio1}
				- (\beta\theta-l_f) \dist(\vx^*, \Omega) \geq F^{\prime}(\vx^*;\overline{\vv}) \overset{\cref{eq:dderivegeq0epsilon}}\geq -\epsilon\|\overline{\vv}\| = -\epsilon \dist(\vx^*, \Omega).
			\end{align}
			Since $\beta > \frac{1}{\theta} (l_f +\epsilon)$, the above inequality holds only if   $\vx^*\in\Omega$. 		

			Now, if $g(\vx^*)=0$, we obtain from the convexity of $g$ that $\partial g_+(\vx^*)= {\mathrm{co}} \{\partial g(\vx^*), \vzero \}$ by~\cite[Proposition 2.3.12]{clarke1990optimization}. Thus, there exists $0\leq t \leq 1$ such that $\vzeta \in t \partial g(\vx^*)$.
			Then~$\vx^*$ is an $\epsilon$-KKT point of problem~\cref{eq:model} with multiplier $\beta t$ by~\cref{eq:KKTe} and $\vzeta \in t \partial g(\vx^*)$. {Otherwise, i.e., if} $g(\vx^*)<0$, we have $\vzeta= \vzero$.
			It then yields that $\vx^*$ is an $\epsilon$-KKT point of problem~\cref{eq:model} with multiplier 0 by~\cref{eq:KKTe}. The proof is then completed.
		\end{proof}



		\begin{lemma}
			\label{lem:2}
			Suppose~\Cref{ass:problemsetup} and~\Cref{ass:exact2} hold.
			Given  $\epsilon>0$, let $\beta>\frac{1}{\theta} (l_f +\epsilon)$.
			If $\vx^*$ satisfying $g(\vx^*)\leq B_g$ is an $\epsilon$-KKT point of problem~\cref{eq:penaltymodel},  it then holds $\vx^*\in\Omega$, and $\vx^*$ is an $\epsilon$-KKT point of problem~\cref{eq:model}.
		\end{lemma}
		\begin{proof}
			Since $\vx^*$ is an $\epsilon$-KKT point of problem~\cref{eq:penaltymodel}, 
			there exits %According to~\cref{eq:epsta}, 
			$\vgamma\in\partial f(\vx^*)$ and $\vzeta\in\partial g_+(\vx^*)$ such that~\cref{eq:KKTe} holds.

			We claim $g_+(\vx^*)=0$, i.e., $g(\vx^*)\leq 0$. If the claim is not true, we have $g(\vx^*)> 0$ and then $\partial g_+(\vx^*)= \partial g(\vx^*)$.
			We then derive that 
			\begin{align}
				\label{eq:vio2}
				\epsilon& \geq {}\|\beta\vzeta + \vgamma\|  \geq {\beta}\|\vzeta\| -\|\vgamma\| \geq  {\beta}\|\vzeta\| -l_f \geq \beta \theta -l_f,
			\end{align}
			where %the second inequality is by triangle inequality, 
			the third inequality holds by~\Cref{ass:problemsetup}(c), and the fourth one follows from~\Cref{ass:exact2} and $\vzeta\in\partial g_+(\vx^*)=\partial g(\vx^*)$. %by $g(\vx^*)\leq B_g$. 
			This contradicts to $\beta > \frac{1}{\theta} (l_f +\epsilon)$. Hence $g_+(\vx^*)=0$. 

			Now, if $g(\vx^*)=0$, we obtain $\partial g_+(\vx^*)= {\mathrm{co}} \{\partial g(\vx^*), \vzero \}$ from the weak convexity of $g$ and~\cite[Proposition~2.3.12]{clarke1990optimization}. Thus, there exists $0\leq t \leq 1$ such that $\vzeta \in t \partial g(\vx^*)$.
			Then $\vx^*$ is an $\epsilon$-KKT point of problem~\cref{eq:model} with multiplier $\beta t$ by~\cref{eq:KKTe} and $\vzeta \in t \partial g(\vx^*)$. {Otherwise, i.e., if} $g(\vx^*)<0$, we have $\vzeta= \vzero$.
			It then yields that~$\vx^*$ is an $\epsilon$-KKT point of problem~\cref{eq:model} with  multiplier 0  by~\cref{eq:KKTe}.   The proof is then completed.
		\end{proof}


		The following corollary holds directly from \cref{lem:1} and \cref{lem:2}.
		\begin{corollary}
			\label{cor:1}
			Under~\Cref{ass:problemsetup}, the following statements hold with $\beta>~\frac{l_f}{\theta}$.

			$\mathrm{(i)}$ Suppose~\Cref{ass:errorbound} hold, and $g$ is convex.  For all $\vx^*$ satisfying $g(\vx^*)\leq B_g$,
            $\vx^*\not\in\Omega$, and $\vx^*\in\dom(f)\cap \dom(g)$, it holds $\dist(\vzero, \partial f(\vx^*) + \beta \partial g_+(\vx^*))\geq \beta\theta -l_f$.

			$\mathrm{(ii)}$ Suppose~\Cref{ass:exact2} hold. For all {$\vx^*$ satisfying }
            $g(\vx^*)\leq B_g$,
            $\vx^*\not\in\Omega$, and $\vx^*\in\dom(f)\cap \dom(g)$,
			it holds $\dist(\vzero, \partial f(\vx^*) + \beta \partial g_+(\vx^*))\geq \beta\theta -l_f$.
		\end{corollary}


		\subsection{Exact penalization with a ``smoothed'' penalty approach}
		\label{sec:exact2}
		In this subsection, we establish the relationship between models~\cref{eq:model} and~\cref{eq:smoothed}.
		We {begin by showing that }%first show that 
        the function~$F^{\nu}$ in \eqref{eq:smoothed} is  weakly convex. 
		\begin{lemma}
			\label{lem:weaklyFnu}
			Suppose~\Cref{ass:problemsetup} holds. {For any given} $\nu>0$, the function $F^{\nu}$ defined in~\cref{eq:smoothed} is $\rho$-weakly convex, where $\rho = \rho_f + \beta \rho_g$. 
		\end{lemma}
		\begin{proof}
			To obtain the desired result, we only need to prove $ h^{\nu} (g(\vx))$ is $\rho_g$-weakly convex. Notice that 
			\begin{align*}
				h^{\nu} (g(\vx)) + \frac{\rho_g}{2}\|\vx\|^2= \max _{0\leq y\leq 1} y \cdot g(\vx) -\frac{\nu}{2} y^2 +\frac{\rho_g}{2}\|\vx\|^2.
			\end{align*}
			Since $g$ is $\rho_g$-weakly convex, $y \cdot g(\vx) -\frac{\nu}{2} y^2 +\frac{\rho_g}{2}\|\vx\|^2$ is convex with respect to $\vx$ for all $0\leq y\leq 1$. Thus  {by Danskin's theorem~\cite{bertsekas1997nonlinear},}
			$h^{\nu} (g(\vx)) + \frac{\rho_g}{2}\|\vx\|^2$ is convex.  
		\end{proof}

		Next,  we introduce some notations and key properties of the Moreau envelope.
		Denote $F_{\frac{1}{2\rho}}$ and~$F^{\nu}_{\frac{1}{2\rho}}$ as the Moreau envelope of $F$ and $F^{\nu}$ with parameter $\frac{1}{2\rho}$, respectively. We let
		\begin{equation}\label{eq:def-x-hat-+}
			\begin{aligned}
				&\overline\vx^*=  \argmin_{\vx}  F(\vx) + \rho \|\vx -\vx^*\|^2,\quad %=\operatorname{Prox}_{\frac{F}{2\rho}}\left(\vx^*\right), 
				 \widehat{\vx}^* =\argmin_{\vx}   F^{\nu}(\vx) + \rho \|\vx -\vx^*\|^2.
				%=\operatorname{Prox}_{\frac{F^{\nu}}{2\rho}}\left(\vx^*\right).\\ 
			\end{aligned}
		\end{equation}	
		We then have 
		\begin{align}
			\label{eq:gradientmore}
			&\|\nabla F_{\frac{1}{2\rho }}(\vx^*)\| = 2\rho\|\overline\vx^* -\vx^*\|, \ \|\nabla F^{\nu}_{\frac{1}{2\rho }}(\vx^*)\| = 2\rho\| \widehat{\vx}^*-\vx^* \|, \text{ and}\\
			&\vzero \in \partial f\left(\widehat\vx^*\right) +\beta \mathrm{Proj}_{[0,1]}\left(\frac{g\left(\widehat\vx^*\right)}{\nu}\right) \partial g\left(\widehat\vx^*\right) +2\rho \left(\widehat\vx^*-\vx^*\right).
			\label{eq:kktwidex2}
		\end{align}
		In addition, by  
		\cite[Eqn. (4.3)]{drusvyatskiy2019efficiency}, it holds that  
		\begin{equation}
			\label{eq:importantine}
			%\begin{cases}
			F(\overline{\vx}^*)\leq F(\vx^*),
			\text{ and }
			\dist(\vzero , \partial F(\overline{\vx}^*))
			\leq \big\|\nabla F_{\frac{1}{2\rho }}(\vx^*)\big\| .
		\end{equation}

		We now present our main results  
		to demonstrate the effectiveness of solving a smoothed exact penalty problem for a deterministic or stochastic case. 
		\begin{theorem}
			\label{thm:main}
			Suppose that~\Cref{ass:problemsetup} holds. Given $\epsilon>0$, let
			\begin{align}
				\label{eq:epsilon}				\small
				\beta >  \frac{1}{\theta}(l_f + \epsilon),\  
				0 < \overline{\epsilon} \leq \epsilon \min\left\{ \frac{\beta \theta - l_f}{2 B_g}, \frac{\beta \theta - l_f}{\beta \theta}, 2 \rho \right\},
				\text{ and } 
				0 < \nu \leq \min\left\{B_g, \frac{\epsilon}{\beta}, \frac{\epsilon}{2}\right\}.
			\end{align}
			If $\vx^*$ is a near-$\overline\epsilon$ stationary
			point of problem~\cref{eq:smoothed} with $t=\frac{1}{2\rho}$ {(see~\cref{def:nearkkt}$\mathrm{(a)}$)} deterministically or in expectation, then $\|\vx^*-\widehat{\vx}^*\| \le \epsilon$ holds deterministically or in expectation, where $\widehat{\vx}^*$ is defined in~\cref{eq:def-x-hat-+}. In addition, for each of the following three cases, $\widehat{\vx}^*$   is an $\epsilon$-KKT point of problem~\cref{eq:model} deterministically or in expectation.  
			\begin{itemize}
				\item[$\mathrm{(i)}$] $g$ is convex,  i.e., $\rho_g=0$,~\Cref{ass:errorbound} holds, and furthermore $\beta > \frac{B_f +\rho_f D^2}{B_g}$.
				\item[$\mathrm{(ii)}$] $g$ is $\rho_g$-weakly convex with $\rho_g\ge 0$,~\Cref{ass:exact2}  holds, $B_g > \rho_g D^2$, and furthermore $\beta >\frac{B_f +\rho_f D^2}{B_g - \rho_g D^2}$.
				\item[$\mathrm{(iii)}$] $g$ is $\rho_g$-weakly convex with $\rho_g \ge 0$,~\Cref{ass:exact2}  holds, $g(\vx^*) \leq \frac{B_g}{2}$, and furthermore $\beta >\frac{2B_f}{B_g}$.
			\end{itemize}         
		\end{theorem}	

		\begin{proof}
			We only need to the prove the theorem in the expectation sense. For the deterministic case, one can simply drop the expectation notation $\EE$.

			First, {according to the definition of $\vx^*$,}%since $\vx^*$ is a near-$\overline{\epsilon}$ stationary point of problem~\cref{eq:smoothed} with $t=\frac{1}{2\rho}$ in expectation, it follows from
            ~\Cref{def:nearkkt} gives 
			$
			\mathbb{E}\left[\|2 \rho (\widehat{\vx}^* - \vx^*)\|^2\right] \leq~\overline{\epsilon}^2.
			$
            {Because $\overline\epsilon \le 2\rho \epsilon$, if follows that}
			%This together with $\overline\epsilon \le 2\rho \epsilon$ indicates	
			\begin{equation}\label{eq:eps-dist-xbar-x}
				\mathbb{E}\left[\|2 \rho (\widehat{\vx}^* - \vx^*)\|\right] \leq \overline{\epsilon} \text{ and  } \mathbb{E}\left[\|\widehat{\vx}^* - \vx^*\|\right] \leq \epsilon. 
			\end{equation}	

			Second, we discuss two events: $\cA_1$ as the case of $\frac{g\left(\widehat\vx^*\right)}{\nu}\leq 1$ and $\cA_2$ as the case of $\frac{g\left(\widehat\vx^*\right)}{\nu}> 1$. Let $\mathrm{Prob}_1$ and $\mathrm{Prob}_2$ denote their probabilities. 	Also, we let  $\lb_{\widehat\vx^*}$ be defined as %satisfies that 
            $\lb_{\widehat\vx^*} = \beta \mathrm{Proj}_{[0,1]}(\frac{g\left(\widehat\vx^*\right)}{\nu}) \ge 0$ when $\cA_1$ happens and $\lb_{\widehat\vx^*} =0$ when $\cA_2$ happens.

			For event $\cA_1$, we have $\dist\left(\vzero, \partial f\left(\widehat\vx^*\right) +\lb_{\widehat\vx^*}\partial g\left(\widehat\vx^*\right)\right) \leq 2\rho \| \widehat\vx^*-\vx^*\|$ by~\cref{eq:kktwidex2} and triangle inequality.
			Also, because $\frac{g\left(\widehat\vx^*\right)}{\nu}\leq 1$, we have $g(\widehat\vx^*) \leq \nu \le \frac{\epsilon}{2}.$ 
			Moreover, if it holds $g(\widehat\vx^*)\le 0$, then $\lb_{\widehat\vx^*}=0$ by its definition, and $|\lb_{\widehat\vx^*} g\left(\widehat\vx^*\right)|=0 \leq \epsilon$; if $g(\widehat\vx^*)>0$, then $|\lb_{\widehat\vx^*} g\left(\widehat\vx^*\right)| = \lb_{\widehat\vx^*} g\left(\widehat\vx^*\right) \leq \beta g\left(\widehat\vx^*\right)  \leq \beta \nu \leq \epsilon$. Hence, we obtain
			\begin{align}
				\label{eq:event1}
				\textstyle		\dist\left(\vzero, \partial f\left(\widehat\vx^*\right) +\lambda_{\widehat{\vx}^*}\partial g\left(\widehat\vx^*\right)\right) \leq  2\rho \| \widehat\vx^*-\vx^*\|, \,\,g(\widehat\vx^*) \le \nu \leq \frac{\epsilon}{2},\text{ and }|\lambda_{\widehat{\vx}^*} g\left(\widehat\vx^*\right)| \leq \epsilon.
			\end{align}

			For event $\cA_2$, we have from $g\left(\widehat\vx^*\right) > \nu$ and~\cref{eq:kktwidex2} that
			\begin{align}
				\label{eq:kktvio2}
				\vzero \in \partial f\left(\widehat\vx^*\right) +\beta  \partial g_+\left(\widehat\vx^*\right) +2\rho \left(\widehat\vx^*-\vx^*\right).
			\end{align}
			Thus $\widehat\vx^*$ satisfies the optimality condition of 	the left minimization problem in~\cref{eq:def-x-hat-+}, and	 
			we obtain $\widehat\vx^* = \overline\vx^* $.  
			Below we show $g_+(\widehat{\vx}^*) \le B_g$ {under event $\mathcal{A}_2$} for all the three cases (i)--(iii) in the statement of~\Cref{thm:main}.	

			For case (i), there exists $\vx_{\mathrm{feas}}\in\dom(f) \cap \dom(g) \cap \Omega$ by \Cref{ass:problemsetup}(a).
			From~\cref{eq:def-x-hat-+},
			we have 
			\begin{align}
				\notag f(\overline{\vx}^*) + \beta g_+(\overline{\vx}^*) + \rho \|\overline\vx^* -\vx^*\|^2 &\leq f(\vx_{\mathrm{feas}}) + \beta g_+(\vx_{\mathrm{feas}})  +\rho \|\vx_{\mathrm{feas}} -\vx^*\|^2 \\& = f(\vx_{\mathrm{feas}}) +  \rho \|\vx_{\mathrm{feas}} -\vx^*\|^2.
				\label{eq:chain-bd}
			\end{align}	
            Now because 
            $\beta \geq \frac{B_f +\rho_f D^2}{B_g}$,  {$\rho=\rho_f+\beta \rho_g=\rho_f$,} and $\|\vx_{\mathrm{feas}} -\vx^*\|^2\leq D^2$ from~\Cref{ass:problemsetup}(a), we arrive at $$g_+(\widehat{\vx}^*) = g_+(\overline{\vx}^*) \leq \frac{1}{\beta}(f(\vx_{\mathrm{feas}}) - f(\overline{\vx}^*) +  \rho_f \|\vx_{\mathrm{feas}} -\vx^*\|^2) \le \frac{B_f +\rho_f D^2}{\beta} \leq B_g.$$ 
			For case (ii), we still have~\cref{eq:chain-bd}. Thus,  
			$
			f(\overline{\vx}^*) + \beta g_+(\overline{\vx}^*) + \rho \|\overline{\vx}^* - \vx^*\|^2\le f(\vx_{\mathrm{feas}}) + \rho D^2$ by \Cref{ass:problemsetup}(a).
			Now by $\rho_g D^2 < B_g$, $\beta \geq \frac{B_f + \rho_f D^2}{B_g - \rho_g D^2}$, and $\rho = \rho_f + \beta \rho_g$, 
			it follows 
			\[
