	\section{A single-loop SPIDER-type stochastic subgradient algorithm}
	\label{sec:algorithm}
	In this section, we present our algorithm for solving problem~\cref{eq:model}. It is developed based on a subgradient method for problem~\cref{eq:smoothed} by using the SPIDER technique to estimate constraint function values. The algorithm framework is outlined in~\Cref{sec:af}. In~\Cref{sec:complexity}, we prove that  in expectation, the algorithm can find a near-$\epsilon$ stationary point of problem~\cref{eq:smoothed}. Building on the results presented in the previous section, %and~\Cref{sec:exact2}, 
	we further establish in~\Cref{sec:all} that an \((\epsilon, \epsilon)\)-KKT point  in expectation of problem~\cref{eq:model} can be obtained.

	\subsection{Algorithm framework}\label{sec:af}
	We employ the SPIDER technique~\cite{fang2018spider}  to obtain an estimator $u^{(k)}$ of $g$ at the $k$-th iteration. Specifically, every~$q$ iterations, we draw a big batch of $S_1$ samples from $\mathbb{P}_g$, 
	while for other iterations, a smaller batch of~$S_2$ samples {is} %are 
    drawn. The estimator is set as
	\begin{equation}
		\label{eq:updateu}
		u^{(k)} = \left\{
		\begin{array}{lll}
			g(\vx^{(k)}, \mathcal{B}_k), & \text{ with }|\mathcal{B}_k| = S_1, & \text{ if }\mathrm{mod}(k, q) = 0 ,\\[1mm]
			u^{(k-1)} + g(\vx^{(k)}, \mathcal{B}_k) -g(\vx^{(k-1)}, \mathcal{B}_{k}), & \text{ with }|\mathcal{B}_k| = S_2, & \text{ otherwise},
		\end{array}
		\right.
	\end{equation}
	where $\mathcal{B}_k$ contains identically independent 
    samples from $\mathbb{P}_g$, and $g(\mathbf{x}, \mathcal{B})$ is defined in~\cref{eq:g-approx}. With $u^{(k)}$, we then take a sample subgradient of $f$ and~$g$ at $\vx^{(k)}$ and perform the update in~\cref{eq:newupdate}.  The pseudocode is given in~\Cref{alg:dad2-2}.

	 \begin{algorithm}[htbp]
		\caption{A SPIDER-type Stochastic Subgradient algorithm}\label{alg:dad2-2}
		\begin{algorithmic}[1]
		\STATE{Input: initial point $\vx^{(0)}\in\dom(f)\cap\dom(g)$, $\beta>0$, $q>0$, $S_1, S_2>0$, and $K>0$.}

		\FOR{$k=0,1, \cdots, Kq-1$}
			%\If{$g$ is deterministic}{set $u^{(k)} = g(\vx^{(k)})$.}
			%\If{$g$ is stochastic}{
			\STATE{Set $u^{(k)}$ by~\cref{eq:updateu}.}			
			\STATE{Choose $\alpha_k>0$, generate a (stochastic) subgradient $\boldsymbol{\zeta}_f^{(k)}$ of $f$ and a (stochastic) subgradient $\boldsymbol{\zeta}_g^{(k)}$ of $g$.}
			\STATE{Update $\vx$ by~\cref{eq:newupdate}.} %Calculate $\vx^{(k+1)}$ by~\cref{eq:updatex}.
			\ENDFOR
			\end{algorithmic}
		\end{algorithm}
		For the convenience of analysis, we {denote}
		\begin{equation}
