				and
				the last one holds because $-{\gamma}{}\leq -2\rho_g\dist(\vx^{(k)}, \Omega) =  -2\rho_g  \left\|\mathbf{x}^{(k)}-\mathbf{x}^{\dagger(k)}\right\|$ by induction. 
				Then it follows that
				\begin{align*}
                \vspace{-1mm}
				\dist({\vx}^{(k+1)}, \Omega) &\leq
					\dist({\vy}^{(k)}, \Omega) + \alpha_kl_f 
					\leq 
					\sqrt{1- \alpha_k \beta  \rho_g} \dist(\mathbf{x}^{(k)}, \Omega)+ \alpha_kl_f \\&\leq   \dist(\mathbf{x}^{(k)}, \Omega),
				\end{align*} where the second inequality uses~\cref{eq:distk1}, and the last one follows from $\beta \geq \frac{2 l_f l_g}{\rho_g C_0}$ and $\dist\left(\mathbf{x}^{(k)}, \Omega\right) \ge \frac{g(\vx^{(k)})}{l_g} \ge~\frac{C_0}{l_g}$.
				Thus 
				$\dist\left({\vx}^{(k+1)}, \Omega\right) \leq \min\{ \frac{\gamma }{2\rho_g}, \frac{B_g}{2l_g}\}$ by induction, and 
				$g({\vx}^{(k+1)}) \leq l_g \dist\left({\vx}^{(k+1)}, \Omega\right) \leq \frac{B_g}{2}$.

				(ii) 
				In the second case, we have $g(\vx^{(k)})\leq C_0.$		 
				From~\cref{eq:newupdate}, we have
				\begin{align}
					\notag
					\dist({\vx}^{(k+1)}, \Omega) 
					\leq &\dist({\vx}^{(k)}, \Omega) 
					+ \alpha_k (l_f +\beta l_g) 
					\\\leq &\min\left\{ \frac{\gamma }{2\rho_g}, \frac{B_g}{2l_g}\right\} + \alpha_k l_f + \frac{C_0}{l_g} \leq \min\left\{\frac{2\gamma}{\rho_g}, \frac{B_g}{l_g}\right\},
					\label{eq:conditionweakly}
				\end{align}
				where %the first inequality follows from the triangle inequality and~\Cref{ass:gradient}(b), and 
				the second inequality follows from $\alpha_k\leq \frac{C_0}{\beta l_g^2}$ and $\dist\left({\vx}^{(k)}, \Omega\right) \leq  \min\{\frac{\gamma }{2\rho_g}, \frac{B_g}{2l_g}\} $ by induction hypothesis, and the last one is derived using $\alpha_k \leq \min\{\frac{\gamma}{2l_f \rho_g}, \frac{B_g}{4 l_f l_g}\}$, and $C_0 \leq \min\{\frac{\gamma l_g}{\rho_g}, \frac{B_g}{4}\}$. 	
				We then obtain
				\begin{align}
					\notag	
					&\dist({\vx}^{(k+1)}, \Omega)  \leq \frac{g(\vx^{(k+1)})}{\gamma}
					\leq \frac{1}{\gamma} \left(g(\vx^{(k )}) + l_g \|{\vx}^{(k+1)}- {\vx}^{(k)}\|\right) \\\leq &\frac{1}{\gamma} \left(g(\vx^{(k )}) + \alpha_k l_g (l_f +\beta l_g) \right)    
					\leq \frac{C_0}{\gamma} +\frac{1}{\gamma} \left(\alpha_k  l_g l_f +  {C_0}{} \right)  
					\leq  \min\left\{\frac{\gamma}{2\rho_g},\,\frac{ B_g}{2l_g}\right\},
					\label{eq:distvxk1}
				\end{align}
				where the first inequality {uses}~\cref{lem:weakly1} {by}~\cref{eq:conditionweakly}, %and $g(\vx^{(k)})\leq B_g$, 
				the second/third one comes from the updating rule~\cref{eq:newupdate} and~\Cref{ass:problemsetup}(c), 
				the fourth one {holds because} 
				$g(\vx^{(k)})\leq C_0$ and $\alpha_k\leq \frac{C_0}{\beta l_g^2}$, and the last one {follows} by $
				C_0 \,\le\, \min\{\frac{\gamma^2}{8\rho_g},\,\frac{\gamma B_g}{8l_g}\},
				$
				and $
				\alpha_k \,\le\, \min\{\frac{\gamma^2}{4l_fl_g\rho_g},\,\frac{\gamma B_g}{4l_fl^2_g}\}.
				$
				Hence 
				$g({\vx}^{(k+1)}) \leq l_g \dist\left({\vx}^{(k+1)}, \Omega\right) \leq \frac{B_g}{2}$.

				Finally, combining the two above cases and applying the induction hypothesis, we complete the proof.
			\end{proof}

