						\right)
						\\ = & \left\langle\lambda^+ \boldsymbol{\zeta}_g, \mathbf{x}-\mathbf{x}^+\right\rangle
						-
						\frac{\lambda^+ \rho_g}{2} \|\mathbf{x}-\mathbf{x}^+\|^2
						=\left\|\mathbf{x}-\mathbf{x}^+\right\|^2-
						\frac{\lambda^+ \rho_g}{2} \|\mathbf{x}-\mathbf{x}^+\|^2.
					\end{aligned}
				\end{equation}
				Since $0<g(\vx)\leq l_g \dist\left(\mathbf{x}, \Omega\right) \le B_g$,
				dividing both sides of~\cref{eq:gdiff2} by \(\lambda^+\) yields
				\begin{align*}
					g(\mathbf{x})-g\left(\mathbf{x}^+\right)& \geq \frac{\left\|\mathbf{x}-\mathbf{x}^+\right\|^2}{\lambda^+} 
					-
					\frac{ \rho_g}{2} \|\mathbf{x}-\mathbf{x}^+\|^2
					= \| \boldsymbol{\zeta}_g\|\| \mathbf{x}-\mathbf{x}^+\|
					-
					\frac{ \rho_g}{2} \|\mathbf{x}-\mathbf{x}^+\|^2 \\
					&	\geq \sqrt{2B (\overline{\rho}-\rho_g)}\left\|\mathbf{x}-\mathbf{x}^+\right\|-
					\frac{ \rho_g}{2} \|\mathbf{x}-\mathbf{x}^+\|^2,
				\end{align*}	
				where the last inequality follows from~\cref{lem:app1}.
				{Noting   $g(\mathbf{x})=g_{+}(\mathbf{x})$ for $\mathbf{x} \not\in \Omega$, $g\left(\mathbf{x}^+\right)=0$ and $\|\mathbf{x}-\mathbf{x}^+\|= \dist(\vx,\Omega)\leq \frac{ \sqrt{2B (\overline{\rho}-\rho_g)}}{\rho_g}$, we obtain $\gamma\dist(\vx, \Omega)\leq g_+(\vx)$ and complete the proof. }
			\end{proof}
	\end{document}

