\section{Problem setting}\label{section:problem setting}
%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%
Consider a domain $\Omega\subset \bbR^{d=2,3}$, and two fields $R:\Omega \to \bbR$ and $T:\Omega\to \bbR$ referred to as \emph{reference} and \emph{target} (or template) images, where $R(\bx)$ and $T(\bx)$ denote the \emph{image intensity} at point $\bx$. \ac{dir} consists in finding a transformation under which the template image resembles the reference \cite{modersitzki2003numerical}, that is to find a mapping of $T$ onto $R$ by means of a warping $\bu$ 
such that 
	\begin{equation}\label{intro:equality}
		T(\bx + \bu(\bx)) \approx R(\bx) \quad \forall \, \bx \in \Omega\,.
	\end{equation}
	This can be reformulated as a variational problem 
	\begin{equation}\label{eqn:pvar}
\inf_{\bu\in \mathcal{V}}\alpha \mathcal{D}[\bu;R,T]+\mathcal{S}[\bu],
\end{equation}
where $\mathcal{V}$ models the admissible deformations space, $\mathcal{D}: \mathcal{V}\rightarrow\mathbb{R}$ is the aforementioned \emph{similarity measure}  which attains its minimum when \eqref{intro:equality} holds, $\mathcal S$ is a regulariser, and $\alpha$ is a regularisation parameter that balances the effects of $\mathcal D$ and $\mathcal S$. In this work we consider $\mathcal V=\bH^1(\Omega)$,  the $L^2$-norm of the error for the similarity, given by 
    \begin{equation*}
        \mathcal D[\bu; R, T] = \int_\Omega (T(\bx + \bu(\bx)) - R(\bx))^2\dx,
    \end{equation*}
and as a regulariser we use the elastic deformation energy, defined in the following manner 
    \begin{equation*}
        \mathcal{S}[\bu]:=\frac{1}{2}\int_{\Omega}{\bf \mathcal{C}}\mathbf{e}(\bu):\mathbf{e}(\bu)\dx.
    \end{equation*}
Here 
$\mathbf{e}(\bu)=\frac{1}{2}\{\bnabla \bu+(\bnabla \bu)^{\mathrm{t}}\}$ 
is the infinitesimal strain tensor, i.e., the symmetric component of the displacement field gradient, and ${\bf \mathcal{C}}$ is the elasticity tensor for isotropic solids:
\[%begin{equation}\label{eqn:tensor-C}
    {\bf \mathcal{C}}\btau=\lambda \tr(\btau)\mathbb{I}+2\mu\btau\quad \forall\btau\in\bbR^{d\times d}.
\]%end{equation}
Naturally, one may consider many other types of regularisations. See \cite{modersitzki2003numerical} for a review.
Assuming that (\ref{eqn:pvar}) has at least one solution with sufficient regularity, the associated Euler--Lagrange equations deliver the following strong problem with Robin or Neumann boundary conditions (representing springs of stiffness $\kappa\geq 0$): Find $\bu$ in $\bH^1(\Omega)$ such that
\begin{equation}\label{eqn:problem}
\begin{array}{rlll}       
 -\mathbf{div}({\bf \mathcal{C}}\mathbf{e}(\bu))& = &\alpha\boldsymbol{f_u}&\quad  \mathrm{in} \quad\Omega,\\[1ex]
{\bf \mathcal{C}}
\mathbf{e}(\bu)\bn + \kappa \bu & = & \boldsymbol{0}& \quad   \mathrm{on} \quad \partial\Omega,
 \end{array}
 \end{equation}
 where 
 \begin{equation}\label{eqn:problem-f}
\boldsymbol{f_u}(\boldsymbol{x})=\big\{T(\boldsymbol{x}+\bu(\boldsymbol{x}))-R(\boldsymbol{x})\big\}\nabla T(\boldsymbol{x}+\bu(\boldsymbol{x}))\quad \forall\boldsymbol{x} \in\Omega.
 \end{equation}
 For the analysis we assume that there are positive constants $L_f$ and $M_f$ such that the nonlinear load term $\boldsymbol{f_u}$ is Lipschitz continuous and uniformly bounded:
     \begin{equation}\label{eqn:assumps}
         |\boldsymbol{f_u}(\boldsymbol{x})-\boldsymbol{f_v}(\boldsymbol{x})| \leq L_f|\boldsymbol{u}(\boldsymbol{x})-\boldsymbol{v}(\boldsymbol{x})|, \quad 
          |\boldsymbol{f_u}(\boldsymbol{x})|\leq M_f\qquad  \forall\,\boldsymbol{x}\in \Omega\,\, a.e.
     \end{equation}
%Finally we have a \emph{family of deformations} $\bV$ 
%(such that $\bu\in \bV$), and, 
% a positive constant $\alpha$ (which balances $\mathcal D$ and $\mathcal S$), 
%	\begin{equation}\label{intro:min-prob}
%	\min_{\bv\in \bV}\,\Big\{ \alpha  \mathcal{D}(\bv) + \mathcal{S}(\bv)\Big\}.
%	\end{equation}

 Under the previous considerations, \eqref{eqn:pvar} becomes 
	\begin{equation*}%\label{intro:min-prob-otro}
        \min_{\bv\in \bH^1(\Omega)}\,\Big\{ \alpha  \int_\Omega |T(\bx + \bu(\bx)) - R(\bx)|^2\dx +\frac12 \int_\Omega \mathcal{C}\mathbf{e}(\bu):\mathbf{e}(\bu)\dx\Big\} + \kappa \int_{\partial\Omega}|\bu|^2\ds,
	\end{equation*}
with first order conditions given by the primal variational formulation for the registration problem: 
Find $\bu\in \bH^1(\Omega)$ such that
 \begin{equation}\label{eqn:prim}
 a(\bu,\bv)=\alpha F_{\bu}(\bv)\quad \forall\bv\in \bH^1(\Omega),
 \end{equation}
 where $a:\bH^1(\Omega)\times\bH^1(\Omega)\rightarrow\mathbb{R}$ is the bilinear form defined by
  \begin{equation}\label{a-primal}
      a(\bu,\bv) \coloneqq\int_{\Omega}{\bf \mathcal{C}}\mathbf{e}(\bu):\mathbf{e}(\bv)+\kappa\int_{\partial\Omega}\bu\cdot \bv\ds \quad\quad \forall\,\bu,\bv\in \bH^1(\Omega),   
  \end{equation}
  and for every $\bu\in\bH^1(\Omega)$, $F_{\bu}:\bH^1(\Omega)\rightarrow\mathbb{R}$ is the linear functional given by
  \begin{equation}
  F_{\bu}(\bv)   \coloneqq-\int_{\Omega}\boldsymbol{f}_{\bu}\cdot \bv \qquad\qquad\forall\, \bv \in\bH^1(\Omega).
  \end{equation}
The conditions (\ref{eqn:assumps}) imply  the Lipschitz continuity and uniform boundedness of $F_{\bu}$, that is
  \begin{equation}\label{eqn:lipschitz}
  \| F_{\bu}- F_{\bv}\|_{{\bH^1(\Omega)}^{\prime}}\leq L_F\|\bu-\bv\|_{0,\Omega}, \qquad 
   \| F_{\bu}\|_{{\bH^1(\Omega)}^{\prime}}\leq M_F 
  \qquad \forall\,\bu,\bv\in \bH^1(\Omega),
  \end{equation}
  respectively. We recall the results concerning the  solvability  of (\ref{eqn:prim}), as developed in \cite[Section 3]{barnafi2018primal}. For it, whenever $\kappa=0$ we need to modify the solution space in order to guarantee uniqueness. We will denote with $\mathbb{RM} = \ker(\mathcal S)$ as the space of rigid body modes, and thus consider the solution space given by 
    \begin{equation*}
        \bV = \begin{cases} \bH^1(\Omega) & \kappa>0 \\ \bH^1(\Omega) \cap \left[\mathbb{RM}\right]^\perp & \kappa = 0\end{cases}.
    \end{equation*}
With it, we define the following linear auxiliary problem: Given $\bz\in \bH^1(\Omega)$, find $\bu\in \bV$ such that
   \begin{equation}\label{eqn:prim-z}
   a(\bu,\bv)=\alpha F_{\bz}(\bv),\quad \bv\in \bV.
   \end{equation}

   \begin{theorem}
Given $\bz\in \bH^1(\Omega)$, problem  \eqref{eqn:prim-z} has a unique solution $\bu\in \bV$, and there exists  $C_p > 0$ such that 
$$\|\bu\|_{1,\Omega}\leq \alpha C_p\| F_{\bz}\|_{{\bH^1(\Omega)}^{\prime}}\,.$$
\end{theorem}

We now define the operator $\mathbf{\widehat T} : \bV\rightarrow \bV$ given by $\mathbf{\widehat T}(\bz)=\bu$, where $\bu$ is the unique solution to problem (\ref{eqn:prim-z}) and thus rewrite (\ref{eqn:prim}) as the fixed-point equation: Find $\bu$ in $\bV$ such that
\begin{equation}\label{T}
\mathbf{\widehat T}(\bu)=\bu.
\end{equation}

The following result, {also proven in \cite[Theorem 3]{barnafi2018primal}, establishes the existence and uniqueness} of solution to the fixed-point equation (\ref{T}) whenever $\kappa=0$.
\begin{theorem}
Under data assumptions {\rm(\ref{eqn:assumps})}, the operator $\mathbf{\widehat T}$ has at least one fixed point. Moreover, if $\alpha C_p L_F < 1$, the fixed point is unique.
\end{theorem}
Throughout the manuscript, we will use $\bV$ to write our problem in order to avoid technicalities regarding the implementation of rigid body modes $\mathbb{RM}$ whenever $\kappa=0$. We enforce it in practice by means of an adequate Lagrange multiplier as in \cite{barnafi2018primal}. 

