\section{Adaptive discretisation scheme}\label{section:fem}
%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%
Let $\bV_h$ be a finite dimensional subspace of $\bV$ built out of a suitable mesh partition $\mathcal T_h$ of $\Omega$ into quadrilateral or hexahedral elements, where $h$ denotes the mesh size. The primal nonlinear discrete problem consists in finding  $\bu_h\in \bV_h$ such that
     \begin{equation}\label{eqn:primdisc}
    a(\bu_h,\bv_h)=\alpha F_{\bu_h}(\bv_h)\quad \forall\bv_h\in \bV_h.
    \end{equation}
Analogously to the continuous case, we consider the auxiliary linear problem: Given $\bz_h\in \bV_h$, find $\bu_h\in \bV_h$ such that
     \begin{equation}\label{eqn:primdisc-zH}
     a(\bu_h,\bv_h)=\alpha F_{\bz_h}(\bv_h)\quad \forall\bv_h\in\bV_h,
     \end{equation}
and also let  $T_h: \bV_h\rightarrow \bV_h$ be the discrete operator given by $T_h(\bz_h)=\bu_h$, where $\bu_h$ is the solution to problem (\ref{eqn:primdisc-zH}). Considering the same data assumptions as in the continuous case, as well as the continuity and bound obtained before, we arrive at the following result proven in \cite[Theorem 5]{barnafi2018primal}, adapted to include the terms arising from $\kappa\neq 0$.
\begin{theorem}
Assume that data assumptions {\rm(\ref{eqn:assumps})} hold. Then, the operator $T_h$ has at least one fixed point. Moreover, if $\alpha C_p L_F < 1$, then such fixed point is unique.
\end{theorem}
Next, we define for each $K\in\mathcal{T}_h$ the \emph{a-posteriori} error indicator
\begin{align}\label{eqn:estimatorprim}
 %\begin{split}   
\nonumber   \Theta_K^2 & \coloneqq h_K^2\|\alpha\boldsymbol{f}_{\bu_h}\! - \textbf{div}({\bf \mathcal{C}}\mathbf{e}(\bu_h))\|_{0,K}^2 +\!\!\!\sum_{e\in\mathcal{E}(K)\cap\mathcal{E}_h(\Omega)}\!\!\! h_e\|[{\bf \mathcal{C}}\mathbf{e}(\bu_h)\bn_e]\|_{0,e}^2 \\
&\qquad        + \!\!\! \sum_{e\in\mathcal{E}(K)\cap\mathcal{E}_h(\Gamma)}\!\!\!h_e\|{\bf \mathcal{C}}\mathbf{e}(\bu_h)\bn_e+\kappa\bu_h\|_{0,e}^2,
       %+ \!\!\! \sum_{e\in\mathcal{E}(K)\cap\mathcal{E}_h(\Gamma)}\!\!\!h_e\|{\bf \mathcal{C}}\mathbf{e}(\bu_h)\bn_e\|_{0,e}^2,
   %\end{split}
 \end{align}
where, according to (\ref{eqn:problem-f}),
$$\left.\boldsymbol{f}_{\bu_h}\right|_K(\boldsymbol{x})\coloneqq\big\{T(\boldsymbol{x}+\bu_h(\boldsymbol{x}))-R(\boldsymbol{x})\big\}\nabla T(\boldsymbol{x}+\bu_h(\boldsymbol{x}))\quad \forall\,\boldsymbol{x}\in K,$$
and introduce the global {\it a-posteriori} error estimator
\begin{equation*}
 \Theta\coloneqq\left\{ \sum_{K\in\mathcal{T}_h}\Theta_K^2\right\}^{1/2}.
\end{equation*}
 The following theorem constitutes the main result of this section.

\begin{theorem}
Let  $\bu\in \bV$ and  $\bu_h\in \bV_h$ be the solutions of {\rm(\ref{eqn:prim})} and {\rm(\ref{eqn:primdisc})}, respectively, and assume
 that $\alpha C_p L_F<1/2$. Then,  there exist positive constants $h_0,\,C_{\mathrm{rel}},\,C_{\mathrm{eff}}$ independent of $h$ such that for $h\leq h_0 $ there holds
\begin{equation}\label{eqn:cotasprim}
 C_{\mathrm{eff}}\Theta \leq \|\bu-\bu_h\|_{1,\Omega} \leq  C_{\mathrm{rel}}\Theta.
\end{equation}
\end{theorem}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
{The reliability (upper bound in (\ref{eqn:cotasprim})) and the efficiency (lower bound in (\ref{eqn:cotasprim})) of $\Theta$  are established separately in the following two lemmas. }
%\subsubsection{Reliability}\label{sec:reliableprim}
%The upper bound for (\ref{eqn:cotasprim}) is established as follows.
\begin{lemma}\label{lem:relprim}
Assume that $\alpha C_pL_F<1/2$. Then,  there exist positive constants $h_0,\,C_{\mathrm{rel}}$ independent of $h$, such that for $h\leq h_0 $ there holds
 $$\|\bu-\bu_h\|_{\bV} \leq  C_{\mathrm{rel}}\,\Theta.$$
\end{lemma}
 \begin{proof}
Let us first define
$$\mathcal{R}_h(\bw-\bw_h)\coloneqq\alpha F_{\bu}(\bw-\bw_h)-a(\bu_h,\bw-\bw_h)\quad \forall\bw_h\in \bV_h.$$
 As a consequence of the ellipticity of $a$ (c.f. (\ref{a-primal})) with ellipticity constant $\bar{\alpha}$ (c.f. \cite[Corollary 11.2.22]{brenner2008mathematical}), we obtain the following condition
 \begin{equation*}
 \bar{\alpha}\|\bv\|_{1,\Omega} \leq\sup_{\substack{\bw\in \bH^1(\Omega)\\ \bw\neq\boldsymbol{0}}}\frac{a(\bv,\bw)}{\|\bw\|_{\bV}}\quad \forall\bv\in \bH^1(\Omega).
 \end{equation*}
 In particular, for $\bv\coloneqq\bu-\bu_h\in \bH^1(\Omega)$, we notice from (\ref{eqn:prim}) and (\ref{eqn:primdisc}) that $a(\bu-\bu_h,\bw_h)=0$ $\,\forall\bw_h\in \bV_h$, and hence we obtain $a(\bu-\bu_h,\bw)=a(\bu-\bu_h,\bw-\bw_h)=\mathcal{R}_h(\bw-\bw_h)$, which yields
 \begin{equation}\label{eqn:issus}
 \bar{\alpha}\|\bu-\bu_h\|_{1,\Omega} \leq\sup_{\substack{\bw\in \bH^1(\Omega)\\ \bw\neq\boldsymbol{0}}}\frac{\mathcal{R}_h(\bw-\bw_h)}{\|\bw\|_{1,\Omega}}\quad \forall\bw_h\in \bV_h.
 \end{equation}
 From the definition of $\mathcal{R}_h(\bw-\bw_h)$, integrating by parts on each $K\in\mathcal{T}_h$, and adding and subtracting  a suitable term, we can write
 \begin{equation}\label{eqn:R}
 \begin{array}{l}
 \mathcal{R}_h(\bw-\bw_h)=\,\alpha F_{\bu_h}(\bw-\bw_h)+\alpha F_{\bu}(\bw-\bw_h)-a(\bu_h,\bw-\bw_h)-\alpha F_{\bu_h}(\bw-\bw_h)\\
              \quad \displaystyle{=\,\alpha\left\{F_{\bu}(\bw-\bw_h)-F_{\bu_h}(\bw-\bw_h)\right\}-\alpha\int_{\Omega}\boldsymbol{f}_{\bu_h}\cdot (\bw-\bw_h)}
             \\
 \qquad               \displaystyle{\,-\sum_{K\in\mathcal{T}_h}\int_K{\bf \mathcal{C}}\mathbf{e}(\bu_h):\mathbf{e}(\bw-\bw_h)} \\
           \quad   =\displaystyle{\,\alpha\{(F_{\bu}-F_{\bu_h})(\bw-\bw_h)\}-\alpha\int_{\Omega}\boldsymbol{f}_{\bu_h}\cdot (\bw-\bw_h)}\\
              \qquad \displaystyle{\,-\sum_{K\in\mathcal{T}_h} \left\{-\int_K\mathbf{div}({\bf \mathcal{C}}\mathbf{e}(\bu_h))\cdot(\bw-\bw_h)+\int_{\partial K}({\bf \mathcal{C}}\mathbf{e}(\bu_h) \bn_e)\cdot(\bw-\bw_h)\right\},}\\
              \quad \displaystyle{=\,\alpha\{(F_{\bu}-F_{\bu_h})(\bw-\bw_h)\}+\sum_{K\in\mathcal{T}_h}\int_K(\mathbf{div}({\bf \mathcal{C}}\mathbf{e}(\bu_h))-\alpha\boldsymbol{f}_{\bu_h})\cdot (\bw-\bw_h)}\\
               \qquad\displaystyle{\,-\sum_{e\in\mathcal{E}_h(\Omega)}\int_e\left[ ({\bf \mathcal{C}}\mathbf{e}(\bu_h) \bn_e)\right] \cdot(\bw-\bw_h)
               -\sum_{e\in\mathcal{E}_h(\Gamma)}\int_e({\bf \mathcal{C}}\mathbf{e}(\bu_h) \bn_e +\kappa\bu_h)\cdot(\bw-\bw_h).}
 \end{array}
 \end{equation}
 Then, choosing $\bw_h$ as the Cl\'ement interpolant of $\bw$, that is $\bw_h\coloneqq I_h(\bw)$, the approximation properties of $I_h$ yield \cite{clement1975approximation}
 \begin{align}\label{eqn:clement}
 \left\| \bw-\bw_h \right\|_{0,K}\leq  c_1h_K\left\| \bw\right\|_{1,{\square(}K)}, \qquad 
 \left\| \bw-\bw_h \right\|_{0,e}\leq  c_2h_e\left\| \bw\right\|_{1,{\square(}e)},
 \end{align}
 where ${\square(}K)\coloneqq \cup\{K'\in \mathcal{T}_h: K'\cap K \neq \emptyset\}$ and $ {\square(}e) \coloneqq \cup\{K'\in \mathcal{T}_h: K'\cap e \neq \emptyset\}$.  In this way, applying the Cauchy--Schwarz inequality to each term (\ref{eqn:R}),
 and making use of (\ref{eqn:clement}) together with  the
 Lipschitz continuity of $F_{\bu}$ (cf. (\ref{eqn:lipschitz})), we obtain
 \begin{align*}
 \mathcal{R}_h(\bw-\bw_h) &\,\le\,
 \alpha c_1L_Fh_K\|\bu-\bu_h\|_{1,\Omega}\|\bw\|_{1,{\square(}K)} \\
& \quad
 + \,\, \widehat{C}\left\{ \sum_{K\in\mathcal{T}_h}\Theta_K^2\right\}^{1/2}
 \left\{\sum_{K\in\mathcal{T}_h}\|\bw\|_{1,{\square(}K)}^2+\sum_{e\in\mathcal{E}_h(\Omega)}\,
 \|\bw\|_{1,{\square(}e)}^2\right\}^{1/2}\,,
 \end{align*}
 where $\widehat{C}$ is a constant depending on $c_1$ and $c_2$ and $\Theta_K^2$ defined by (\ref{eqn:estimatorprim}). Additionally using the fact that the number of elements in
 ${\square(}K)$ and ${\square(}e)$ is bounded, we have
 $$\sum_{K\in\mathcal{T}_h}\|\bw\|_{1,{\square(}K)}^2\leq C_1\|\bw\|_{1,\Omega}^2\qquad{\rm and}\qquad\sum_{e\in\mathcal{E}_h(\Omega)}\|\bw\|_{1,{\square(}e)}^2\leq C_2\|\bw\|_{1,\Omega}^2,$$
 where $C_1,\,C_2$ are positive constants,  and using that $\alpha C_p L_F\leq 1/2$, it follows that $h_0\coloneqq 1/(2c_1\alpha L_F)$. Finally, substituting in (\ref{eqn:issus}) we conclude that
 $$\|\bu-\bu_h\|_{1,\Omega} \leq  C_{\mathrm{rel}}\,\Theta,$$
 where $C_{\mathrm{rel}}$ is independent of $h$.
 \end{proof}


The efficiency bound requires using a localisation technique based on element-bubble and edge-bubble functions. Given $K\in\mathcal{T}_h$ and $e\in\mathcal{E}(K)$, we define $\psi_K$ and $\psi_e$ the typical {element-} and edge-bubble functions \cite[eqs. (1.5)-(1.6)]{verfurth1999review}, which satisfy:
\begin{itemize}
\item [(i)] $\psi_K\in P_3(K)$, $\psi_K=0$ on $\partial K$, $\mathrm{supp}(\psi_K)\subseteq K$, and $0\leq\psi_K\leq 1$ in $K$,
\item [(ii)]  $\psi_e\in P_2(K)$, $\psi_e=0$ on $\partial K$, $\mathrm{supp}(\psi_e)\subseteq \omega_e$, and $0\leq\psi_e\leq 1$ in $\omega_e$,
\end{itemize}
where $\omega_e\coloneqq\cup\{K^{\prime}\in\mathcal{T}_h:\,\,e\in\mathcal{E}(K^{\prime})\}$.
Additional properties of $\psi_K$ and $\psi_e$ are collected in the following lemma (c.f. \cite[Lemma 1.3]{verfurth1994posteriori}, \cite[Section 3.4]{verfurth1996review}  or \cite[Section 4]{verfurth1999review}).
\begin{lemma}\label{lem:bubbles}
Given $k\in\mathbb{N}\cup\{0\}$, there exist positive constants $\gamma_1$, $\gamma_2$, $\gamma_3$, $\gamma_4$ and $\gamma_5$, depending only on k and the shape regularity of the
triangulations, such that for each $K\in\mathcal{T}_h$ and $e\in\mathcal{E}(K)$, there hold
\begin{equation}\label{eqn:bubble}
\begin{array}{rlll}
\gamma_1\left\| q\right\|_{0,K}^2&\leq& \left\| \psi_K^{1/2}q\right\|_{0,K}^2&\quad \forall\, q\in P_k(K),\\[1ex]
\left\| \psi_Kq\right\|_{1,K}&\leq& \gamma_2h_K^{-1}\left\| q\right\|_{0,K}&\quad \forall\, q\in P_k(K),\\[1ex]
\gamma_3\left\| p\right\|_{0,e}^2&\leq& \left\| \psi_e^{1/2}p\right\|_{0,e}^2&\quad \forall\, p\in P_k(e),\\[1ex]
\left\| \psi_ep\right\|_{1,\omega_e}&\leq& \gamma_4h_e^{-1/2}\left\| p\right\|_{0,e}&\quad \forall \,p\in P_k(e),\\[1ex]
\left\| \psi_ep\right\|_{0,\omega_e}&\leq &\gamma_5h_e^{1/2}\left\| p\right\|_{0,e}&\quad \forall\, p\in P_k(e).
\end{array}
\end{equation}
\end{lemma}

The efficiency (lower bound in (\ref{eqn:cotasprim})) is established with the help of the following lemma whose proof is a slight modification of \cite[Section 6]{verfurth1999review}.
\begin{lemma} \label{lem:effiprim}
    There exist constants $\eta_1,\eta_2,\eta_3>0$ and $C_{\mathrm{eff}}>0$, independent of $h$, but depending on $\gamma_i$ for $i\in\{1,\dots,5\}$ from Lemma~\ref{lem:bubbles} , such that for each $K\in\mathcal{T}_h$ there holds
\begin{align*}
h_K\left\|\alpha\boldsymbol{f}_{\bu_h} - \textrm{\bf div}({\bf \mathcal{C}}\mathbf{e}(\bu_h))\right\|_{0,K}&\leq \eta_1\| \bu-\bu_h\|_{0,K},\\ h_e^{1/2}\|[{\bf \mathcal{C}}\mathbf{e}(\bu_h)\cdot\bn_e]\|_{0,e}&\leq \eta_2\left\{\| \bu-\bu_h\|_{0,\omega_e}+\sum_{K\in \omega_e}h_K\|\bu-\bu_h\|_{0,K} \right\}, \\
h_e^{1/2}\|{\bf \mathcal{C}}\mathbf{e}(\bu_h)\cdot\bn_e\|_{0,e}&\leq \eta_3\| \bu-\bu_h\|_{0,K},
\end{align*}
where $\omega_e\coloneqq\cup\{K^{\prime}\in\mathcal{T}_h:\,\,e\in\mathcal{E}(K^{\prime})\}$. Further, it holds that
\begin{equation*}
    C_{\mathrm{eff}}\Theta \leq \|\bu-\bu_h\|_{1,\Omega}.
\end{equation*}

\end{lemma}
\begin{proof}
Using the properties of bubble functions, and letting $R_K(\bu_h)\coloneqq\alpha\boldsymbol{f}_{\bu_h} - \textrm{\bf div}({\bf \mathcal{C}}\mathbf{e}(\bu_h))$ we have
\begin{align*}
\left\| R_K(\bu_h)\right\|_{0,K}^2&\leq \gamma_1^{-1}\left\|\psi_K^{1/2}R_K(\bu_h)\right\|_{0,K}^2\\
%&=\gamma_1^{-1}\int_K \psi_KR_K(\bu_h)\big\{\alpha\boldsymbol{f}_{\bu_h} - \textrm{\bf div}({\bf \mathcal{C}}\mathbf{e}(\bu_h))\},\\[2ex]
&=\frac{1}{\gamma_1}\int_K \alpha\psi_KR_K(\bu_h)\{\boldsymbol{f}_{\bu_h}-\boldsymbol{f}_{\bu}\} -\frac{1}{\gamma_1}\int_K\psi_KR_K(\bu_h)\{ \textrm{\bf div}({\bf \mathcal{C}}\mathbf{e}(\bu_h)-{\bf \mathcal{C}}\mathbf{e}(\bu))\},\\
&=\frac{1}{\gamma_1}\int_K \alpha\psi_KR_K(\bu_h)\big\{\boldsymbol{f}_{\bu_h}-\boldsymbol{f}_{\bu}\} +\frac{1}{\gamma_1}\int_K({\bf \mathcal{C}}\mathbf{e}(\bu_h)-{\bf \mathcal{C}}\mathbf{e}(\bu))\cdot\nabla(\psi_KR_K(\bu_h)),\\
&\leq \frac{\alpha}{\gamma_1}\|R_K(\bu_h)\|_{0,K}\|\boldsymbol{f}_{\bu_h}-\boldsymbol{f}_{\bu}\|_{0,K} \\
& \qquad + \frac{\gamma_2}{\gamma_1h_K}\|{\bf \mathcal{C}}\mathbf{e}(\bu_h)-{\bf \mathcal{C}}\mathbf{e}(\bu)\|_{0,K}\|R_K(\bu_h)\|_{0,K},
\end{align*}
where, for the last inequality we used the inverse inequality. Next, we have
$$h_K\|R_K(\bu_h)\|_{0,K}\leq \alpha h_K \gamma_1^{-1}\|\boldsymbol{f}_{\bu_h}-\boldsymbol{f}_{\bu}\|_{0,K}+ \gamma_1^{-1}\gamma_2\|{\bf \mathcal{C}}\mathbf{e}(\bu_h)-{\bf \mathcal{C}}\mathbf{e}(\bu)\|_{0,K},$$
now, using (\ref{eqn:assumps}) and grouping terms, we conclude with $\eta_1>0$ independent of $h$, that 
$$h_K\left\|\alpha\boldsymbol{f}_{\bu_h} - \textrm{\bf div}({\bf \mathcal{C}}\mathbf{e}(\bu_h))\right\|_{0,K}\leq \eta_1\| \bu-\bu_h\|_{0,K}.$$
 We omit further details and repeated arguments used for the remaining inequalities.
\end{proof}




