\section{Methodology}
\label{Methodology}
\subsection{Overall Framework}
% We present the XiYan-SQL framework, as shown in Figure \ref{fig:pipeline}.
We present the XiYan-SQL framework in Figure \ref{fig:pipeline}, where the inputs include a question, evidence (i.e., external knowledge), and the database schema (i.e., the overall organization of tables, columns, and values within the database).
The framework consists of three steps: Schema Filter, Multiple SQL Generation, and SQL Selection.
% The Schema Filter module initially generates multiple filtered schemas based on the input.
The Schema Filter module initially generates multiple filtered schemas.
Subsequently, multiple candidate SQL queries are generated through various SQL generators. 
Finally, the most accurate SQL query is selected by the selection model based on the candidate reorganization. 
The details of each step are described below.


\subsection{Schema Filter}
% Our Schema Filter Module consists of schema retrieval and schema selection, designed to effectively implement schema linking for large databases and generate multiple filtered schemas.
Our Schema Filter Module consists of multi-path retrieval and column selection, designed to effectively implement schema linking for large databases and generate multiple filtered schemas.
\\
% \textbf{Schema Retrieval.}\hspace{1em}The Schema Retrieval functions as a pruning mechanism for large databases by employing cosine similarity across all tables, columns and values.
\textbf{Multi-path Retrieval.}\hspace{1em}Multi-path Retrieval is a pruning mechanism for large databases that employ cosine similarity for the embeddings of all tables, columns, and values.
% Multi-path Retrieval is a pruning mechanism for large databases that employ cosine similarity across all tables, columns, and values.
% The Multi-path Retrieval functions as a pruning mechanism for large databases by employing cosine similarity across all tables, columns and values.
Initially, we used an out-of-the-box LLM $\mathcal{M}_s$ to extract keywords from the question $Q$ and evidence $E$, represented as $K = f_{\mathcal{M}_s}(Q,E)$.
These keywords, denoted as $K = \{ k_1, k_2, \ldots \}$, are instrumental in identifying relevant columns and values within the database.
% Subsequently, in the column retrieval stage, we compute scores between each keyword $k_i$ and column $c_j$, calculated as the product of two distinct scores as follows.
In the table and column retrieval stage, we compute the scores between the keywords $K$ and the original schema $S$, which can be represented as a set of columns, $\{ c_1, c_2, \ldots \}$.
This process is calculated as the product of two distinct scores as follows.
% In the column retrieval stage, we compute a score between each keyword $k_i$ and column $c_j$, calculated as the product of two distinct scores as follows.

\begin{equation}
% \small
\resizebox{0.4\textwidth}{!}{$\text{Score}(k_i, c_j) = \left\langle \mathbf{V}_{Q||E}, \mathbf{V}_{Tab({c_j})} \right\rangle \cdot \left\langle \mathbf{V}_{k_i}, \mathbf{V}_{c_j} \right\rangle$}
\label{eq:col_retriever_score}
\end{equation}
One part is the cosine similarity between the embedding of the keyword $\mathbf{V}_{k_i}$ and that of the column metadata $\mathbf{V}_{c_j}$.
% The other part is calculated by the cosine similarity between original input and the table metadata.
The other part is the calculation between the input text and the table metadata.
In detail, we concatenate the query and evidence to obtain the embedding representation $\mathbf{V}_{Q||E}$.
The table to which $c_j$ belongs can be determined by projection $Tab$, and the embedding representation of the table is $\mathbf{V}_{Tab({c_j})}$.
% We identify the most relevant columns for each keyword through this process.
Through this process, we identify the top-$k$ columns that are most relevant to each keyword.

% For the value retrieval stage, we use edit distance to locate similar values for each keyword. 
For the value retrieval, we first use edit distance to locate the top-$k$ values of each column that are similar to each keyword.
Subsequently, we employ the RoBERTa tokenizer to uniquely tokenize the value text along with column metadata. 
This step enhances the efficiency of Locality Sensitive Hashing \cite{datar2004locality} in filtering text related to values. 
An embedding cosine similarity is then applied, using a threshold to refine the retrieved values. 
% Embedding cosine similarity is then applied, using a threshold to refine the retrieved values. 
Through multi-path retriever, we filter out a schema $S^{rtrv} = \{ c_{r_1}, c_{r_2}, \ldots \}$ from the original schema $S$.
\\
% \textbf{Schema Selection.}\hspace{1em}
% The Schema Selection introduces diversity into the filtered schemas, facilitating subsequent multiple SQL generation.
\textbf{Column Selection.}\hspace{1em}Column Selection introduces diversity into the retrieved schemas, facilitating subsequent multiple SQL generation.
This process is detailed in Algorithm \ref{alg:schema selector}, which outputs $p_s$ different schemas through multiple iterations.
% leverages multiple iterations of language model usage to produce different schemas.
In each iteration, we prompt an LLM $\mathcal{M}_s$ to select columns related to the question and evidence, saved as $S^{slct}_i$. 
The function $\text{PFKeyIdentifier}$ then identifies primary and foreign keys according to the columns in $S^{slct}_i$.
A new schema is generated by unifying the previous schemas with the selected columns.
The selected columns in this iteration are removed from $S^{rtrv}$, while retaining essential columns such as primary keys.
% except for essential columns such as primary keys, which are retained.
As iterations increase, the precision of the selected schemas tends to decrease while recall improves, resulting in a diversity of filtered schemas.
% \vspace{-4pt}
\renewcommand{\algorithmicrequire}{ \textbf{Input:}}
\renewcommand{\algorithmicensure}{ \textbf{Output:}}
% \resizebox{0.4\textwidth}{!}{
% \begin{algorithm}[H]
\begin{algorithm}
% \caption{Schema Selection}
\caption{Column Selection Algorithm}
\label{alg:schema selector}
% \small
% \footnotesize 
% \scriptsize
\begin{algorithmic}[1]
    \REQUIRE Set of columns $S^{rtrv} = \{ c_{r_1}, c_{r_2}, \ldots \}$, Question $Q$, Evidence $E$, The maximum iteration $p_{s}$
    \ENSURE Schema set $\mathcal{S} = \{ S_1, \ldots, S_{p_s}\}$
    % \STATE $U \gets \emptyset$ \COMMENT {selected columns in iterations}
    \STATE Initialize a list $\mathcal{S} \gets [\ ]$
    \FOR{$i = 1$ to $p_{s}$}
        \STATE $S^{slct}_i \gets f_{\mathcal{M}_s}(S^{rtrv}, Q, E)$  \COMMENT {Select from $S^{rtrv}$}
        \STATE $P_i \gets \text{PFKeyIdentifier}(S^{slct}_i)$ 
        % \COMMENT {Identify primary and foreign keys}
        \STATE $S_i \gets \left( \bigcup_{k=1}^{i-1} S_k \right) \cup S^{slct}_i \cup P_i$ \COMMENT {Unify and generate $S_i$}
        \STATE Append $S_i$ to $\mathcal{S}$

        % \STATE $U \gets U \cup S^{slct}_i$ 

        \STATE $S^{rtrv} \gets S^{rtrv} \setminus (S^{slct}_i \setminus P_i)$ \COMMENT{Remove the selected}
    \ENDFOR
    \RETURN $\mathcal{S}$
\end{algorithmic}
\end{algorithm}
