\begin{algorithmic}[1]
    \REQUIRE Question $Q$, Evidence $E$, Filtered Schema set $\mathcal{S} = \{ S_1, \ldots, S_{p_s}\}$, List of SQL Generators $\mathcal{M}$, DataBase $D$
