    \ENSURE Candidate SQL list $L = \{ l_1, \ldots, l_{p_l}\}$
    % Schema set $\mathcal{S} = \{ S_1, \ldots, S_{p_s}\}$

    \STATE Initialize Candidate SQL $L \gets \emptyset$
    % and execution results $R \gets \emptyset$ 
    % \FOR{each Schema $S_i \in \mathcal{S}$}
    \FOR{$i = 1$ to $p_{s}$}
        \FOR{$j = 1$ to $p_{m}$}
        % \FOR{each Model $M_j \in \mathcal{M}$}
            \STATE Predict SQL $l_{ij} \gets f_{\mathcal{M}_j}(Q, E, S_i)$
            \STATE Execute Result $r \gets \text{execute}(l, D)$

            \IF{No exception in $r$}
                \STATE Append $l_{ij}$ to $L$
            \ELSE
                \FOR{retry $1$ times}
                    % \STATE Refine SQL $\hat{l} \gets M_i.\text{refine}(Q, E, \mathcal{S}, l,r)$
                    \STATE $\hat{l}_{ij} \gets f_{\mathcal{M}_j}(Q, E, S_i, l, r)$ \COMMENT{Self-refine}
                    % \STATE Execution Result $\hat{r} \gets \text{execute}(\hat{l}, \mathcal{S})$
                    % \STATE $l\gets \hat{l}$, $r\gets \hat{r}$
                    \STATE Append $\hat{l}_{ij}$ to $L$
                    % \IF{No error in $\hat{r}$}
                    %     \STATE Append $L_i \gets l$  and $R_i \gets r$
                    %     \STATE \textbf{break}
                    % \ENDIF
                \ENDFOR
            \ENDIF
        \ENDFOR
    \ENDFOR
    \RETURN $L$
\end{algorithmic}
\end{algorithm}

