      Automaton* A = new Automaton("A.txt");
      Automaton* B = safetyClosure(A, LimInfAvg);
      Automaton* C = livenessComponent(A, LimInfAvg);
      bool flagEmpt = A->isNonEmpty(LimInfAvg, 5, &witEmpt);
