\section{Overview of LiB Cell Model Equations} \label{section_2}

The ESPM is a control-oriented model that captures the essential electrochemical behavior of li-ion batteries. It improves upon the traditional Single Particle Model (SPM) by incorporating electrolyte dynamics, which are crucial for accurate voltage prediction \cite{fan2016modeling}. The ESPM simplifies the detailed Pseudo Two-Dimensional (P2D) model by representing each electrode as a single spherical particle, retaining the key physics of lithium intercalation and deintercalation within the solid phase. 

The solid-phase lithium concentration $ c_{s,i}$ (where $i = n,p$) dynamics is governed by Fick’s second law:

\begin{equation} 
\frac{\partial c_{s,i}(r, t)}{\partial t} = D_{s,i} \frac{\partial^2 c_{s,i}(r, t)}{\partial r^2} + \frac{2 D_{s,i}}{r} \frac{\partial c_{s,i}(r, t)}{\partial r}
\label{eq:ficks_law}
\end{equation}

\noindent where $r$ is the radial coordinate within the particle. %The associated boundary conditions are:
%\begin{equation} \label{eq:130}
%\left. \frac{\partial c_{s,i}(r, t)}{\partial r} \right|_{r=0} = 0 \quad
%\end{equation}
%\begin{equation} \label{eq::140}
%\quad D_{s,i} \left. \frac{\partial c_{s,i}(r, t)}{\partial r} \right|_{r=R_i} = -\frac{J_i(t)}{F}
%\end{equation}

The dynamics of lithium concentration in the electrolyte phase is described by:
\begin{equation}
\epsilon_{e,i} \frac{\partial c_{e}(x,t)}{\partial t} = D_{e,i} \frac{\partial^2 c_{e}(x,t)}{\partial x^2} + \frac{a_i (1 - t_0^+)}{F} J_i(t)
\label{eq:ficks_law_liquid}
\end{equation}
\noindent where $\epsilon_{e,i}$ is the porosity, $D_{e,i}$ the effective diffusion coefficient, $c_e$ the electrolyte concentration, $t_0^+$ the transference number, $x$ the spatial coordinate, and $a_i$ is the specific surface area. For brevity, the boundary conditions associated with Equations \eqref{eq:ficks_law} and \eqref{eq:ficks_law_liquid} are provided in \cite{fan2016modeling}.%The boundary conditions for the electrolyte concentration are:
% \begin{equation}
% \left. \frac{\partial c_e(x,t)}{\partial x} \right|_{x=0} = 0, \quad \left. \frac{\partial c_e(x,t)}{\partial x} \right|_{x=L} = 0
% \end{equation}

% % \begin{equation}
% % \left. \frac{\partial c_e(x,t)}{\partial x} \right|_{x=L} = 0
% % \end{equation}

% \begin{equation}
% c_e(x,t)\big|_{x=L_p^-} = c_e(x,t)\big|_{x=L_p^+}
% \end{equation}

% \begin{equation}
% c_e(x,t)\big|_{x=L_p + L_s^-} = c_e(x,t)\big|_{x=L_p + L_s^+}
% \end{equation}

% \begin{equation}
% -D_{e,p} \left. \frac{\partial c_e(x,t)}{\partial x} \right|_{x=L_p^-} = 
% -D_{e,s} \left. \frac{\partial c_e(x,t)}{\partial x} \right|_{x=L_p^+}
% \end{equation}

% \begin{equation}
% -D_{e,s} \left. \frac{\partial c_e(x,t)}{\partial x} \right|_{x=L_p + L_s^-} =
% -D_{e,n} \left. \frac{\partial c_e(x,t)}{\partial x} \right|_{x=L_p + L_s^+}
% \end{equation}


The kinetic overpotential $\eta_i$ is given by:
\begin{equation}
\eta_i(t) = \frac{{R}T}{\alpha F} \sinh^{-1} \left( \frac{J_i(t)}{2 i_{0,i}(t)} \right)
\end{equation}
\noindent where the exchange current density $i_{0,i}$ depends on the kinetic rate constant $K_k$, maximum electrode concentration $c_{s,\text{max},i}$, and average electrolyte concentration $c_e$:
\begin{equation}
i_{0,k}(t) = F K_k \sqrt{c_{s,\text{surf},k} \left( c_{s,\text{max},k} - c_{s,\text{surf},k} \right) c_{e}}
\end{equation}
\par The liquid phase potential $\phi_e$ \eqref{eq::180} is defined as a function of the effective ionic conductivity $\kappa^{eff}$, the effective diffusional conductivity  $\kappa_D^{eff}$, and the ionic current $i_e$ in the liquid phase.


\begin{equation} \label{eq::180}
\frac{\partial \phi_e (x, t)}{\partial x} = -\frac{i_e (t)}{\kappa^{eff}} + \frac{\kappa_D^{eff}}{\kappa^{eff}} \frac{\partial \ln c_e (x, t)}{\partial x}
\end{equation}
\par Last, the terminal voltage is expressed as:
\begin{equation} \label{eq:1}
\begin{split}
V_{espm}(t) = U_p(c_{s,p},t) - U_n(c_{s,n},t) - (\eta_p(0,t) \\ - \eta_n(L,t) ) - (\phi_{e}(0,t) - \phi_{e}(L,t)) - I(t)R_c
 \end{split}
\end{equation}

\noindent where $U_i$ denotes the open-circuit potential, and $R_0$ the ohmic resistance. In this work, the PDEs governing the solid-phase and electrolyte concentrations are approximated using the Galerkin projection method, as described in \cite{8008775}.


