\vspace{-1.5em} 
\begin{equation} \label{eq:theta_split}
\begin{split}
\mathbf{\Theta}(\mathbf{e}, \mathbf{U}) = \Big[\, \mathbf{1},~ 
&\underbrace{T_1(\mathbf{e}),\, T_2(\mathbf{e}),\, \ldots,\, T_n(\mathbf{e})}_{\text{State Chebyshev polynomial terms}}, \\
&\underbrace{T_1(\mathbf{U}_1),\, \ldots,\, T_n(\mathbf{U}_1),\, \ldots,\, T_n(\mathbf{U}_m)}_{\text{Input Chebyshev polynomial terms}},\, \ldots, \\
&\underbrace{T_i(\mathbf{e}) T_j(\mathbf{U}_1),\ T_i(\mathbf{e}) T_j(\mathbf{U}_2) T_k(\mathbf{U}_3)}_{\text{Cross Chebyshev polynomial terms}}, \, \ldots,\, \\
& \underbrace{\phi(\mathbf{e}, \mathbf{U})}_{\text{Additional terms}} 
\,\Big]
\end{split}
\end{equation}
\noindent \vspace{-1.0em} 
\begin{equation} \label{eq:lib_set}
\mathbf{\Theta_s} = \left[ \begin{array}{c c c c c}
\vert & \vert &  & \vert & \vert \\
\mathbf{\Theta_{s,1}} & \mathbf{\Theta_{s,2}} & \cdots & \mathbf{\Theta_{s,m-1}} & \mathbf{\Theta_{s,m}} \\
\vert & \vert &  & \vert & \vert
\end{array} \right]
\end{equation}

In the library matrix, $T_n(\cdot)$ represents a Chebyshev polynomial function of the first kind of order $n$ (Eq. \ref{chebyshev_func}), $\mathbf{U_k}$ is the k$^{th}$ input variable from the set $\mathbf{U} = \{ I, c_{s,p}, c_{s,n}, c_{e,0}, c_{e,L}\}$, and product of Chebyshev polynomials from state/input variables is constrained by $i + j + k \leq d$, for the maximum polynomial degree $d$ defined by the selective process of library terms. The adoption of Chebyshev polynomials is motivated by their numerical stability and orthogonality, which enhance approximation performance and reduce multicollinearity among the basis functions \cite{mostajeran2025scaled}.  Additionally, $\phi(\mathbf{e}, \mathbf{U})$ represents possible additional nonlinear basis functions. In this formulation, trigonometric and hyperbolic functions are selected as potential terms for $\phi(\mathbf{e}, \mathbf{U})$ based on their ability to capture more complex nonlinear processes that govern the error dynamics \cite{AHMADZADEH2024110743,da2024improving}. 
\begin{equation} \label{chebyshev_func}
\begin{aligned}
T_1(x) &= x \\
T_2(x) &= 2x^2 - 1 \\
&\vdots \\
T_{n+1}(x) &= 2xT_n(x) - T_{n-1}(x)
\end{aligned}
\end{equation}

As shown in Eq. \ref{eq20}, all features are scaled to the range $[-1,1]$ to promote numerical stability,  uniform regularization, and improved model interpretability. 
\begin{equation} \label{eq20}
U' = 2 \cdot \frac{U - U_{\min}}{U_{\max} - U_{\min}} - 1,~~ e' = 2 \cdot \frac{e - e_{\min}}{e_{\max} - e_{\min}} - 1
\end{equation}

The identification of $\xi = (\xi_1, \xi_2,\dots,\xi_m)^T$ can be formulated as a regularized optimization problem solved by sequentially thresholded ridge (STRidge) regression \cite{rudy2019data}:
\begin{equation}  \label{eq:SINDyC}
\begin{split}
    \hat{\xi}^{\lambda_1,\lambda_2} = \arg \min_{\xi \in \mathbb{R}^{m}} \left\| \mathbf{{e}}[k+1] - \Theta(\mathbf{{e}}[k],\mathbf{U}[k])\xi \right\|_{2} + \lambda_{1} \left\| \xi \right\|_{2} 
\end{split}
\end{equation}

\noindent which is followed by a thresholding rule:
\begin{equation}  \label{eq:SINDyC1}
\begin{split}
\hat{\xi}_j^{(l+1)} = 
\begin{cases}
\hat{\xi}_j^{(l)}, & \text{if } |\hat{\xi}_j^{(l)}| \geq \lambda_2 \\
0, & \text{otherwise}
\end{cases}
\quad \forall ~ j = 1, \dots, m
\end{split}
\end{equation}
\noindent where $\lambda_1$ represents the L2-norm regularization parameter that provides uniform coefficient shrinkage, addressing multicollinearity and model overfitting issues. The elimination of unnecessary basis functions is controlled by the sparsification hyperparameter $\lambda_2$, whose range (defined as  [$10^{-2}$, $5$]) is based on the minimum value of $\lambda_2$ that will set the model coefficients to zero when the library matrix contains all possible combinations of basis functions. The regularization parameter $\lambda_1$ varies in the range [$10^{-13}$, $10^{-1}$]. Additionally, the individual polynomial function maximum order $p_{c,i}$ ranges from [1, 5], constrained by the maximum total polynomial degree $d$, which is set within the range [1, 5] and satisfies $p_{c,1} + p_{c,2} + \dots + p_{c,6} \leq d$.

