\section{Proof Checking and Evaluation}
\label{ch:evaluation}



% Although HOLALA is itself also a theorem prover, it is supposed to be only used to convert proof scripts to proof articles. Thus, it should not be conflicting with the role of HOL Light.


% HOLALA is adapted from HOL Light and is compatible with the  proof scripts of the standard library which consists of over a thousand proofs ranging from function operators and combinators to relation operators. New article files were generated from the standard library by HOLALA for comparison. Holide is a translator which takes HOL proof articles as input and outputs files in the Dedukti format. Following that, Dedukti takes the translated files and performs proof checking.

\subsection{Extending Holide and Dedukti}
 In this project we employ Dedukti as the proof checker to verify the proofs generated by HOLALA. Cousineau and Dowek showed that Higher Order Logic can be embedded in the $\lambda\Pi$-calculus Modulo as well as other Pure Type Systems (PTS) \cite{gilles1}. This laid the foundation of Dedukti \cite{dedukti}, a universal proof checker. On top of Dedukti, Holide\cite{holide} was developed to transform proofs from a proof repository, namely the OpenTheory Repository \cite{opentheory}, to Dedukti. Following the extension of the logic kernel of HOL Light, there are some necessary changes to the existing translation of HOL Light's logic into Dedukti to accommodate this larger kernel. To deal with this update, the declaration of the universal quantifier and the implication together with their elimination and introduction inference rules were added to Holide as well as the input to Dedukti. The quantified terms would be translated as follows, with the notation of translation follows from the notation of \cite{holide}: 

 \begin{itemize}
  \item[]  $|\rightarrow |=imp$
  \item[]  $|(\forall_{A})|=forall |A|$
 \item[] $|\forall (M:A)| = forall |A| |M| $
 \item[]  $|M\rightarrow N|=imp|M||N|$, where
%  \end{itemize}


% \begin{itemize}

  \item[] imp: $term\,bool\rightarrow term\,bool\,\rightarrow term\,bool$ 
  \item[] forall : $\Pi\alpha:type\rightarrow term(arr\,\alpha\,bool)\rightarrow term\,bool$

\end{itemize}


%  imp: $term\,bool\rightarrow term\,bool\,\rightarrow term\,bool$ 


%  forall : $\Pi\alpha:type\rightarrow term(arr\,\alpha\,bool)\rightarrow term\,bool$


%  $|\rightarrow |=imp$

%  $|(!_{A})|=forall |A|$ 


To translate the additional inference rules, four constants $\text{MP}$, $\text{DISCH}$, $\text{GEN}$ and $\text{SPEC}$ were introduced as below: 

\begin{itemize}
\item [] $\text{MP}$: $\Pi p:term\,\text{bool}.\Pi q:term\,\textit{bool.proof}(imp\,p\,q)\rightarrow \textit{proof}\,p\rightarrow \text{proof}\,q$
\item[] $\text{DISCH}$: $\Pi p:term\,\textit{bool}.\Pi q:term\,\textit{bool.proof}\,p\rightarrow proof\,q\rightarrow \textit{proof}(imp\,p\,q)$

\item[] $\textit{GEN}$: $\Pi\alpha:type.\Pi p':(term\,\alpha\rightarrow term\,bool).\Pi x:term\,\alpha.\textit{proof}\,(p'\,x)\rightarrow \textit{proof}(\textit{forall}\,\lambda\,x.p'x)$

\item[] $\textit{SPEC}$: $\Pi\alpha:type.\Pi t:(term\,\alpha\rightarrow term\,bool).\Pi u:term\,\alpha.\textit{proof}(\textit{forall}\,\alpha\,t)\rightarrow \textit{proof}(t\,u)$
\end{itemize}

% $MP$: $\Pi p:term\,bool.\Pi q:term\,bool.proof(imp\,p\,q)\rightarrow proof\,p\rightarrow proof\,q$



% $DISCH$: $\Pi p:term\,bool.\Pi q:term\,bool.proof\,p\rightarrow proof\,q\rightarrow proof(imp\,p\,q)$


% $GEN$: $\Pi\alpha:type.\Pi p':(term\,\alpha\rightarrow term\,bool).\Pi x:term\,\alpha.proof\,(p'\,x)\rightarrow proof(forall\,\lambda\,x.p'x)$



% $SPEC$: $\Pi\alpha:type.\Pi t:(term\,\alpha\rightarrow term\,bool).\Pi u:term\,\alpha.proof(forall\,\alpha\,t)\rightarrow proof(t\,u)$



 The translation of corresponding inference rules were added to Holide:

\begin{itemize}
\item [] \translate{\Omp} = ${\text{MP}|A||B||\mathcal{D}_{1}||\mathcal{D}_{2}|}$, where $\mathcal{D}_{1}$ and $\mathcal{D}_{2}$ are the proofs of $ A \rightarrow B$ and $A$ respectively.
% \item[]  \translate{\Omp} = ${MP|A||B||\mathcal{D}_{1}||\mathcal{D}_{2}|}$, where $\mathcal{D}_{2}$ and $\mathcal{D}_{2}$ are proofs of $ A \rightarrow B$ and $A$ respectively.

\item[] \translate{\Ogen} = ${\text{GEN}|A||c'||\mathcal{D}'|}$,
  where $\,c'=\lambda x:||A||.|c|$, $\mathcal{D}$ is a proof of $A[c/x]$ and $\mathcal{D}'=\lambda x:||A||.|\mathcal{D}|$

 \item[] \translate{\Odisch} = ${\text{DISCH}|A||B||\mathcal{D}'||\mathcal{D}|}$, where $\mathcal{D}'$ is a proof of $A$ and $\mathcal{D}$ is a proof of $B$ 
 \item[] \translate{\Ospec} = $\text{SPEC}\,|A|t'|u||\mathcal{D}|$, where $t'=\lambda x:||A||.|t|$ and $\mathcal{D}$ is a proof of $B$.
\end{itemize}


