\section{Preliminaries}\label{sec:method}

\subsection{Mesh and Discrete Curvature}
Let $\mathcal{M}=(V,E,F)$ be a closed triangular mesh with $n=|V|$ vertices, $m=|E|$ edges, and faces $F$.  

We assign each vertex $i\in V$ a real number $x_i$, called its \emph{log‐radius}, and collect all of them into the vector $x\in\mathbb{R}^n$.

From these radii, we compute edge lengths $e^{x_i+x_j}$ and then the corner angles $\theta_{ij}(x)$ at vertex $i$ in each face $[i,j,k]$.  

The \emph{discrete Gaussian curvature} (or angle deficit) at $i$ is
\[
  K_i(x)
  \;=\;
  2\pi
  \;-\;
  \sum_{[i,j,k]\in F}\theta_{ij}(x),
\]
so that a flat mesh has $K_i(x)=0$ for all $i$ \cite{Jin2008TVCG,Springborn2008SGP}.

\subsection{Cotangent Laplacian and Syndrome}
We build the standard \emph{cotangent-weight Laplacian} matrix $H\in\R^{n\times n}$ by
\[
  H_{ij} =
  \begin{cases}
    -\tfrac12\,\bigl(\cot\alpha_{ij} + \cot\beta_{ij}\bigr), & \text{if }[i,j]\in E,\\[6pt]
    -\sum_{k\neq i}H_{ik}, & \text{if }i=j,\\[6pt]
    0, & \text{otherwise},
  \end{cases}
\]
where $\alpha_{ij}$ and $\beta_{ij}$ are the two angles opposite the edge $[i,j]$ in its two adjacent faces \cite{Springborn2008SGP,Bobenko2004CGF}. We then define the \emph{syndrome} (or residual)
\[
  \bm{s} \;=\; H\,x,
\]
which in fact approximates the curvature vector $K(x)$ to first order.

\subsection{Discrete Ricci Energy and Flow}
The \emph{discrete Ricci energy} is
\[
  E(x)
  \;=\;
  \int_{0}^x \sum_{i=1}^n K_i(u)\,du_i,
\]
and its negative gradient flow is
\[
  \dot x
  \;=\;
  -\,\nabla E(x)
  \;=\;
  -\,\bm{s},
\]
which recovers the usual discrete Ricci flow dynamics \cite{Luo2004JDG,Springborn2008SGP}.


\begin{theorem}[Convexity and Uniqueness]\label{thm:convex}
On the hyperplane $\sum_i x_i = 0$, the energy $E(x)$ is strictly convex (in both Euclidean and hyperbolic settings).  Therefore, there is exactly one solution $\bar x$ with zero curvature, $K(\bar x)=0$, and the flow converges from any starting point to this unique $\bar x$.
\end{theorem}

\begin{proof}[Proof Sketch]
By differentiating under the integral, one sees $D^2E(x)=H$.  Standard spectral arguments for the cotangent Laplacian (using positivity of the cotangent weights and zero row–sum) show $H$ is positive–definite on $\sum_i x_i=0$; strict convexity and ODE theory then give uniqueness and global convergence.
\end{proof}

\subsection{Greedy Syndrome‐Decoding Solver}
Interpreting $H$ as a parity‐check matrix and $\s=Hx$ as its syndrome, we perform a simple \emph{greedy update}:
\[
  i^* \;=\;\arg\max_i|s_i|,
  \qquad
  x_{i^*} \;\leftarrow\; x_{i^*} - \varepsilon\,s_{i^*},
\]
which acts like flipping the single bit (vertex) with the largest violation \cite{Jin2008TVCG,Yin2008SGP}.

\begin{lemma}[Monotonicity]\label{lem:mono}
If $0 < \varepsilon \le 1 / \|H\|_\infty$, then each greedy step strictly lowers the maximum of $|\s|$:
\[
  \|\s_{\rm new}\|_\infty \;<\; \|\s\|_\infty.
\]
\end{lemma}

\begin{proof}[Proof Sketch]
Writing $\s_{\rm new} = \s - \varepsilon\,s_{i^*}\,H e_{i^*}$, Gershgorin’s theorem shows the largest entry decreases by at least $\varepsilon\,s_{i^*}^2>0$, while all other entries change by at most $\varepsilon\|H\|_\infty\,\|\s\|_\infty\le\|\s\|_\infty$, so the overall max‐norm drops.
\end{proof}

\begin{theorem}[Termination and Complexity]\label{thm:complex}
For a tolerance $\tau>0$, the greedy solver finishes in
\[
  O\!\bigl(\tfrac{\|x(0)\|_\infty}{\varepsilon\,\tau}\bigr)
\]
iterations.  Each iteration costs $O(m)$ to compute $H x$ and $O(1)$ to update one entry, so total work is $O(m/\tau)$.
\end{theorem}

\begin{proof}[Proof Sketch]
By Lemma~\ref{lem:mono}, each step cuts the max‐norm by at least $\varepsilon\,\tau$, starting from $\|\s(0)\|_\infty=O(\|H\|\|x(0)\|_\infty)$.  Hence at most $\|\s(0)\|_\infty/(\varepsilon\,\tau)$ steps are needed.  The cost per step is dominated by the sparse matrix–vector product.
\end{proof}

\subsection{Scope and Extensions}
Exactly the same arguments extend if you replace Euclidean by spherical or hyperbolic geometry, or swap in other discrete‐flow operators (e.g.\ mean‐curvature flow) by redefining $H$ and rechecking convexity \cite{Jin2008TVCG,Yin2008SGP}.



