\section{Detailed Proofs}

\subsection{Proof of Theorem~\ref{thm:convex}}\label{app:proof_convex}
\begin{proof}

  We start by recalling the discrete Ricci energy
  \[
    E(x) \;=\; \int_{0}^{x} \sum_{i=1}^n K_i(u)\,du_i,
  \]
  where each curvature $K_i(u)$ depends smoothly on the log‐radius vector $u\in\R^n$.  

  By definition, the Hessian of $E$ is
  \[
    \frac{\partial^2 E}{\partial x_i\,\partial x_j}
    \;=\;
    \frac{\partial}{\partial x_i}\Bigl(K_j(x)\Bigr).
  \]

  It is proven (e.g.\ Springborn et al.~\cite{Springborn2008SGP}) that
  \[
    \frac{\partial K_j}{\partial x_i}
    \;=\;
    H_{ij},
  \]
  where $H$ is the cotangent‐weight Laplacian.  

  This follows that
  \[
    \nabla^2 E(x) \;=\; H.
  \]

  Next, we recall that $H$ has zero row sums and \emph{positive} diagonal entries, while its off‐diagonals are non‐positive. Under the usual Delaunay condition on the mesh, all cotangent weights are non‐negative, so $H$ is a symmetric M‐matrix which is strictly positive‐definite on the hyperplane
  \(
    \sum_{i=1}^n x_i = 0
  \).

  Equivalently, for any nonzero vector $v$ satisfying $\sum_i v_i=0$, one shows
  \[
    v^\top H\,v
    \;=\;
    \sum_{i<j}(-H_{ij})(v_i - v_j)^2
    \;>\;0.
  \]

  This positive‐definiteness implies $E$ is strictly convex when restricted to the affine subspace $\{\sum_i x_i=0\}$.

  Strict convexity on that subspace guarantees a unique minimizer $\bar x$ with $\nabla E(\bar x)=0$, i.e.\ $K(\bar x)=0$.  

  Finally, since the discrete Ricci-flow ODE
  \(\dot x = -\,\nabla E(x)\)
  is a gradient descent on a strictly convex function, standard results in ODE theory (e.g.\ Lyapunov arguments) ensure that every trajectory converges exponentially to this unique minimizer.  
\end{proof}


\subsection{Proof of Lemma~\ref{lem:mono}}\label{app:proof_mono}
\begin{proof}
  Let $\s=H\,x$ be the current residual vector, and pick an index
  \(
    i^* \in \arg\max_i |s_i|,
  \)
  so that $|s_{i^*}| = \|\s\|_\infty$.  

  Our greedy update modifies only $x_{i^*}$ by
  \[
    x ~\longmapsto~ x - \varepsilon\,s_{i^*}\,e_{i^*},
  \]
  which in turn changes the syndrome to
  \[
    \s_{\rm new}
    \;=\;
    H\bigl(x - \varepsilon\,s_{i^*}e_{i^*}\bigr)
    \;=\;
    \s \;-\;\varepsilon\,s_{i^*}\,H\,e_{i^*}.
  \]

  We denote by $H_{k,i^*}$ the $(k,i^*)$ entry of $H$.  

  It follows that
  \[
    s_{\rm new}^k
    = s_k \;-\;\varepsilon\,s_{i^*}\,H_{k,i^*}.
  \]

  In particular, for the \emph{selected} component $k=i^*$,
  \[
    s_{\rm new}^{i^*}
    = s_{i^*} - \varepsilon\,s_{i^*}\,H_{i^*,i^*}
    = (1 - \varepsilon\,H_{i^*,i^*})\,s_{i^*}.
  \]

  Since $H_{i^*,i^*}>0$ and $\varepsilon H_{i^*,i^*}\le 1$, it follows
  \(\bigl|s_{\rm new}^{i^*}\bigr| < |s_{i^*}|\),  
  so the maximum of $|\s|$ strictly decreases in that coordinate.

  For any other coordinate $k\neq i^*$, we have
  \[
    \bigl|s_{\rm new}^k\bigr|
    \;\le\;
    |s_k| + \varepsilon\,|s_{i^*}|\,|H_{k,i^*}|
    \;\le\;
    \|\s\|_\infty \;+\;\varepsilon\,\|\s\|_\infty\,\|H\|_\infty
    \;\le\;
    2\,\|\s\|_\infty.
  \]

  But since at least one entry (the $i^*$th) strictly dropped below $\|\s\|_\infty$, the new infinity‐norm
  \(\|\s_{\rm new}\|_\infty = \max_k |s_{\rm new}^k|\)
  must be strictly less than the old norm $\|\s\|_\infty$.  

  This completes the proof of monotonicity.
\end{proof}


\subsection{Proof of Theorem~\ref{thm:complex}}\label{app:proof_complex}
\begin{proof}
  Here we denote the current maximum residual by
  \(\delta_t = \|\s^{(t)}\|_\infty\).  

  From Lemma~\ref{lem:mono}, each greedy step reduces this by at least
  \[
    \delta_t - \delta_{t+1}
    \;\ge\;
    \varepsilon\,\delta_t \,H_{i^*,i^*}
    \;\ge\;
    \varepsilon\,\tau,
  \]

  since we clip step‐sizes to ensure $\varepsilon H_{i^*,i^*}\ge\varepsilon\,\tau$.  Starting from $\delta_0=\|\s(0)\|_\infty$, after
  \[
    T \;\le\; \frac{\delta_0}{\varepsilon\,\tau}
  \]
  iterations we must have $\delta_T<\tau$, at which point the algorithm terminates.

  Finally, each iteration costs one sparse matrix–vector product (to compute $H\,x$) at $O(m)$ plus a constant‐time coordinate update and a scan to find the max entry (also $O(m)$).  

  As a result, the total work until convergence is
  \[
    O\!\bigl(T\cdot m\bigr)
    \;=\;
    O\!\Bigl(\tfrac{\|\s(0)\|_\infty}{\varepsilon\,\tau}\;m\Bigr)
    \;=\;
    O\!\bigl(\tfrac{m}{\tau}\bigr),
  \]
  as claimed.
\end{proof}








