\subsection{Phase Misalignment Analysis of OFDM PASS}
To characterize the detrimental effect of this phase misalignment introduced by the single-carrier approximation, we analyze the magnitude of the phase variation itself. We aim to find the phase of the signal component arriving at the user via PA $n$, relative to the phase of $E_{\rm{in},1}(f_p)$ at the input of the waveguide. The complex amplitude $E_{n,p}$ of the signal component at the user can be expressed as
\begin{equation}
\begin{split}\label{G}
 E_{n,p} = & E_{\rm{in},1}(f_p) \times T(f_p) \times \left( \prod_{i=1}^{n-1} \alpha'_{{\rm{WG}},i}(f_p) \right) \\
 & \times \alpha'_{{\rm{PA}},n}(f_p) \times h_{n,p} \times h_{\rm{ant}},
 \end{split}
\end{equation}
where $h_{\rm{ant}}$ represents other constant phase shifts or gains from transmit and receive antennas. The total phase of $E_{n,p}$ relative to $E_{\rm{in},1}(f_p)$ is given by
\begin{equation}
\begin{split}\label{G}
&\arg(E_{n,p}/E_{\rm{in},1}(f_p)) \\
 &= -\beta_{\rm{g}}(f_p)\tilde{x}_n + \phi_{{\rm{accum}},n-1,p} + \phi_{{\rm{coup}},n,p} - \phi_{n,p} + \phi_{\rm{const}},
\end{split}
\end{equation}
where $\phi_{{\rm{accum}},n-1,p} = \sum_{i=1}^{n-1} \arg(\alpha'_{{\rm{WG}},i}(f_p))$, $\phi_{{\rm{coup}},n,p} = \arg(\alpha'_{{\rm{PA}},n}(f_p)) = \frac{\Delta\beta_n(f_p) L_n}{2} - \frac{\pi}{2}$ $\pm \pi$, $\phi_{n,p} = \arg(h_{n,p}) =\frac{2\pi f_p}{c}d_{u,n}$ and $\phi_{\rm{const}}=\arg(h_{\rm{ant}})$ denote the phase contribution of corresponding channel components, respectively.

{Defining} the total accumulated phase delay $\Phi_{n,p}(\tilde{\mathbf{x}})$ such that $E_{n,p} \propto e^{-j \Phi_{n,p}(\tilde{x}_n)}$, we have
\begin{equation}
\begin{split}\label{phase}
\Phi_{n,p}(\tilde{\mathbf{x}})
= &\beta_{\rm{g}}(f_p)\tilde{x}_n - \sum_{i=1}^{n-1} \arg\left(\alpha'_{{\rm{WG}},i}(f_p)\right) \\
&- \left(\frac{\Delta\beta_n(f_p) L_n}{2} - \frac{\pi}{2}\right)
+ \frac{2\pi f_p}{c} d_{u,n}(\tilde{x}_n) - \phi_{\rm{const}}.
\end{split}
\end{equation}
%
%The expression used in the proof outline was:
%$\Phi_{n,p}(\mathbf{x})_{Lemma3} = \beta(f_p)\tilde{x}_n + \frac{2\pi f_p}{c} d_{u,n}(\mathbf{x}) + \phi_{coup,n,p}$
%Comparing this to the rigorously derived phase delay (Eq. D.8, ignoring $\phi_{const}$ and the sign difference which cancels in $\Delta\Phi$), we see that the Lemma 3 expression **correctly included** the dominant terms related to propagation delays (waveguide $\beta \tilde{x}_n$ and free-space $\phi_{fs}$), and the local coupling phase $\phi_{coup}$. However, it **omitted the accumulated phase term** $-\sum_{i=1}^{n-1} \arg(\alpha'_{{\rm{WG}},i}(f_p))$.
%
%As discussed previously, this omission simplifies the analysis of the phase difference variation $\Delta\Phi_{n,p} - \Delta\Phi_{n,0}$, likely under the assumption that the derivative of $\arg(R_{n-1}(f_p))$ contributes less significantly to the linear term than the derivatives of $\beta(f_p)\Delta$ and $\phi_{fs,n,p} - \phi_{fs,n-1,p}$. Eq. (D.8) provides the complete expression for the total accumulated phase delay.
%
%Let $\Phi_{n,p}(\mathbf{x}) = \beta(f_p)\tilde{x}_n + \frac{2\pi f_p}{c} d_{u,n}(\mathbf{x}) + \phi_{coup,n,p}$ be the relevant phase of the signal arriving at the user from PA $n$ for subcarrier $p$ (neglecting constant phase terms and assuming coupling phase $\phi_{coup,n,p}$ varies slowly with $f_p$ around $f_0$). Let $\Delta\Phi_{n,p}(\mathbf{x}) = \Phi_{n,p}(\mathbf{x}) - \Phi_{n-1,p}(\mathbf{x})$ be the phase difference between adjacent PAs.

\textbf{Lemma 1:} Given $|f_p - f_c| \ll f_c$ in mmWave OFDM PASS, the phase difference between adjacent PAs $\Delta\Phi_{n,p}(\tilde{\mathbf{x}}) = \Phi_{n,p}(\tilde{\mathbf{x}}) - \Phi_{n-1,p}(\tilde{\mathbf{x}})$ can be approximated by
\begin{equation}
\begin{split}\label{phase_error}
\Delta\Phi_{n,p}(\tilde{\mathbf{x}}) \approx \left[ \frac{2\pi \Delta}{v_{\rm{g}}(f_c)} + \frac{2\pi}{c} \Delta_{d,n} \right] (f_p - f_c) +\Delta\Phi_{n,c}(\tilde{\mathbf{x}}),
\end{split}
\end{equation}
where $\Delta_{d,n}={d}_{u,n}-{d}_{u, n-1} $ and $\Delta\Phi_{n,c}$ denotes inter-PA phase differences at the center frequency $f_c$.

\emph{Proof:}
Considering that the derivative of $\arg({\alpha'_{{\rm{WG}},n}}(f_p) )$ contributes less significantly to the linear term than the derivatives of $\beta_{\rm{g}}(f_p)\Delta$ and $\phi_{n,p} - \phi_{n-1,p}$, the accumulated phase term $-\sum_{i=1}^{n-1} \arg(\alpha'_{{\rm{WG}},i}(f_p))$ is omitted. Furthermore, neglecting constant phase terms $\phi_{\rm{const}}$ and the sign difference which cancels in $\Delta\Phi$, the total phase difference experienced by the signal is
$\Delta\Phi_{n,p}(\tilde{\mathbf{x}}) = [\beta_{\rm{g}}(f_p)\tilde{x}_n + \frac{2\pi f_p}{c} {d}_{u,n}] - [\beta_{\rm{g}}(f_p)\tilde{x}_{n-1} + \frac{2\pi f_p}{c} {d}_{u,n-1}] + (\phi_{{\rm{coup}},n,p} - \phi_{{\rm{coup}},n-1,p})= \beta_{\rm{g}}(f_p)(\tilde{x}_n-\tilde{x}_{n-1}) + \frac{2\pi f_p}{c} \Delta_{d,n} + \Delta\phi_{{\rm{coup}}, n, p}$.
Using the first-order Taylor expansion around $f_c (|f_p - f_c| \ll f_c)$:
$\beta_{\rm{g}}(f_p) \approx \beta_{\rm{g}}(f_c) + \beta'_{\rm{g}}(f_c)(f_p - f_c)$
and $\frac{2\pi f_p}{c} {d}_{u,n} \approx \frac{2\pi f_c}{c} {d}_{u,n} + \frac{2\pi {d}_{u,n}}{c}(f_p - f_c)$.
Assuming the differential coupling phase $\Delta\phi_{{\rm{coup}}, n, p} \approx \Delta\phi_{{\rm{coup}}, n, c}$ varies slowly near $f_c$.
Substituting these into the expression for $\Delta\Phi_{n,p}(\tilde{\mathbf{x}})$ and using $\tilde{x}_n-\tilde{x}_{n-1} = \Delta$, we have
\begin{equation}
\begin{split}
 \Delta\Phi_{n,p}(\tilde{\mathbf{x}}) \approx & [\beta_{\rm{g}}(f_c) + \beta'_{\rm{g}}(f_c)(f_p - f_c)]\Delta \\
 &+ \left[\frac{2\pi f_c}{c} \Delta_{d,n}+ \frac{2\pi}{c}\Delta_{d,n}(f_p - f_c)\right] + \Delta\phi_{\text{coup}, n, c}.
\end{split}
\end{equation}
Grouping terms evaluated at $f_c$ gives $\Delta\Phi_{n,c}(\tilde{\mathbf{x}})$, we have
\begin{equation}
\begin{split}
\Delta\Phi_{n,c}(\tilde{\mathbf{x}}) \approx \beta_{\rm{g}}(f_c)\Delta + \frac{2\pi f_c}{c}\Delta_{d,n}+ \Delta\phi_{{\rm{coup}}, n, c}.
\end{split}
\end{equation}
Subtracting this from the expression for $\Delta\Phi_{n,p}(\tilde{\mathbf{x}})$ leaves the terms proportional to $(f_p - f_c)$:
\begin{equation}
\begin{split}
\Delta\Phi_{n,p}(\tilde{\mathbf{x}}) - \Delta\Phi_{n,c}(\tilde{\mathbf{x}}) \approx \left[\beta'_{\rm{g}}(f_c)\Delta + \frac{2\pi}{c}\Delta_{d,n}\right] (f_p - f_c).
\end{split}
\end{equation}
Substituting $\beta'_{\rm{g}}(f_c) = \frac{d\beta_{\rm{g}}}{df}|_{f_c} = \frac{2\pi}{v_{\rm{g}}(f_c)}$, we arrive at \eqref{phase_error}. 
This completes the proof. $\blacksquare$

{\textbf{Lemma 1}} reveals the linear dependence of the phase difference deviation on the frequency offset $(f_p - f_c)$, with the slope determined by the group delay over the PA spacing $\Delta$ and the free-space path difference delay. The approximation $\tilde{x}_n$ works well only when the total phase variation $\Delta\Phi_{n,p} \times B \ll 2\pi$ and the relative bandwidth $B/f_c$ is small. These conditions correspond to narrowband systems, low dispersion ($f_c \gg f_0$), and small array apertures $(N-1)\Delta$.

