    \Function{\InsertKeywordsFunctionName{}}{$\Title$, $\AbstractAdv$, $\ArchiveAdv{}$}
    \State $\AbstractAdvVersion{0} \gets \AbstractAdv$
    \For{$i=1,\ldots,\Alternations$}
        \If{Early stopping is used \textbf{and} \EarlyStoppingCheck{$\AbstractAdvVersion{i-1}$}{$\ArchiveAdv{}$}} 
