\subsubsection{\FindKeywords{} Subroutine}
We propose the \FindKeywords{} subroutine, which is a greedy search to find \textit{keywords} that when inserted into $\AbstractAdv$ raise the similarity to the $\ArchiveAdv{}$. In order to make this search efficient, we narrow down keywords by using a heuristic that measures the increase in similarity upon appending the word to the current $\AbstractAdv$. Algorithm \ref{alg:keywords} details the precise algorithm. This is just one simple instantiation of a possible attack strategy that uses the openly available SPECTER weights---more sophisticated attacks are possible, but we find that our simple heuristics are already extremely successful at breaking current systems. 
\begin{algorithm}[h]
    \caption{\FindKeywords{} subroutine}\label{alg:keywords}
    \hspace*{\algorithmicindent} \textbf{Input:} \parbox[t]{.85\linewidth}{Paper title $\Title$, adversarial abstract from \IncludeRelatedWork{} $\AbstractAdv$, adversarial archive $\ArchiveAdv{}$, $\Keywords$ (number of keywords to return), and optionally \Call{Filter}{$\cdot$} (a function to filter out undesirable keywords)}\\
    \hspace*{\algorithmicindent} \textbf{Output:} \parbox[t]{.85\linewidth}{Up to $\Keywords$ keywords greedily selected to maximize the SPECTER similarity to $\AbstractAdv$ when the keywords are inserted into the abstract.}
    \vspace{0.1cm}
    \begin{algorithmic}[1]
    \Function{\FindKeywords{}}{$\Title, \AbstractAdv, \ArchiveAdv{}, \Keywords$}
    \State $\ArchiveWords \gets$ All words in titles and abstracts from $\ArchiveAdv{\Reviewer}$.
    \State $\ArchiveWords \gets$ \Call{Filter}{$\ArchiveWords$} \Comment{Optionally filter out certain \addforconference{

    }words, e.g. numbers}
    \State \textit{keywords} $\gets$ {\tt []} \Comment{Keeps track of the keywords}
    \State \textit{keywordsSimilarity} $\gets$ $\SimilarityAbstract{\Title}{\AbstractAdv}{\ArchiveAdv{}}$ \Comment{Keeps track \addforconference{ 

    }of estimated similarity to $\Reviewer$}
    \For{$i=0,\ldots,\Keywords-1$} \Comment{Iteratively select up to $\Keywords$ \addforconference{

    }keywords}
        \For{each word $w_j$ in $\ArchiveWords$} \Comment{Simulate real\addforconference{ 

       } modified abstracts with different $w_j$ added}
            \vspace{1mm}
            \State \parbox[t]{.80\linewidth}{$\AbstractAdvVersion{j} \gets$ adversarial abstract with words appended at the end ``\{$\AbstractAdv{}$\} \{$\ithMaxSimWord{0}$\} ... \{$\ithMaxSimWord{i-1}$\} \{$w_j$\}''.}
            \vspace{1mm}
        \EndFor
        \vspace{0.1cm}
        \State Let $\ithMaxSimWord{i}$ be a word $w_j$ such that the associated \addforconference{

        }$\SimilarityAbstract{\Title}{\AbstractAdvVersion{j}}{\ArchiveAdv{}}$ is the highest in $\ArchiveWords$.

        \If{$\underset{j}{\max} \ \SimilarityAbstract{\Title}{\AbstractAdvVersion{j}}{\ArchiveAdv{}} <$ \textit{keywordsSimilarity}} 
        \Comment{Stop if similarity does not increase}
            \State \textbf{break}
        \EndIf
        \State \textit{keywords}.append($\ithMaxSimWord{i}$)  \Comment{Add $\ithMaxSimWord{i}$ as a new\addforconference{ 

       } keyword} %put append here
        \State \textit{keywordsSimilarity} $\gets \underset{j}{\max} \ \SimilarityAbstract{\Title}{\AbstractAdvVersion{j}}{\ArchiveAdv{}}$  \Comment{Update estimated similarity with $\ithMaxSimWord{i}$ added}
    \EndFor
    \State \textbf{return} \textit{keywords}
    \EndFunction
    \end{algorithmic}
