We define the signature $\sigma_2=(<,E)$. 
We note that for every semi-plane tree $\Lambda$ represented as a $\sigma_1$-structure, the expanded $\sigma$-structure $\interp{I}_{\sigma_1\rightarrow\sigma}(\Lambda)$ can be recovered from its $\sigma_2$-reduct 
$\interp{R}_{\sigma\rightarrow\sigma_2}\interp{I}_{\sigma_1\rightarrow\sigma}(\Lambda)$ by an interpretation, which we denote by $\interp{I}_{\sigma_2\rightarrow\sigma}$.
Hence, the representations of semi-plane trees as $\sigma$-structures, $\sigma_1$-structures, and $\sigma_2$-structures are interpretation-equivalent.

This equivalence will be convenient as it will allow us to use all the power of $\sigma$-structures for semi-plane trees defined either as $\sigma_1$-structures or as $\sigma_2$-structures.











\section{Transduction toolbox}\label{sec:transductions}
\begin{fact}
	Let $\sigma,\widehat\sigma$ be relation signatures and let $D\notin\sigma$ be a unary predicate.

	For every interpretation $\mathsf I$ of $\widehat\sigma$-structures in $\sigma$-structures, there exists an interpretation $\widehat{\mathsf I}$ of $\widehat\sigma$-structures in $\sigma\cup\{D\}$-structures, called  $D$-relativization of\/ $\mathsf I$, such that
	$\widehat{\mathsf I}(\mathbf M)=\mathsf I(\mathbf M[D(\mathbf M)])$.
\end{fact}

Note that if $\mathsf T=\mathsf I\circ\Gamma\circ\mathsf C$ (where $\mathsf C$ is a copy operation, $\Gamma$ is a monadic lift introducing unary predicates distinct from $D$, and $\mathsf I$ is an interpretation), then 
$\widehat{\mathsf T}:=\widehat{\mathsf I}\circ\Gamma\circ\mathsf C$ is such that $\widehat{\mathsf T}(\mathbf M)=\mathsf T(\mathbf M[D(\mathbf M)])$.


\begin{lemma}[Transduction gluing lemma]\label{lem:glu}
Let $q$ be a positive integer, $\interp{T}_{i}$ be transductions of graphs indexed by
$i\in [q]$.

Then there exists a transduction $\interp{T}$ such that for every graph $G=(V,E)$ and structures $H_{i}\in \interp{T}_{i}(G)$,
$\interp{T}(G)$ contains all structures obtained from the disjoint union $V\cup \bigcup_iH_{i}$ where vertices in $V$ are only linked to some of their clones in the graphs $H_i$.
\end{lemma}
\begin{proof}
Each transduction $\mathsf T_i$ is the composition of a copy operation $\mathsf C_{k_i}$, a monadic lift $\Gamma_{i}$, and an interpretation $\mathsf I_{i}$. Note that we can assume (by renaming them if necessary) that the unary predicates introduced by the $\Gamma_i$ are distinct.
We consider a copy operation $\mathsf C_k$ with $k=1+\sum_{i}k_{i}$.
We mark the first clone by $V$, and $k_i$ of its twins by $D_i$, such that these marks are disjoint. 
Let $\widehat{\mathsf I}_i$ be the $D_i$-relativization of $\mathsf I$. Let $\interp S$ turn the clique between all clones of a vertex $v$ into 
$q$ disjoint cliques (according to the marks $D_1,\dots,D_q$), the copy in $V$ linked to some of its twins (those marked by a special mark $K$), and remove any relation between vertices in $V$. We let
$
\interp{T} := \widehat{\interp{I}}_1 \circ \ldots \circ \widehat{\interp{I}}_q \circ \interp{S}\circ \interp{\Gamma}_1\circ \ldots \circ \interp{\Gamma}_q \circ \interp{C}_k$  (See~\Cref{fig:gluing}). 
\end{proof}
\begin{figure}[ht]
    \centering
    \includegraphics[width=\textwidth]{gluing}
    \caption{Gluing transductions: for a graph $G$, we first create all the copies of the vertex set need for the $q$ transductions, plus one. (The green rectangles corresponds to cliques of twins.) The clones are partitioned into $q+1$ parts by $D_1,\dots,D_q$, and $V$. The edges between the parts are deleted, except, for each vertex $v$, an edge from $v$ of its $V$-copy to its twins marked $K$. Then, the transduction $T_i$ is applied to the part $D_i$.} 
    \label{fig:gluing}
\end{figure}

By precomposing the transductions $\mathsf T_i$ with the restriction transduction, we get

\begin{corollary}
	Let $q$ be a positive integer, $\interp{T}_{i}$ be transductions of graphs indexed by
	$i\in [q]$.

	Then there exists a transduction $\interp{T}$ such that for every graph $G=(V,E)$ and structures $H_{i}\in \interp{T}_{i}(G[V_i])$ with $V_i\subseteq V$,
	$\interp{T}(G)$ contains all structures obtained from the disjoint union $V\cup \bigcup_iH_{i}$ where vertices in $V$ are only linked to some of their clones in the graphs $H_i$.
\end{corollary}

The next lemma is used for another type of gluing, typically used in a recursive construction of a tree model
where the number of children of a node may be unbounded, thus making the previous lemma unusable, but the domains of the graphs modeled by each subtree are themselves definable.

\begin{lemma}\label{eq_trans}
	Let $\sim$ be a definable binary relation, which defines an equivalence relation on the domain of each structure in a class $\mathscr C$, let $R$ be a definable binary relation, and let $\mathsf T$ be a transduction expanding
	$\mathscr C$ by a binary relation $L$.

	Then, there exists a
	transduction $\interp{S}$ such that for every non-empty structure $G\in\mathscr C$ with \mbox{$\sim$-equivalence} classes  $V_1, \ldots, V_k$ inducing substructures $G_i=G[V_i]$, $\interp{S}(G)$ contains a structure $H$ as follows: 

	  For all $H_1, \ldots, H_k$ where $H_i \in \interp{T}(G_i)$ and $a_i \in
    V(H_i)$, $H$ is formed by the disjoint
    union of $H_1, \ldots, H_k$, a new
    element $r$ with $L(a,r)$ if and only if $a = a_i$ for some $i \in [k]$ and
    $R(a_i,a_j)$ if and only if $R(v_i,v_j)$ for some $v_i \in V(G_i), v_j\in V(G_j)$.


\end{lemma}
\begin{figure}[ht]
    \centering
    \includegraphics[width=\textwidth]{TrS}
    \caption{The transduction $\sf S$.} 
    \label{fig:TrS}
\end{figure}
\begin{proof}
We assume that $\sim$ is already in the structure, otherwise if it is defined by a
formula $\varphi$, we can precompose by an expansion operation $\interp{Rel}^{\varphi
\to \sim}$.

We start with an expansion $\interp{E}$ by a binary relation $R'$ not used in $\interp{T}$, such that
$R'(a,b) \leftrightarrow \exists u, v . (u\sim a)\land (v\sim b)\land R(u,v)$.
We then do an interpretation $\interp{B}$ breaking any relation between elements of different
equivalence classes. That is, its output has the same signature and each relation
$U$ is now defined by $\rho_U(\bar x):=U(\bar x)\wedge\bigwedge_{i\in[|\bar x|]}(x_1\sim x_i)$

It is enough to consider the case where $\interp{T}$ is an atomic operation. We now
consider cases depending on what atomic operation $\interp{T}$ is.
\begin{itemize}
	\item If $\interp{T}$ is a reduct, restriction or copy operation, or a monadic
		lift, we set $\interp{P} = \interp{T}$.
	\item If $\interp{T}$ is an extension operation parameterized by a formula
		$\varphi(x_1, \ldots, x_l)$, let $\psi$ be the formula obtained from $\varphi$
		where every quantification is relativized to stay within the equivalence class
		of $x_1$\footnote{replacing $\exists y\ \varphi(\bar x,y)$ (resp. $\forall y\ \varphi(\bar x,y)$) by $\exists y.(y\sim
		x_1)\wedge\varphi(\bar x,y)$ (resp. $\forall y.(y\sim x_1)\rightarrow\varphi(\bar x,y)$)}. Then we set $\interp P$ to be the extension operation
		parameterized by the formula $\varphi(x_1, \ldots, x_l)\wedge
		\bigwedge_{i\in [l]}(x_i\sim x_1)$.
\end{itemize}

After $\interp{P}$, the representatives of each equivalence class can be marked in a monadic expansion by a mark $K$. $R$ is redefined as the restriction of $R'$ to $K$. It is then easy to see that if the number of classes is nonzero, a transduction $\interp{F}$ can as well construct a star with a new vertex related by $L$ to each element marked by $K$.
In the end, $\interp{S} := \interp{F}\circ \interp{P} \circ \interp{B}\circ \interp{E}$.

\end{proof}



\section{Shallow ordered bicographs}\label{sec:sob}
A \emph{model} of \emph{complexity} $(N,h)$ is a triple $\mathfrak M=(\mathbf
T,\gamma,\kappa)$, where $\mathbf T$  is a semi-plane tree with depth at most $h$, $\gamma:L\rightarrow [N]$ is a coloring of the set $L$ of the leaves of $\mathbf T$, and
$\kappa: A(\mathbf T)\cup C(\mathbf T)\mapsto \{0,1\}^{[N]\times[N]}$ is a mapping such that
$\kappa(v)$ (written $\kappa_v$ in the following) is a symmetric function if $v\in A(\mathbf T)$.
(The mappings $\gamma$ and $\kappa$ are actually encoded using unary predicates, so that $\mathfrak M$ is a binary relational structure).
We define the interpretation $\build$ introducing an edge relation $E$ defined by the following formula
\begin{align*}
\rho_E(u,v)&:=(A(u\curlywedge v)\lor C(u\curlywedge v)\land (u<v))\land(\kappa_{u\curlywedge v}(\gamma(u),\gamma(v))=1)\\
&=\neg(u\geqslant v)\land (\kappa_{u\curlywedge v}(\gamma(u),\gamma(v))=1).
\end{align*}

Intuitively, the adjacency between a pair of vertices is stored at their least common ancestor in the tree,
and takes into account their order with respect to $<$ only if this ancestor is a node of type $C$.

This way,
a model $\mathfrak M$ defines a graph $G= \build(\mathfrak M)$.

For a model $\mathfrak M = (\mathbf T, \gamma, \kappa)$ and a node $u \in \mathbf T$, we
write $\mathfrak M{\upharpoonright}u$ for the submodel of $\mathfrak M$ induced by the subtree $\mathbf T[u]$ of $\mathbf T$ rooted at $u$ (and the derived restrictions of $\gamma$ and $\kappa$).
Note that the class of graphs having models of complexity $(N,h)$ is hereditary, for if
$G\subseteq_i H$ and $H$ has a model $\mathfrak M$, then the submodel of $\mathfrak M$ induced by all ancestors of
vertices in $G$ is a model of $G$.

In the case where $C(\mathbf{T})$ is empty, we retrieve the notion of connection model for classes of bounded shrubdepth (\cite{Ganian2012}). A class of graphs $\mathscr C$ has bounded shrubdepth
if and only if there exists integers $N$ and $h$ and class of connection models $\mathscr M$ each of complexity $(N,h)$ such that $\mathscr C \subseteq \interp{Build}_N(\mathscr M)$.

Otherwise, this corresponds to the notion of \emph{embedded shrubdepth} present in \cite{SODA_msrw}: a class of graphs $\mathscr C$ has bounded embedded shrubdepth
if and only if there exists integers $N$ and $h$ and class of models $\mathscr M$ each of complexity $(N,h)$ such that $\mathscr C \subseteq \interp{Build}_N(\mathscr M)$.




We now define a particular class of bipartite graphs having simpler models,
\emph{shallow ordered bicographs}, abbreviated \emph{sob}. A model of a sob, called an
\emph{ordered bicotree} (we will omit the adjective ordered in the following), has
bounded height, uses only two colors 1 and 2 and has three types of nodes :
\begin{itemize}
    \item U (Union) : $\kappa_u(i,j)=0$ for all $i,j$;

    \item B (Bi-join) : $\kappa_u(i,j) = 1$ if $i\neq j$ (and 0 otherwise);

    \item O (Ordered-join) : $\kappa_u(i,j) = 1$ if $i<j$ (and 0 otherwise).
\end{itemize}

These models appear in the literature using the name $K+S$ decomposition when the
height is not bounded \cite{fouquet1999bipartite}.

\begin{lemma}\label{osd_dec}
    If a class of graphs $\mathscr C$ has models of complexity $(N,h)$, then there is an integer $q$ such that for every $G \in \mathscr C$ there exists a partition $V_1, \ldots, V_q$ of $V(G)$ such that 
    \begin{itemize}
        \item the graphs $G[V_i]$ are cographs with cotrees of height at most $h$;
        \item the graphs $G[V_i,V_j]$ are sobs with bicotrees of height at most $h$.
    \end{itemize}
\end{lemma}

\begin{proof}
	Let $G\in \mathscr C$ with a model $\mathfrak M$ of complexity $(N,h)$.
	Take $q=N$ and $V_i$ to be the set of vertices colored $i$ in $\mathfrak M$. As noted
	earlier, the ancestors of $V_i$ in $\mathfrak M$ induce a model of $G[V_i]$. Since
	this model uses only one color, it is a cograph. Similarly, the ancestors of the
	bipartite graph $G[V_i,V_j]$ in $\mathfrak M$ induce a model of $G[V_i,V_j]$. The model
	uses only two colors, that we may relabel 1 and 2. Since the
	graph is bipartite, for every node $u$ of the model and color $x$,
	$\kappa_u(x,x)=0$. The only nodes that are not readily of one of the three authorised
	types are those $u$ such that $\kappa_u(2,1) = 1$ and $\kappa_u(1,2)=0$. For those,
	we can simply consider the model obtained by reversing the order $\lin$ on children
	of $u$ and making $u$ a node of type O, which models the same graph. Hence repeating
	this operation for every problematic node, we obtain a bicotree.

	Both the cotree and bicotree are obtained by removing nodes from the tree of $\mathfrak
	M$, hence their heights are at most $h$.
\end{proof}

We say that a bicotree $\mathfrak T$ is \emph{clean} if it satisfies the following conditions:

\begin{enumerate}
    \item For every U-node $u$ with children $v_1, \ldots, v_n$, the subtrees $\mathfrak T{\upharpoonright}v_i$ model the connected components of $\mathfrak{T}{\upharpoonright}u$;
    \item For every B-node $u$ with children $v_1, \ldots, v_n$, the subtrees $\mathfrak
    	T{\upharpoonright}v_i$ model the bipartite complement of the connected
		components of $\overline{\mathfrak{T}{\upharpoonright}u}^{\mbox{\tiny bip}}$;

    \item For every O node $u$ with children $v_1, \ldots, v_n$, the subtrees $\mathfrak T{\upharpoonright}v_i$ contain both leaves of color 1 and of color 2.
\end{enumerate}

\begin{lemma}
    Every sob with bicotree of height $h$ has a clean bicotree of height at most $3h$. 
\end{lemma}

\begin{proof}
	Let $\mathfrak T$ be a bicotree of height $h$.

	If the root $u$ is a node of type U, assume
	that some child $v_i$ of $u$ is the root of a model of a disconnected graph $G = G_1
	\uplus G_2 \uplus \ldots \uplus G_k$. Let $\mathfrak T_1, \ldots, \mathfrak T_k$ be the
	models induced by the ancestors of $V(G_1), \ldots, V(G_k)$ in $\mathfrak
	T{\upharpoonright}v_i$. The bicotree obtained by removing $\mathfrak
	T{\upharpoonright}v_i$ and adding $\mathfrak T_1, \ldots, \mathfrak T_k$ as children of $u$
	models the same graph and is no shallower than $\mathfrak T$. Repeating this for every
	problematic $v_i$, we can make $u$ comply with the first condition.

	If the root is a node of type B, the same reasoning applied to the bipartite complement of the
	graph shows how to make it comply with the second condition.

	If the root $u$ is of type O, assume that some of its children $v_1, \ldots, v_n$ are
	the roots of monochromatic subtrees (considering leaves colors), and that $u$ cannot
	be turned into a B-node or a U-node (this would be the case if all bicolor pairs of
	leaves are in the same order below $u$). The construction is illustrated in
	\Cref{figsob}. For every $i>1$, if 
	the subtree rooted in $v_i$ is monochromatic of color 1, we can model the same graph
	by substituting $v_{i-1}$ by a U-node with children $v_{i-1}$ and $v_i$. If
	$v_{i-1}$ was already a U-node, we can simply make $v_i$ one of the children of
	$v_{i-1}$. Similarly, if $i<n$ and $v_i$ is the root of a monochromatic subtree of
	color 2, we can make a U-node with children $v_i$ and $v_{i+1}$, or make $v_i$ one
	of the children of $v_{i+1}$ if $v_{i+1}$ is already a U-node. After repeating this
	operation, only the subtree rooted in $v_1$ may remain monochromatic of color 1, and
	the one rooted in $v_n$ monochromatic of color 2. If it is the case, we can add a B
	node between $u$ and its parent, and make $v_1$ and $v_n$ also children of this B
	node. In the end, $u$ complies with the third condition, and all U- or B-nodes added
	in the process also respect the first or second condition.

	By induction, we can turn $\mathfrak T$ into a clean bicotree by adding at most 2 more
	levels by O type node, hence the obtained bicotree as height at most $3h$.
\end{proof}

\begin{figure}
	\centering
	\caption{Turning a bicotree into a clean bicotree at an O type node.}
	\includegraphics[width=.35\textwidth]{clean_sob}
	\label{figsob}
\end{figure}
\pagebreak
\begin{lemma}[\cite{fouquet1999bipartite}]\label{sob_p7}
    Let $G$ be a sob, then $G$ does not contain an induced $P_7$.
\end{lemma}

\begin{lemma}\label{sob_transeq}
	Let $\mathscr C$ be a class of sobs, then $\mathscr C$ is transduction equivalent to
	the class $\mathscr D$ of its clean bicotrees.
\end{lemma}

\begin{proof}
	We define the transduction $\interp T_h$ from $\mathscr C$ to $\mathscr D$ by induction on
	the height $h$ of a clean bicotree, the reverse transduction will be the trivial
	interpretation of bicotrees of height $h$.
	We only have to show how to build the tree, as
	transductions can provide unary predicates for free.


	If $h=1$, a single vertex is modelled by itself, so $\interp T_1 = \interp{Id}$
	works. Let us take instead $\interp T_1$ to be a monadic lift introducing the colors
	$\interp \Gamma_1$ and $\interp \Gamma_2$ of the
	vertices according to $\gamma$ so that it is done once and for all.

	Let $h>1$, and let $G$ be a graph of $\mathscr C$ with clean bicotree $\mathfrak T$.
	Using appropriate monadic expansions, we may assume that the transduction has access
	to the tree (it ``knows'' the tree, but still needs to define it using first order
	logic). We can thus make a case disjunction on the type of the root $u$ of $\mathfrak
	T$.

	If $u$ is of type U, let $G_1, \ldots, G_n$ be the connected components of $G$. By
	\Cref{sob_p7}, each $G_i$ has diameter at most $6$, so we can define the equivalence
	relation $x\sim y := \mbox{d}(x,y)\leq 6$ and have $G_i$s be the equivalence classes
	of $\sim$. Applying \Cref{eq_trans} with $\interp T_{h-1}$ yields $\interp T_h$.

	If $u$ is of type B, notice that bipartite complementation can be obtained by a
	transduction $\interp B$. Let $G_1, \ldots, G_n$ be the connected components of
	$\overline{G}^{\mbox{\tiny bip}}\in \interp B(G)$, as in the previous case we can apply
	\Cref{eq_trans} to $\interp T_{h-1}\circ \interp B$ and get  $\interp T_h$.

	If $u$ is of type O, let $G_1, \ldots, G_n$ be the subgraphs by the subtrees rooted
	at children of $u$. We first apply a monadic lift $\interp K$ introducing predicates
	$K_1, K_2, K_3$, that we refer as \emph{indices}, such that vertices of
	$G_i$ satisfy the predicate $K_{1+(i\mod 3)}$. We may write $\varkappa(x) = i$ as
	syntactic sugar for $\interp K_i(x)$. Let $u$ and $v$ be two vertices with
	distinct indices, they cannot be in the same $G_i$. If
	$\gamma(u)\neq\gamma(v)$, they can be ordered directly by checking the adjacency
	between them. Otherwise, they can be ordered by a universal formula expressing that
	the neighborhood of the rightmost vertex among vertices with the remaining index
	is included into the one of the leftmost vertex. If $u$ and $v$ have the same
	indices, either they are in the same $G_i$ and they cannot be ordered, or there is
	some vertices between them whose colors and adjacencies witness the order between
	$u$ and $v$. We summarize the formulas needed in the next table, where syntactic
	sugar has been used and redundant
	lines have been omitted for readability:
\bigskip

	\noindent\begin{tabular}{|Mc|p{.68\textwidth}|}
		\hline
		\gamma(x), \gamma(y), \varkappa(x)=\varkappa(y) &\multicolumn{1}{c|} {\centering formula defining  $x<y$}\\
		\hline
		1, 2, \bot & $E(x,y)$\\
		\hline
		2, 1, \bot & $\neg E(x,y)$\\
		\hline
		1, 1, \bot & $\big[\exists z.(\varkappa(z)\not\in \{\varkappa(x),\varkappa(y)\} \land E(x,z) \land \neg E(z,y) \big]\lor \newline \big[\varkappa(y)=\varkappa(x)+1\land \forall z. (\varkappa(z)\not\in \{\varkappa(x),\varkappa(y)\})\rightarrow (E(y,z)\rightarrow E(x,z))\big]$\\
		\hline
		2, 2, \bot & $\ldots$\\
		\hline
		1, 1, \top & $\exists z. \varkappa(z)\neq\varkappa(x)\land
		E(x,z)\land\neg E(z,y)$\\
		\hline
		2, 2, \top & $\ldots$\\
		\hline
		1, 2, \top & $\exists z_1, z_2. \varkappa(x) \not\in\{\varkappa(z_1),\varkappa(z_2)\} \land
	    E(x,z_1) \land \neg E(z_1,z_2) \land
		E(z_2, y)$\\
		\hline
		2, 1, \top & $\ldots$\\
		\hline
	\end{tabular}
\bigskip

	Once the order between the $G_i$s is defined, they can be defined themselves as
	equivalence classes of incomparability with respect to $<$, i.e. with $x\sim y :=
	\neg(x<y)\land\neg(y<x)$. There is then a transduction $\interp O$ which removes
    every edge between comparable vertices.
    We can again apply \Cref{eq_trans} on $\interp T_{h-1}\circ \interp O$
	to get $\interp T_h$.

\end{proof}

\section{Gluing}
\label{sec:gluing}

In this section, we use parameter 2 decompositions to leverage the transduction
equivalence obtained in the previous section to more complex classes of graphs.

\begin{theorem}\label{dec_transeq}
	Let $\mathscr C$ be a class of graphs admitting a parameter 2 decomposition into a
	class $\mathscr C'$, such that $\mathscr C'$ has a transduction pairing with a class
	$\mathscr D'$ of ordered degenerate graphs whose partial orders have cover graphs of
	bounded pathwidth.

	Then  $\mathscr C$ has a transduction pairing with a class $\mathscr D$ of ordered
	degenerate graphs whose partial orders have cover graphs of	bounded pathwidth.
\end{theorem}

\begin{proof}
	Let $N$ be an integer such that every graph of $\mathscr C$ admits a coloring
	into $N$ colors, two of which induce a graph of $\mathscr C'$. Let $(\interp T_C,
	\interp T_D)$ be the transduction pairing between $\mathscr C'$ and $\mathscr D'$.

	We consider the transduction $\interp T$ defined as the composition of an $N$-copy
	operation $\interp C$ and a transduction $\interp G_C$.
Let $G\in \mathscr C$. The vertex set of $\interp{C}(G)$ is identified with $V(G)\times [N]$ for convenience.
The transduction $\interp G_C$ is obtained by applying, for every $c_1,c_2\in[N]$ the transduction $\interp T_C$ applied to $G[V(G)\times\{c_2\},V(G)\times\{c_1\}]$ if $c_1\neq c_2$, or $G[V(G)\times\{c_1\}]$ if $c_1 = c_2$.
Furthermore, for every vertex of color $c$, every $c'$th copy (with $c'\neq c$) is joined by an edge to the $c$th copy.
Thus, the vertex set of $G$ can be identified with the vertices $(v,\gamma(v))$ of $\interp{C}(G)$. 

By this transduction, we obtain a similar gluing of structures of $\mathscr D'$, from
which we can go back to $\interp C(G)$ using some transduction $\interp G_D$. Setting
$\mathscr D = \interp T(\mathscr C)$, it is trivial that the edge relation of structures
in $\mathscr D$ is degenerate, as it is obtained from disjoint unions of degenerate
graphs by adding the edge set of a star forest. Furthermore, the cover graphs of the
partial order relation are disjoint unions of cover graphs of bounded pathwidth, hence
of bounded pathwidth.
\end{proof}

\thmMain*
\begin{proof}
According to \cite{SODA_msrw}, $\mathscr C$ has a parameter $2$ bounded embedded
shrubdepth cover. Taking a product coloring using \Cref{osd_dec}, $\mathscr C$ has a
parameter 2 decomposition into a class $\mathscr C'$ of bounded height cographs and sobs.
Cographs of bounded heights admit a transduction pairing with their cotrees as
already known from \cite[Lemma 31]{SBE_TOCL}, and sobs to their bicotrees by \Cref{sob_transeq}.
This gives a transduction pairing of $\mathscr C'$ with a class $\mathscr D$ of bounded height semi-plane
trees, hence of degenerate graphs with partial orders whose cover graphs have bounded pathwidth. The pathwidth
of the cover graphs is bounded by \Cref{fact:ws} as they are weakly sparse by construction and series-parallel, hence transduction of paths, so of bounded linear cliquewidth. By \Cref{dec_transeq}, $\mathscr C$ has the
desired transduction pairing.

\end{proof}
\pagebreak
We deduce the following stronger characterization of classes of graphs with
bounded linear cliquewidth.

\begin{lemma}
	\label{lem:order_all}
	Let $\mathscr P$ be a class of partial orders, $\mathscr G$ be a class of graphs, and $\mathscr C$ be a coupling of $\mathscr P$ and $\mathscr G$.

	Then, there exists a class of partial orders $\mathscr P'$ that has a transduction pairing with $\mathscr C$.
	Moreover, if both $\mathscr G$ and the class of the cover graphs of the partial orders in $\mathscr P$ are weakly sparse, we can require that the class of the cover graphs of the partial orders in $\mathscr P'$ is also weakly sparse.
\end{lemma}
\begin{proof}
	Let $\{<\}$, $\{E\}$, and
	$\varsigma=(<,E)$ be the signatures of the structures in $\mathscr P$ and $\mathscr P'$, in $\mathscr D$, and in $\mathscr C$, respectively.

	We first define the transduction $\interp{T_0}$, which is the composition of a $\interp{C}_4$ copying operation, and the transduction that defines the partial order as follows:
	\begin{align*}
		\rho_<(u,v)&:=\biggl(P_4(u)\wedge P_4(v)\wedge (u<v)\biggr)\vee
		\biggl(\bigvee_{2\leq i\leq 4} P_i(u)\wedge P_1(v)\wedge E(u,v)\biggr)\\
		&\qquad\vee \biggl(P_2(u)\wedge (P_3(v)\vee P_1(v))\wedge (\exists v'\ P_2(v')\wedge E(v,v')\wedge E(u,v'))\biggr)
	\end{align*}
	The class $\mathscr P'\subseteq \interp{T_0}(\mathscr C)$ is defined as follows: for each $\mathbf M\in \mathscr C$, we perform the copy operation, then mark the copies of $\mathbf M$ by the predicates $P_1,\dots,P_4$, then compute the partial order using the interpretation defined by $\rho_<$. 
	The meaning of $\rho_<$ is as follows:
	we keep the partial order part of $\mathbf M$ between the $P_4$-vertices. The $P_1$ vertices will form an antichain of maximum elements, each element being greater that its clones. Then, we add a cover between the clone in $P_2$ of a vertex $u$ and the clone in $P_3$ of a vertex $v$ is $u$ and $v$ are adjacent in $\mathbf M$ (by relation $E$). Adding this cover, we have to also the order relation between the clone of $u$ in $P_2$ and the clone of $v$ in $P_1$ (See \Cref{fig:order_all}).

	Assume that both $\mathscr G$ and the class of the cover graphs of the partial orders in $\mathscr P$ are weakly sparse. 
	By an easy application of pigeon-hole principle, if the cover graph of a partial order in $\mathscr P'$ contains a large balanced complete bipartite graph, we can assume that this complete bipartite graph is between elements marked $P_i$ and elements marked $P_j$.
	This clearly would contradict either the assumption on $\mathscr P$ or the assumption on $\mathscr G$.

	Conversely, we define a transduction $\interp{T_1}$ by
	\begin{align*}
		\iota(v)&=P_1(v)\\
		\rho_<(u,v)&=\exists u',v'\ P_4(u')\wedge P_4(v')\wedge (u'<u)\wedge (v'<v)\wedge (u'<v')\\
		\rho_E(u,v)&=\exists u',v'\ P_2(u')\wedge P_3(v')\wedge (u'<u)\wedge (v'<v)\wedge (u'<v')
	\end{align*}
	It is clear that $(\interp{T_0},\interp{T_1)}$ is a pairing of $\mathscr C$ and $\mathscr P'$.
\end{proof}

