\begin{lemma}
\label{lem:closure0}
	Let $\mathscr T_0$ be a class of  cotrees of height at most $h$, and $\interp{I_0}$ the
	interpretation from $\mathscr T_0$ to the cographs modeled by the cotrees.
	There exists a
	transduction $\interp{T_0}$ and an integer $C_0$ with following property:

    For $\mathbf T\in\mathscr T_0$ and $G=\interp{I_0}(\mathbf T)$, there exists a map
    $u\mapsto A_u^0$ from $V(G)$ to 
    $\mathcal P(V(G))$, such that $u\in A_u^0$, $|A_u^0|\leq
	C_0$, and for every $W\subseteq V(G)$ there exists $\mathbf T^0_W\in \interp T_0(G[W])$ such that for every $X\subseteq V(G)$ we have
\[
\bigcup_{u\in X}A^0_u\subseteq W\quad\Longrightarrow\quad 
    \mathbf T\langle X\rangle = \mathbf T^0_W\langle X\rangle.
    \]
\end{lemma}
\begin{proof}
Let $\prec$ be the ancestor order of $\mathbf T$. For $v\preceq u$ and $u\in V(G)$, we define a subset
$F_v^0(u)$ of descendants of $v$.
(The functions $F_v^0$ are extended to subsets of $V(G)$ in a standard way: $F_v^0(X)=\bigcup_{x\in X}F_v^0(x)$.)
First, to each internal node $v$ of $\mathbf T$, we associate a representative $\rho(v)$ that is a leaf of the subtree $\mathbf T{\upharpoonright}v$ rooted at $v$.
We let $F_r^0(u)=\set{u}$.
Assume $F_v^0(u)$ has been defined for some $v\prec u$.
Let $w$ be the child of $v$ that is an ancestor of $u$.
We define the set $W_v^0(u)$ as follows:
\begin{itemize}
\item if $v$ is a union node, then $W_v^0(u)$ is the vertex set of a shortest path from $u$ to $\rho(w)$ in $\interp{I_0}(\mathbf T{\upharpoonright}v)$;
\item if $v$ is a join node, then $W_v^0(u)$ is the vertex set of a shortest path from $u$ to $\rho(w)$ in the complement of $\interp{I_0}(\mathbf T{\upharpoonright}v)$.
\end{itemize}
We let $F_w^0(u)=F_v^0(W_v^0(u))$.
We repeat the process and let $A_u^0=F_u^0(u)$.

It is easily checked that the transduction $\mathsf T_0$ will construct a model $\mathbf T_W^0$ with $\mathbf T_W^0\langle X\rangle=\mathbf T\langle X\rangle$.    
\end{proof}


\begin{lemma}
\label{lem:closure}
	Let $\mathscr T$ be a class of clean bicotrees of height at most $h$, and $\interp{I}$ the
	interpretation from $\mathscr T$ to the graphs modeled by the bicotrees.
	There exists a
	transduction $\interp{T}$ and an integer $C$ with following property:

    For $\mathbf T\in\mathscr T$ and $G=\interp{I}(\mathbf T)$, there exists a map
    $u\mapsto A_u$ from $V(G)$ to 
    $\mathcal P(V(G))$, such that $u\in A_u$, $|A_u|\leq
	C$, and for every $W\subseteq V(G)$ there exists $\mathbf T_W\in \interp T(G[W])$ such that for every $X\subseteq V(G)$ we have
\[
\bigcup_{u\in X}A_u\subseteq W\quad\Longrightarrow\quad 
    \mathbf T\langle X\rangle = \mathbf T_W\langle X\rangle.
    \]
\end{lemma}

\begin{proof}
Let $\prec$ be the ancestor order of $\mathbf T$. For $v\preceq u$ and $u\in V(G)$, we define a subset
$F_v(u)$ of descendants of $v$.
(The functions $F_v$ are extended to subsets of $V(G)$ in a standard way: $F_v(X)=\bigcup_{x\in X}F_v(x)$.)
First, to each internal node $v$ of $\mathbf T$, we associate a representative $\rho(v)$ that is a leaf of the subtree $\mathbf T{\upharpoonright}v$ rooted at $v$.
We let $F_r(u)=\set{u}$.
Assume $F_v(u)$ has been defined for some $v\prec u$.
Let $w$ be the child of $v$ that is an ancestor of $u$.
We define the set $W_v(u)$ as follows:
\begin{itemize}
\item if $v$ has type U, then $W_v(u)$ is the vertex set of a shortest path from $u$ to $\rho(w)$ in $\interp{I}(\mathbf T{\upharpoonright}v)$;
\item if $v$ has type B, then $W_v(u)$ is the vertex set of a shortest path from $u$ to $\rho(w)$ in the bicomplement of $\interp{I}(\mathbf T{\upharpoonright}v)$;
\item if $v$ has type O, then $W_v(u)$ is any leaf of $\mathbf T{\upharpoonright}w$ with a color different from the one of $u$.
\end{itemize}
We let $F_w(u)=F_v(W_v(u))$.
We repeat the process and let $A_u=F_u(u)$.

It is easily checked that the transduction $\mathsf T$ will construct a model $\mathbf T_W$ with $\mathbf T_W\langle X\rangle=\mathbf T\langle X\rangle$.
\end{proof}


\begin{proof}[Proof of \Cref{strong_thm}]
    Let $\mathscr C$ be a class with bounded-size bounded linear cliquewidth decompositions.

    Considering a parameter $2$ decomposition and following similar arguments as in the proof of \Cref{th:main}, we infer that there are integers $n,h$ such that every graph $G\in\mathscr C$ admits a vertex partition into $n$ (possibly empty) parts $V_1,\dots,V_{n}$, such that $G[V_i]$ is a cograph with cotree of height at most $h$ and $G[V_i,V_j]$ is a sob with bicotree of height at most $h$.

    As seen in \Cref{lcw_dec_transeq}, $\mathscr C$ is transduction-equivalent to a class of ordered graphs $\mathscr D$ whose edge relation is degenerate and whose partial order has cover graphs of bounded pathwidth.
    Let us denote $(\interp T, \interp M)$ the transductions between $\mathscr C$ and $\mathscr D$.
    The ordered graphs in $\mathscr D$ are obtained by gluing the cotrees of the cographs $G[V_i]$ and the (clean) bicotrees of the sobs $G[V_i,V_j]$. Since the partial orders are obtained by disjoint union of partial orders
    with bounded pathwidth cover graphs, their cover graphs trivially have bounded pathwidth.
    Thus, we need only to consider the edge reducts and show that they have bounded
    expansion.

    Consider a parameter $p\in\mathbb N$.

    Let $G\in\mathscr C$ and $\mathbf{T} \in \interp{T}(G)\cap \mathscr D$ (so that $\interp{M}(\mathbf T) = G$, as we
    may restrict $\mathscr D$ to those models). Let $H$ be the edge reduct of $\mathbf T$.
    Let $X$ be a subset of (at most) $p$ vertices of $\mathbf T$. There is a set of leaves $Y\subseteq L(\mathbf T)$ such
    that $|Y|\le p$ and $X\subseteq \mathbf T\langle Y\rangle$. In particular $Y$ can be viewed as a subset of $V(G)$.
     Let $V_1,\ldots, V_n$ be the vertex partition associated
    with the parameter 2 decomposition of $G$.
    Applying \Cref{lem:closure0} to each $G[V_i]$ we get a closure operator $u\mapsto A_u^i$;
applying \Cref{lem:closure} to each $G[V_i,V_j]$ we get a closure operator $u\mapsto A_u^{i,j}$.    

    Now define 
\[
A_Y=\bigcup_{i\in[n]}\bigcup_{u\in Y\cap V_i}\biggl(A_u^i\cup\bigcup_{j\in[n]\setminus\set{i}}A_u^{i,j}\biggr).
\]
Note that $|A_Y|\leq q:=(C\binom{n}{2}+C_0n)p$, where $C_0$ and $C$ are the constants appearing in the statement of \Cref{lem:closure0,lem:closure}.
   As $\mathscr C$ has bounded-size bounded linear cliquewidth covers, there exists a integers $m_q$ and $t_q$ such that for every $G\in\mathscr C$ there exist subsets 
    $Q_1,\dots,Q_{m_q}$ of $V(G)$ with the following properties:
    \begin{itemize}
        \item the linear cliquewidth of $G[Q_i]$ is at most $t_q$;
        \item every subset of $V(G)$ with size at most $q$ is included in (at least one) $Q_i$.
    \end{itemize}
Note that the sets $Q_i$ depend on $q$.
Let $U_i = \{u\in V(G); A_u\subseteq V(Q_i)\}$. It follows from \Cref{lem:closure0,lem:closure}, that 
there exists a transduction $\interp G$ obtained by gluing such that
for every $W\subseteq V(Q_i)$ there exists $\mathbf R\in \interp G(Q_i[W])$ such that for every $X'\subseteq U_i$, 
if $X'\subseteq W$ then $\mathbf T\langle X'\rangle = \mathbf R\langle X'\rangle$. We let $\mathbf R_i \in \interp G(Q_i)$ corresponding to $W=V(Q_i)$, and $S_i$ its edge reduct. Since the graphs $Q_i$ have pathwidth
at most $t_q$, there exists an integer $t_q'$ (depending only on $q$) such that each $S_i$ has pathwidth at most $t'_q$.


Now by definition of the sets $Q_i$, there exists $i\in [m_q]$ such that $A_Y\subseteq V(Q_i)$, hence $Y\subseteq U_i$. It follows that $\mathbf T\langle Y\rangle = \mathbf R_i\langle Y\rangle$, hence
$H[X]\subseteq H\langle Y\rangle \subseteq S_i$. We deduce that
the edge reducts of the ordered graphs in $\mathscr D$ admit bounded size bounded pathwidth covers by the 
families $(S_i)_{i\in [m_q]}$, hence have bounded expansion.



\end{proof}






































\section{Concluding remarks}
\label{sec:conc}


In this section we discuss Conjecture~\ref{conj:inverse} and its consequences.

First, we notice that the conjecture has to impose some restriction on the partial order, for otherwise it would obviously hold: every class of graphs has a transduction pairing with a class of partial orders. Indeed, we consider the transduction $\interp{T}$ that is the composition of a copy operation that creates $3$ clones $(v,1), (v,2)$, and $(v,3)$ of each vertex $v$, then define (for distinct $(u,i)$ and $(v,j)$)
\[
(u,i)<(v,j)\quad\iff\quad\begin{cases}
    j=3\text{ and }u=v\\
    \text{ or }i=1,j=2,\text{ and }E(u,v).
\end{cases}
\]
As the constructed posets have bounded height, they are transduction-equivalent to their cover graphs. Hence,
if we apply this transduction to a hereditary unstable class of graphs, the cover graphs of the obtained partial orders will not be stable.
This shows that the weakest non-trivial version of \Cref{conj:inverse} would be

\begin{conj}
	\label{conj:inverseweak}
	Every dependent hereditary class of graph has a transduction pairing with a dependent hereditary class, consisting in the expansion of a hereditary stable class of graphs by a partial order having a stable cover graph.
\end{conj}

We start with an interesting consequence of Conjecture~\ref{conj:inverse}, if true.



\begin{proposition}
	Assuming \Cref{conj:inverse}, a class of graphs $\mathscr C$ is transduction-equivalent to a class  of partial orders whose cover graphs have bounded treewidth if and only if  $\mathscr C$ has bounded cliquewidth.
\end{proposition}
\begin{proof}
	If $\mathscr C$ is transduction-equivalent to a class $\mathscr P$ of partial orders whose cover graphs have bounded treewidth, then $\mathscr P$ is an {\sf MSO}-transduction of a class with bounded treewidth, hence has bounded cliquewidth.
	Conversely, assume that $\mathscr C$ has bounded cliquewidth.
	Then,  assuming \Cref{conj:inverse}, $\mathscr C$ is transduction equivalent to a $\varsigma$-structure, whose $E$-reduct is stable and whose $<$-reduct is a class of posets with bounded treewidth.
	Then, the $E$-reduct is  transduction-equivalent to a class $\mathscr D$ with bounded expansion \cite{SBE_TOCL}. Considering $\mathscr D$ instead of $\mathscr C$ if necessary, we may assume that the $E$-reduct is biclique-free.
	Then, according to \Cref{lem:order_all}, there exists a transduction pairing between
	$\mathscr C$ and a class of partial orders whose cover graphs form a weakly sparse
	class $\mathscr H$. A $\mathscr H$ is (by transitivity) a transduction of a class with bounded cliquewidth, it has bounded width. Then, it follows from \Cref{fact:ws} that $\mathscr H$ has bounded treewidth.
\end{proof}


