\section{An Adversarial Game Formulation}
\label{sec:problem}
The ancillary services market can be formulated as a multi-leader single follower bilevel problem. At the upper level, producers (leaders) bid strategically to maximize their revenues while anticipating the market clearing. At the lower level, the market operator (follower) determines the fractions of the bids that are accepted in order to minimize the total cost it has to pay to the producers to meet the zonal demands, while satisfying zonal, interzone and bid-related constraints. Because of the opposite objectives of the producers and market operator, the problem can be interpreted as an adversarial game, also called a zero sum game.

We define $\mathcal{N}\defeq\{1, \hdots, N\}$ as the set of $N$ producers and $\mathcal{Z}\defeq\{1,...,Z\}$ as the set of zones.
%We let $\mathcal{B}$ be the set of bids.
Each producer $n \in \mathcal{N}$ can bid up to $K_n \in \mathbb{N}^\star$ bids. Thus, the maximum number of bids is $B\defeq\sum_{n\in\mathcal{N}}K_n$. Further, each zone $z \in \mathcal{Z}$ has three input parameters: the total requested demand $D_z \geq 0$, the export limit $E_z \geq 0$ and the core portion $C_z \geq 0$. For all $n\in\mathcal{N}$, $z(n)\in\mathcal{Z}$ defines the zone of producer $n$ and $\mathcal{N}(z)\subseteq\mathcal{N}$ is the subset of producers in zone $z$. Each producer $n$'s decision variable is a finite sequence of bids $y_n \defeq \text{col}(\Delta_n,\pi_n) = \text{col}\Big((\Delta_{n,1},\pi_{n,1}),\dots,(\Delta_{n,K_n},\pi_{n,K_n})\Big)$, where $\Delta_n,\pi_n$ are producer $n$'s finite sequences of offered capacities and prices, respectively. The decision variables of the market operator are $x\defeq(x_{n,k}^z)_{n,k,z} \in [0,1]^{B\times Z}$, where $x_{n,k}^z$ represents the fraction of bid activated in each zone. A summary of the definitions is in Tab.~\ref{tab:notation}.

\subsection{Producers}
Each producer $n \in \mathcal{N}$ has a capacity $\Delta^{max}_n\geq 0$ and a marginal price $\pi^{min}_n \geq 0$, and can either submit a single price (with full capacity) or a finite sequence of price and quantity pairs satisfying the following constraints involving finite upper and lower bounds:
\begin{subequations}
    \begin{align}
        &  \pi^{min}_n\leq \pi_{n,k}\leq \pi^{max}_n,\quad \forall\; k\in\{1,\dots,K_n\},\label{eq:price_bound}\\
        & \Delta^{min}_n\leq\Delta_{n,k}\leq\Delta^{max}_n,\quad\forall\; k\in\{1,\dots,K_n\},\label{eq:capacity_bound}\\
        &  \sum_{k=1}^{K_n}\Delta_{n,k} \leq \Delta^{max}_n.\label{eq:tot_capacity_bound}
    \end{align}
    \label{eq:producer_const}
\end{subequations}
We define producer $n$'s feasibility set as $\mathcal{Y}_n \defeq \{y_n\in \mathbb{R}^{2\times K_n}\,|\, y_n \mbox{ satisfies Eqs.\eqref{eq:producer_const}} \}$. The objective of producer $n$ is to maximize its revenue defined as follows:
\begin{equation}
    J_n(y_n,x_n) \defeq \sum_{k=1}^{K_n}\pi_{n,k}\Delta_{n,k}\left(\sum_{z\in \mathcal{Z}} x_{n,k}^z\right).
    \label{eq:J_n}
\end{equation}

\subsection{Market Operator}
The market operator deals with four sets of constraints that depend on the capacities $\Delta_{n,k}, \forall k\in[1,K_n],n\in\mathcal{N}$ submitted by the producers:\\
\textbf{Zonal Demand}
\begin{equation}
    \sum_{n\in\mathcal{N}}\sum_{1\leq k\leq K_n}x_{n,k}^z\Delta_{n,k}\geq D_z,\quad \forall z\in\mathcal{Z}. \label{eq:demand_c}
\end{equation}
\textbf{Capacity Limit}
\begin{equation}
    \sum_{z\in\mathcal{Z}} x_{n,k}^z\leq 1,\quad \forall k\in[1,\dots,K_n],\quad\forall n\in\mathcal{N}. \label{eq:accepted_c}
\end{equation}
\textbf{Export Limit}
\begin{equation}
    \sum_{n\in\mathcal{N}(z)}\sum_{1\leq k\leq K_n}\sum_{z'\neq z}x_{n,k}^{z'}\Delta_{n,k} \leq E_z,\quad \forall z\in\mathcal{Z}. 
    \label{eq:export_c}
\end{equation}
\textbf{Core Portion}
\begin{equation}
    \sum_{n\in\mathcal{N}(z)}\sum_{1\leq k\leq K_n} x_{n,k}^z\Delta_{n,k}\geq C_z,\quad \forall z\in\mathcal{Z}.
    \label{eq:core_c}
\end{equation}
Eq.~\eqref{eq:demand_c} ensures that the total demand in each zone is met, Eq.~\eqref{eq:core_c} ensures that there is a given amount of the demand of a specific zone satisfied by the producers in that zone, while Eq.~\eqref{eq:export_c} gives a cap to the amount of energy that can be exported.
Finally, Eq.~\eqref{eq:accepted_c} captures the fact that for a given bid $(n,k)$, the sum of the fractions activated in each zone is normalized. Constraints \eqref{eq:demand_c}-\eqref{eq:core_c} can be compactly written under the form
$$\Phi(x,y) \leq 0,$$ and we denote $\mathcal{X}(y):=\{x\in[0,1]^{B\times Z}:\Phi(x,y)\leq0\}$ the feasibility set of the market operator which depends on the profile of strategies of the producers $y:=(y_n)_n$.
The market operator aims to minimize the total cost it has to pay to the producers. Its objective function takes the form:
\begin{equation}
    J_{\text{MO}}(x,y) \defeq \sum_{n\in\mathcal{N}}\sum_{1\leq k\leq K_n}\left(\sum_{z\in\mathcal{Z}}x_{n,k}^z\right)\Delta_{n,k}\pi_{n,k}.
    \label{eq:J_mo}
\end{equation}
The market operator determines the fractions of bids to activate in each zone $(x_{n,k}^z)_{n,k,z}$, under constraints \eqref{eq:demand_c}-\eqref{eq:core_c}:
\begin{subequations}
    \begin{align}
    \min_{x} & \quad J_{\text{MO}}(x,y), \label{eq:market_obj}\\
    \text{s.t.} & \quad x\in\mathcal{X}(y).
\end{align}
\label{eq:market_clearing}
\end{subequations}
