\subsection{Market Clearing and KKT Reformulation}
We formulate the ancillary market clearing problem  as a pessimistic multi-leader single follower bilevel optimization problem:
\begin{subequations}
\begin{alignat}{3}
    &\forall n\in \mathcal{N}, \quad && \min_{x_n} \max_{y_n}&& \quad  J_n(y_n,x_n), \label{eq:MO:1} \\
    & && \text{s.t.} && x \in \argmin_{x \in \mathcal{X}(y)} \quad J_{\text{MO}}(x,y), \label{eq:MO:2}\\
    & && && y\in \prod_j\mathcal{Y}_j. \label{eq:MO:3}
\end{alignat}
\label{eq:full_problem}
\end{subequations}
With this formulation, each producer optimizes its bids without considering the different zones. Such a distinction is made by the market operator when it determines the fraction of bids accepted in each zone. Further, each producer's objective function is independent of the other producers' strategies. Coupling between the objective functions occurs through the market operator's strategy. In case of multiple solutions at the lower level, the pessimistic formulation enables the selection of the worst equilibrium for the producers, obtaining a more robust formulation of the market.
%If the $\min$ operator were to be removed in Eq.~\eqref{eq:MO:1}, multiple solutions might be considered at the lower level \eqref{eq:MO:2}-\eqref{eq:MO:3}.

The Lagrangian function associated with the market clearing defined in problem \eqref{eq:market_clearing} takes the form:
\begin{equation}
    L(x,y;\Lambda) = \sum_{n\in\mathcal{N}}\sum_{k=1}^{ K_n}\left(\sum_{z\in\mathcal{Z}}x_{n,k}^z\right)\Delta_{n,k}\pi_{n,k} + \Lambda^\top\Phi(x,y),
    \label{eq:lagrangian}
\end{equation}
where $\Lambda \in \mathbb{R}_{+}^{3Z+B}$ refers to the dual variables associated with constraints~\eqref{eq:demand_c}-\eqref{eq:core_c}. The analytical expression of the Lagrangian function in \eqref{eq:lagrangian} can be found in Appendix~\ref{app:kkt}.
%Notice that the derivatives of the constraints associated to the multipliers $\sigma$ and $\delta$ have a non trivial behavior depending on the zone. 
\begin{lemma}[Slater's Constraint Qualification] \label{lem:slater}
    Slater's constraint qualification holds if one of these conditions is satisfied
    \begin{itemize}
        \item[(i)] $\displaystyle{\sum_{n\in \mathcal{N}(z)}}\Delta_n^{\max} > D_z,\;\forall z\in\mathcal{Z}$,
        \item[(ii)] $\displaystyle{\sum_{z'\neq z}}\left(\sum_{n\in \mathcal{N}(z')}\Delta_n^{\max}-D_{z'}\right) > D_z - \sum_{n\in \mathcal{N}(z)}\Delta_n^{\max}$ \\
        and $D_z - \sum_{n\in \mathcal{N}(z)}\Delta_n^{\max}\leq \sum_{z'\neq z}E_{z'}$.
    \end{itemize}
\end{lemma}
\begin{proof}
Under condition (i), each zone can satisfy its own demand; thus, there exists an interior-point solution. Under condition (ii), one zone $z \in \mathcal{Z}$ may not be able to meet its own demand, i.e., $D_z - \sum_{n\in \mathcal{N}(z)}\Delta_n^{\max}>0$. In this situation, we need enough demand offers left from other zones to cover the lack of supply, thus $\sum_{z'\neq z}\left(\sum_{n\in \mathcal{N}(z')}\Delta_n^{\max}-D_{z'}\right) > D_z - \sum_{n\in \mathcal{N}(z)}\Delta_n^{max}$. Since the export constraint should hold, we get that $D_z - \sum_{n\in \mathcal{N}(z)}\Delta_n^{\max}\leq \sum_{z'\neq z}E_{z'}$.
\end{proof}
When the lower-level problem \eqref{eq:market_clearing} satisfies Lemma~\ref{lem:slater}, we can replace it by its KKTs in \eqref{eq:full_problem}. Hence, each producer has to anticipate the decision $x$ of the market operator, meaning that in the single level the decision variables for producer $n$ will be $y_n \in \mathcal{Y}_n$ and $x_n \in \mathcal{X}_n(y)$. %In addition, each producer also has the vector $\Lambda_n$ of dual decision variables coming from the market clearing reformulation.
Before writing the full reformulation, we introduce tracking variables for every $z\in \mathcal{Z}$:
\begin{subequations}
    \begin{align}
        & d^z_n(x_{-n},y_{-n}) \defeq D_z - \sum_{j\neq n}\sum_{1\leq k\leq K_j}x_{j,k}^z\Delta_{j,k},\\
        & e^z_n(x_{-n},y_{-n}) \defeq E_z - \sum_{\substack{j\in \mathcal{N}(z),\\j\neq n}} \sum_{z'\neq z}\sum_{1\leq k\leq K_j} x_{j,k}^{z'}\Delta_{j,k},\\
        & c^z_n(x_{-n},y_{-n}) \defeq C_z - \sum_{\substack{j\in \mathcal{N}(z),\\j\neq n}} \sum_{1\leq k\leq K_j} x_{j,k}^z\Delta_{j,k}.
    \end{align}
\end{subequations}
The single-level problem for agent $n$ is
\begin{comment}
\begin{subequations}
\begin{alignat}{2}
    \min_{x_n}\,\max_{y_n,\Lambda_n}& J_n(&&y_n,x_n), \label{eq:single_level_obj}\\
    \mbox{s.t. }  & y_n\in&&\mathcal{Y}_n, x_n\in \mathcal{X}_n(y), \Lambda_n\geq0,\\
    & \nabla_{x_n}&&L(x_n,y_n;\Lambda_n) = 0,\label{eq:KKT_market}\\
