\section{Mathematical Proofs}\label{sec:appendixproofs}
\subsection{\Cref{prop:trajsol}}
Integrating the equation for $\widehat T_{k,t}$ by  using~\cref{eq:shearfouriersol} we find
\begin{align}
\widehat T_{k,t} &= -\alpha \int_0^t \exp(-\gamma_{T,k}(t-s) + i \omega_{T,k}[s,t])\hat v_{k,s} \, ds \\
&= -\alpha \sigma_{v,k} \int_0^t \int_0^s \exp(-\gamma_{T,k}(t-s) -\gamma_{v,k}(s-r) +  + i \omega_{T,k}[s,t] +  i \omega_{v,k}[r,s]) \, d B_{k,r} \, ds  \\
&=  -\alpha \sigma_{v,k}  \int_0^t   \int_r^t \exp(-\gamma_{T,k}(t-s) -\gamma_{v,k}(s-r) +  + i \omega_{T,k}[s,t] +  i \omega_{v,k}[r,s])   \, ds \, d B_{k,r}.
\end{align}
Fubini's theorem is used in the last equality to exchange the order of integration.
\subsection{\Cref{prop:condvar}}
The derivation of the variance of trajectory solutions conditioned on a zonal flow trajectory is given by
\begin{align}
    \Sigma_{k,t\mid u} &=   \alpha^2 \sigma_{v,k}^2 \int_0^t \biggl\lvert \int_r^t  \exp(-\gamma_{T,k}(t-s) -\gamma_{v,k}(s-r) +  + i \omega_{T,k}[s,t] +  i \omega_{v,k}[r,s])   \, ds  \biggr\rvert^2  \, dr \\
     &=\alpha^2 \sigma_{v,k}^2 \int_0^t \biggl\lvert \int_r^t  \exp(-\gamma_{T,k}t + \gamma_{v,k} r + \gamma_{R,k} s + i \omega_{T,k}[s,t] +  i \omega_{v,k}[r,t] -   i \omega_{v,k}[s,t]) )  \, ds  \biggr\rvert^2  \, dr\\
     &=\alpha^2 \sigma_{v,k}^2 \int_0^t \biggl\lvert  \int_r^t  \exp(-\gamma_{T,k}t + \gamma_{v,k} r  +  i \omega_{v,k}[r,t]  + \gamma_{R,k} s + i \omega_{R,k}[s,t]    \, ds  \biggr\rvert^2  \, dr \\
      &=\alpha^2 \sigma_{v,k}^2 \int_0^t \biggl\lvert   \exp(-\gamma_{T,k}t + \gamma_{v,k} r  +  i \omega_{v,k}[r,t] ) \int_r^t  \exp( \gamma_{R,k} s + i \omega_{R,k}[s,t] )   \, ds  \biggr\rvert^2  \, dr  \\
      &=\alpha^2 \sigma_{v,k}^2 \int_0^t  \exp(-2\gamma_{T,k}t + 2\gamma_{v,k} r)  \biggl\lvert   \int_r^t  \exp( \gamma_{R,k} s + i \omega_{R,k}[s,t] )   \, ds  \biggr\rvert^2  \, dr ,
\end{align}
where  $\omega_{R,k} \coloneqq \omega_{T,k} - \omega_{v,k} = -(a_k+k)u_t - b_k$
    and  $\gamma_{R,k} \coloneqq \gamma_{T,k} - \gamma_{v,k}$.
Alternatively, we can express the variance as:
\begin{equation}\label{eq:integralcomplete}
{\Sigma_{k,t\mid u} = \alpha^2 \sigma_{v,k}^2 \int_0^t  \exp(-2\gamma_{v,k} (t-r) )  \biggl\lvert   \int_r^t  \exp( -\gamma_{R,k} (t-s) + i \omega_{R,k}[s,t]  )  \, ds  \biggr\rvert^2  \, dr.}
\end{equation}

\subsection{\Cref{cor:varbound}}
We can   find an upper bound for the conditional variance as follows.
Start from~\cref{eq:altintegral}  and first use $\abs{\int z} \le \int \abs{z} = \int r$, where $z = r e^{i \theta}$, for the inner integral to obtain:
\begin{align}
 \biggl\lvert   \int_r^t  \exp( \gamma_{R,k} s + i \omega_{R,k}[s,t] )   \, ds \biggr\rvert^2 \le \biggl(\int_r^t e^{ \gamma_R s} \, ds\biggr)^2 =  \frac{1}{\gamma_R^2}(e^{\gamma_R t} - e^{\gamma_R r})^2\le \frac{1}{\gamma_R^2} (e^{2 \gamma_R t} + e^{2 \gamma_R r}),
\end{align}
\begin{align}
\Sigma_{k,t\mid u} &=\alpha^2 \sigma_{v,k}^2 \int_0^t  \exp(-2\gamma_{T,k}t + 2\gamma_{v,k} r)  \biggl\lvert   \int_r^t  \exp( \gamma_{R,k} s + i \omega_{R,k}[s,t] )   \, ds  \biggr\rvert^2  \, dr\\
&\le \alpha^2 \sigma_{v,k}^2 \int_0^t  \exp(-2\gamma_{T,k}t + 2\gamma_{v,k} r)  \frac{1}{\gamma_{R,k}^2} (e^{2 \gamma_{R,k} t} + e^{2 \gamma_{R,k} r})  \, dr\\ &= \alpha^2 \sigma_{v,k}^2 \int_0^t   \frac{1}{\gamma_{R,j}^2} (e^{-2 \gamma_{v,k}( t-r)} + e^{-2 \gamma_{T,k} (t-r)})  \, dr \\ &= \frac{\alpha^2 \sigma_{v,k}^2 }{\gamma_{R,k}^2}\biggl(\frac{1 - e^{-2\gamma_{v,k}t}}{2 \gamma_{v,k}}  +  \frac{1 - e^{-2\gamma_{T,k}t}}{2 \gamma_{T,k}} \biggr)
\end{align}
We also find the bound in the long time limit
\begin{equation}
    \lim_{t \to \infty} \Sigma_{k,t\mid u} \leq \frac{\alpha^2 \sigma_{v,k}^2}{\gamma_{R,k}^2} \biggl( \frac{1}{2\gamma_{v,k}} + \frac{1}{2\gamma_{T,k}} \biggr)
\end{equation}


\subsection{\Cref{prop:tracermodepdf}}
Starting from~\cref{eq:integralcomplete} for the rescaled system in~\cref{cor:rescaled},
\begin{equation}\label{eq:condvar_appendix}
    {\Sigma_{k,t\mid u} = \epsilon^{-2}\alpha^2 \sigma_{v,k}^2 \int_0^t  \exp(-2\gamma_{v,k} (t-r) )  \biggl\lvert   \int_r^t  \exp( -\gamma_{R,k} (t-s) + i \epsilon^{-1} \omega_{R,k}[s,t]  )  \, ds  \biggr\rvert^2  \, dr,}
    \end{equation}
where $\gamma_{R,k} = \epsilon^{-1}  \gamma_{T,k} - \gamma_{v,k}$. Define the inner integral
\begin{equation}
    I(r) \coloneq   \int_r^t \exp\Bigl(-\bigl(\epsilon^{-1} \gamma_{T,k}  - \gamma_{v,k}\bigr)(t-s) + i \epsilon^{-1} \omega_{R,k}[s,t] \Bigr) \, ds,
\end{equation}
where $\omega_{R,k}[s,t] =\int_s^t \omega_{R,k}(u)\, du$. Consider the change of variables $u = t-s$,
\begin{equation}
    I(r) =   \int_0^{t-r}    \exp\Bigl(- \epsilon^{-1} \gamma_{T,k} u \Bigr)
    \exp\Bigl(  \gamma_{v,k} u  + i\epsilon^{-1} \omega_{R,k}[t-u,t] \Bigr) \, du,
\end{equation}
In the small $\epsilon$ limit, most of the contribution to this integral comes from when $u$ is small.  As a result $\omega_{R,k}[t-u,t] \approx \omega_{R,k}(t) u$:
\begin{equation}
    I(r) \approx   \int_0^{t-r} \exp\bigl( \epsilon^{-1}(- {\gamma_{T,k}}       + i  \omega_{R,k}(t) ) u \bigr) \, du,
\end{equation}
This integral is of the form
\begin{equation}
    \int_0^{t-r} \exp(-\lambda u) du = \frac{1}{\lambda}(1-\exp(-\lambda(t-r))), \quad \text{where } \lambda =  \epsilon^{-1}( {\gamma_{T,k}} - i  \omega_{R,k}(t)
\end{equation}
Taking the modulus square and keeping only leading order terms we find
\begin{equation}
    \lvert I(r) \rvert^2 \approx \frac{\epsilon^2}{ \gamma_{T,k}^2  +   \omega_{R,k}(t) ^2}.
\end{equation}
Using this result in~\cref{eq:condvar_appendix} we obtain
\begin{align}
    \Sigma_{k,t\mid u} &= \epsilon^{-2}\alpha^2 \sigma_{v,k}^2 \int_0^t  \exp(-2\gamma_{v,k} (t-r) )  \frac{\epsilon^2}{ \gamma_{T,k}^2  +   \omega_{R,k}(t) ^2}  \, dr  \\
    &=  \frac{\alpha^2\sigma_{v,k}^2 }{2\gamma_{v,k} \bigl(\gamma_{T,k}^2  +   \omega_{R,k}(t) ^2\bigr)}\bigl(1- \exp(-2\gamma_{v,k}  t ) \bigr).
\end{align}
As $t\to \infty$, the conditional variance $\Sigma_{k,t\mid u}$   converges to the stationary value
\begin{equation}
    \tilde \Sigma_{k}(u) = \frac{\alpha^2 E_{v,k}}{\gamma_{T,k}^2 + \omega_{R,k}(u)^2},   \quad \text{where } E_{v_k} =  \frac{\sigma^2_{v,k}}{2\gamma_{k,v}}.
\end{equation}


