\title{\huge ArgMed-Agents: Explainable Clinical Decision Reasoning with LLM Disscusion via Argumentation Schemes}

\author{
	\IEEEauthorblockN{Shengxin Hong, Liang Xiao, Xin Zhang, Jianxia Chen,}
