\subsection{Space semi-discrete formulation and algebraic realization} 

The space semi-discrete formulation of the model problem \eqref{weak_form_acoustic_eq}-\eqref{weak_form_elastic_eq} consists in finding $(p_{\Tf}(t),$ $ p_{\Ff}(t), \bd{m}_{\Tf}(t)) : J \longrightarrow P^{k^\prime}(\Tf) \times P^{k}(\Ff) \times \bd{M}^{k}(\Tf)$ in the fluid subdomain and $(\bd{v}_{\Ts}(t), \bd{v}_{\Fs}(t),$ $\bbm{s}_{\Ts}(t)) \in \bd{V}^{k^\prime}(\Ts) \times \bd{V}^{k}(\Fs) \times \bbm{S}^{k}(\Ts)$ in the solid subdomain, such that, for all $t \in \overline{J}$,
\begin{subequations}
\label{HHO1}
\begin{align}
(\partial_t \bd{m}_{\Tf}(t) & , \bd{r}_{\Tf})_{{\bd{L}^2(\rho^\sc{f};\domain{f})}} - (\bd{g}_{\Tf}(p_{\Tf}(t),p_{\Ff}(t)), \bd{r}_{\Tf})_{{\bd{L}^2(\domain{f})}} = 0,\\
(\partial_t p_{\Tf}(t) & ,q_{\Tf})_{{L^2(\frac{1}{\kappa}; \domain{f})}} + (\bd{m}_{\Tf}(t), \bd{g}_{\Tf}(q_{\Tf},q_{\Ff}))_{{\bd{L}^2(\domain{f})}} \nonumber\\
& + s^{\sc{f}}((p_{\Tf}(t),p_{\Ff}(t)),(q_{\Tf},q_{\Ff})) + (\bd{v}_{\Fs}(t) {\cdot} \bd{n}_{\G}, q_{\Ff})_{L^2(\G)} = (f^{\sc{f}}(t),q_{\Tf})_{L^2(\domain{f})}, 
\end{align}
\end{subequations}  
for all $\bd{r}_{\Tf} \in \bd{M}^{k}(\Tf)$ and all $(q_{\Tf}, q_{\Ff}) \in P^{k^\prime}(\Tf) \times P^{k}(\Ff)$, and 
\begin{subequations}
\label{HHO2} 
\begin{align}
(\partial_t & \bbm{s}_{\Ts}(t), \bbm{b}_{\Ts})_{\bbm{L}^2(\bbm{C}^{-1};\domain{s})} - (\bbm{g}^{\rm{sym}}_{\Ts}(\bd{v}_{\Ts}(t),\bd{v}_{\Fs}(t)), \bbm{b}_{\Ts})_{\bbm{L}^2(\domain{s})} = 0,\\
(\partial_t & \bd{v}_{\Ts}(t), \bd{w}_{\Ts})_{\bd{L}^2(\rho^\sc{s};\domain{s})} + (\bbm{s}_{\Ts}(t), \bbm{g}_{\Ts}^{\rm{sym}}(\bd{w}_{\Ts},\bd{w}_{\Fs}))_{\bbm{L}^2(\domain{s})} \nonumber\\
& + s^{\sc{s}}((\bd{v}_{\Ts}(t),\bd{v}_{\Fs}(t)), (\bd{w}_{\Ts},\bd{w}_{\Fs})) -(p_{\Ff}(t) \bd{n}_{\G},\bd{w}_{\Fs})_{\bd{L}^2(\G)} = (\bd{f^{\sc{s}}}(t), \bd{w}_{\Ts})_{\bd{L}^2(\domain{s})},
\end{align}
\end{subequations}   
for all $\bbm{b}_{\Ts} \in \bbm{S}^k(\Ts)$ and all $(\bd{w}_{\Ts},\bd{w}_{\Fs}) \in \bd{V}^{k^\prime}(\Ts) \times \bd{V}^{k}(\Fs)$. Here, $\bd{g}_{\Tf}$, $\bbm{g}^{\rm{sym}}_{\Ts}$, $s^{\sc{f}}$, and $s^{\sc{s}}$ are the global (symmetric) gradient reconstruction operators and global stabilization bilinear forms whose expressions are given by the right-hand sides of equations \eqref{rec}-\eqref{stab} below. The main ideas are the following: the (symmetric) gradient reconstruction allows to consistently and locally build the (symmetric) gradient of the primal variable using both its cell and face dofs; the stabilization bilinear form weakly enforces locally the matching of the trace of the cell dofs with the face dofs. The reader is referred to \cite{MEKG_2025} for further insight into the HHO formulation.

To derive the algebraic realization of \eqref{HHO1}-\eqref{HHO2}, we consider the following generic bases:
\begin{subequations}
\begin{alignat}{5}
& \{\varphi_i\}_{1 \leq i \leq N_{\Tf}^{k^\prime}}, & \qquad & \{\psi_i \}_{1 \leq i \leq N_{\Ff}^{k}}, & \qquad & \{\bd{\zeta}_k\}_{1 \leq k \leq M_{\Tf}^{k}},\\
& \{\bd{\phi}_i\}_{1 \leq i \leq L_{\Ts}^{k^\prime}}, & \qquad & \{\bd{\theta}_i \}_{1 \leq i \leq L_{\Fs}^{k}}, & \qquad & \{\bbm{Y}_k\}_{1 \leq k \leq H_{\Ts}^{k}},
\end{alignat}
\end{subequations}
with the corresponding dimensions
\begin{subequations}
\begin{alignat}{5}
& N_{\Tf}^{k^\prime} := \dim(P^{k^\prime}(\Tf)), & \qquad & N_{\Ff}^{k} := \dim(P^{k}(\Ff)), & \qquad & M_{\Tf}^{k} := \dim(\bd{M}^{k}(\Tf)),\\
& L_{\Ts}^{k^\prime} := \dim(\bd{{V}}^{k^\prime}(\Ts)), & \qquad & L_{\Fs}^{k} := \dim(\bd{{V}}^{k}(\Fs)), & \qquad & H_{\Ts}^{k} := \dim(\bbm{S}^k(\Ts)).
\end{alignat}
\end{subequations}
The basis $\{\bd{\zeta}_k\}_{1 \leq k \leq M_{\Tf}^{k}}$ is build by combining Cartesian basis vectors of $\bbm{R}^d$ with scalar basis functions of $P^{k}(\Tf)$. Similarly, the bases $\{\bd{\phi}_i \}_{1 \leq i \leq L_{\Ts}^{k^\prime}}$, $\{\bd{\theta}_i \}_{1 \leq i \leq L_{\Fs}^{k}}$ and $\{\bbm{Y}_k\}_{1 \leq k \leq H_{\Ts}^{k}}$ are built by combining Cartesian basis vectors of $\bbm{R}^{d}$, $\bbm{R}^{d}$ and $\bbm{R}_{\text{sym}}^{d \times d}$, respectively, with scalar basis functions of $P^{k^\prime}(\Ts)$, $P^{k}(\Fs)$ and $P^{k}(\Ts)$, respectively. For all the scalar-valued polynomial spaces, we use a local modal basis composed of monomials centered at the barycenter of the corresponding geometric object.

