\paragraph{Mass matrices.} The mass matrices $\mass{\rho^{\sc{f}}}{f} \in \bbm{R}^{M_{\Tf}^{k} \times M_{\Tf}^{k}}$ and $\mass{\frac{1}{\kappa}}{f} \in \bbm{R}^{N_{\Tf}^{k^\prime} \times N_{\Tf}^{k^\prime}}$ are associated with the inner products in $\bd{L}^2(\rho^\sc{f}; \Omega^\sc{f})$ and $L^2(\frac{1}{\kappa}; \Omega^\sc{f})$, respectively, and the mass matrices $\mass{\bbm{C}^{-1}}{s} \in \bbm{R}^{H_{\Ts}^{k} \times H_{\Ts}^{k}}$ and $\mass{\rho^{\sc{s}}}{s} \in \bbm{R}^{L_{\Ts}^{k^\prime} \times L_{\Ts}^{k^\prime}}$ are associated with the inner products in $\bbm{L}^2_{\rm{sym}}(\bbm{C}^{-1};\Omega^\sc{s})$ and $\bd{L}^2(\rho^\sc{s}; \Omega^\sc{s})$, respectively. Their (classical) expressions are as follows:
\begin{subequations}\label{mass}
\begin{alignat}{6}
& \dofs{M}{T}{f}^{\dagger} \mass{\rho^{\sc{f}}}{f} \rm{R}_{\T^\sc{f}} 
&& = \sum_{T \in \Tf} \rho^{\sc{f}}(\bd{m}_T, \bd{r})_{\bd{L}^2(T)}, \qquad
&& \dofs{P}{T}{f}^{\dagger} \mass{\frac{1}{\kappa}}{f} \rm{Q}_{\T^\sc{f}} 
&& = \sum_{T \in \Tf} \frac{1}{\kappa}({p}_T, q)_{{L}^2(T)}, \\  
& \dofs{S}{T}{s}^{\dagger} \mass{\bbm{C}^{-1}}{s} \rm{B}_{\T^\sc{s}} 
&& = \sum_{T \in \Ts} \bbm{C}^{-1}(\bbm{s}_T, \bbm{b})_{\bbm{L}^2(T)}, \qquad
&& \dofs{V}{T}{s}^{\dagger} \mass{\rho^{\sc{s}}}{s} \rm{W}_{\T^\sc{s}} 
&& = \sum_{T \in \Ts} \rho^{\sc{s}}(\bd{v}_T, \bd{w})_{\bd{L}^2(T)},
\end{alignat}                 
\end{subequations}
for all $\bd{m}_{\Tf}, \bd{r} \in \bd{P}^{k}(\Tf)$ and all $p_{\Tf}, q \in {P}^{k^\prime}(\Tf)$ with component vectors $\dofs{M}{T}{f}$, $\rm{R}_{\T^\sc{f}}$ and $\dofs{P}{T}{f}$, $\rm{Q}_{\T^\sc{f}}$, respectively, and all $\bbm{s}_{\Ts}, \bbm{b} \in \bbm{S}^{k}(\Ts)$ and all $\bd{v}_{\Ts}, \bd{w} \in \bd{P}^{k^\prime}(\Ts)$ with component vectors $\dofs{S}{T}{s}$, $\rm{B}_{\T^\sc{s}}$ and $\dofs{V}{T}{s}$, $\rm{W}_{\T^\sc{s}}$, respectively.

\paragraph{Gradient reconstruction blocks.} The gradient reconstruction blocks $\graddiag{T}{f} \in \bbm{R}^{M_{\Tf}^{k} \times N_{\Tf}^{k^\prime}}$ and $\grad{T}{F}{f} \in \bbm{R}^{M_{\Tf}^{k} \times N_{\Ff}^{k}}$ and the symmetric gradient reconstruction blocks $\straindiag{\T} \in \bbm{R}^{H_{\Ts}^{k} \times L_{\Ts}^{k^\prime}}$ and $\strain{T}{F} \in \bbm{R}^{H_{\Ts}^{k} \times L_{\Fs}^{k}}$ are defined so that they satisfy
\begin{subequations}\label{rec}
\begin{alignat}{6}
\label{rec_a}
& (\graddiag{T}{f}\dofs{\rm{P}}{T}{f} + \grad{T}{F}{f} \dofs{\rm{P}}{F}{f})^{\dagger} \rm{R}_{\T^\sc{f}} 
&& = \sum_{T \in \Tf} \left\{(\nabla p_T, \bd{r})_{\bd{L}^2(T)} - (p_{T} - p_{\partial T}, \bd{r} {\cdot} \bd{n}_T)_{L^2(\partial T)} \right\}, \\  
& (\straindiag{T}\dofs{\rm{V}}{T}{s} + \strain{T}{F} \dofs{\rm{V}}{F}{s})^{\dagger} \rm{B}_{\T^\sc{s}} 
&& = \sum_{T \in \Ts} \left\{ (\nabla_{\rm{sym}} \bd{v}_T, \bbm{b})_{\bbm{L}^2_{\rm{sym}}(T)} - (\bd{v}_T - \bd{v}_{\partial T}, \bbm{b} {\cdot} \bd{n}_T)_{\bd{L}^2(\partial T)} \right\},
\label{rec_e}
\end{alignat}                 
\end{subequations}
for all $(p_{\Tf},p_{\Ff}) \in P^{k^\prime}(\Tf) \times P^{k}(\Ff)$, all $(\bd{v}_{\Ts},\bd{v}_{\Fs}) \in \bd{V}^{k^\prime}(\Tf) \times \bd{V}^{k}(\Ff)$ with component vectors $\dofs{P}{T}{f}$, $\dofs{P}{F}{f}$ and $\dofs{V}{T}{s}$, $\dofs{V}{F}{s}$, respectively, and for all $\bd{r} \in \bd{M}^{k}(\Tf)$, all $\bbm{b} \in \bbm{S}^k(\Ts)$ with component vectors $\rm{R}_{\Tf}$ and $\dofs{B}{T}{s}$, respectively.

\paragraph{Stabilization blocks.} The fluid stabilization blocks $\stabdiag{f}{T} \in \bbm{R}^{N_{\Tf}^{k^\prime} \times N_{\Tf}^{k^\prime}}$, $\stab{f}{T}{F} \in \bbm{R}^{N_{\Tf}^{k^\prime} \times N_{\Ff}^{k}}$, and $\stabdiag{f}{F} \in \bbm{R}^{N_{\Ff}^{k} \times N_{\Ff}^{k}}$ and the solid stabilization blocks $\stabdiag{s}{T} \in \bbm{R}^{L_{\Ts}^{k^\prime} \times L_{\Ts}^{k^\prime}}$, $\stab{s}{T}{F} \in \bbm{R}^{L_{\Ts}^{k^\prime} \times L_{\Fs}^{k}}$, and $\stabdiag{s}{F} \in \bbm{R}^{L_{\Fs}^{k} \times L_{\Fs}^{k}}$ are defined so that they satisfy \ifHAL \else \\ \fi
\begin{subequations}\label{stab}
\begin{align}
\label{stab_a}
(\stabdiag{f}{T}\dofs{\rm{P}}{T}{f} + \stab{f}{T}{F} \dofs{\rm{P}}{F}{f})^\dagger \dofs{\rm{Q}}{T}{f} &+ (\stab{f}{T}{F}^{\dagger}\dofs{\rm{P}}{T}{f} + \stabdiag{f}{F}\dofs{\rm{P}}{F}{f})^\dagger \dofs{\rm{Q}}{F}{f} \notag \\
& = \sum_{T \in \Tf} \tau^\sc{f}_{T} (S_{\partial T}(p_T,p_{\partial T}), S_{\partial T}(q_T,q_{\partial T}))_{L^2(\partial T)}, \\
(\stabdiag{s}{T}\dofs{\rm{V}}{T}{s} + \stab{s}{T}{F}
\dofs{\rm{V}}{T}{s})^\dagger \dofs{\rm{W}}{T}{s} &+ (\stab{s}{T}{F}^{\dagger}\dofs{\rm{V}}{T}{s} + \stabdiag{s}{F}\dofs{\rm{V}}{F}{s})^\dagger \dofs{\rm{W}}{F}{s} \notag \\
& = \sum_{T \in \Ts} \tau^\sc{s}_{T} (\bd{S}_{\partial T}(\bd{v}_T,\bd{v}_{\partial T}), \bd{S}_{\partial T}(\bd{w}_T,\bd{w}_{\partial T}))_{\bd{L}^2(\partial T)},
\label{stab_e}
\end{align}
\end{subequations}    
for all $(p_{\Tf},p_{\Ff}) \in P^{k^\prime}(\Tf) \times P^{k}(\Ff)$ and all $(\bd{v}_{\Ts},\bd{v}_{\Fs}) \in \bd{V}^{k^\prime}(\Ts) \times \bd{V}^{k}(\Fs)$ with component vectors $\dofs{P}{T}{f}$, $\dofs{P}{F}{f}$ and $\dofs{V}{T}{s}$, $\dofs{V}{F}{s}$, respectively, and for all $(q_{\Tf}, q_{\Ff}) \in P^{k^\prime}(\Tf) \times P^{k}(\Ff)$ and all $(\bd{w}_{\Ts}, \bd{w}_{\Fs}) \in \bd{V}^{k^\prime}(\Ts) \times \bd{V}^{k}(\Fs)$ with component vectors $\rm{Q}_{\Tf}$, $\rm{Q}_{\F^\sc{f}}$ and $\rm{W}_{\Ts}$, $\rm{W}_{\Fs}$, respectively. The stabilization parameters are defined as follows:
\begin{equation}
\tau^\sc{f}_{T} := (\rho^\sc{f}c_\sc{p}^\sc{f})|_T^{-1}\tih_T^{-\alpha}, \qquad \tau^\sc{s}_{T} := (\rho^\sc{s}c^\sc{s})|_T \tih_T^{-\alpha},
\end{equation}
where the local scaling by $(\rho^\sc{f}c_\sc{p}^\sc{f})|_T^{-1}$ and $(\rho^\sc{s}c^\sc{s})|_T$ follows from physical consistency, the parameter $\alpha \in \{0,1\}$ is used to shift from $\cal{O}(1)$-stabilization ($\alpha=0$) to $\cal{O}(\frac{1}{h})$-stabilization ($\alpha=1$), and $\tih_T := \frac{h_T}{\ell_\Omega}$ is a normalized cell diameter, where the global length scale $\ell_\Omega := \text{diam}(\Omega)$ is introduced for dimensional consistency.

Regarding the local stabilization operators $S_{\partial T} : P^{k'}(T) \times P^k(\F_{\partial T}) \rightarrow P^k(\F_{\partial T})$ and $\bd{S}_{\partial T} : \bd{P}^{k'}(T) \times \bd{P}^k(\F_{\partial T}) \rightarrow \bd{P}^k(\F_{\partial T})$, we consider two configurations:
\begin{itemize}
\item The first one, which we use in the equal-order HHO discretization ($k' = k$), corresponds to a plain Least-Squares stabilization:
\begin{equation}
S_{\partial T}(p_T, p_{\partial T}) := p_T|_{\partial T} - p_{\partial T}, \qquad \bd{S}_{\partial T}(\bd{v}_T, \bd{v}_{\partial T}) := \bd{v}_T|_{\partial T} - \bd{v}_{\partial T}.
\end{equation}
This stabilization will be used with the scaling $\alpha = 0$ and explicit time-stepping schemes.
\item The second one, which we use in the mixed-order HHO discretization ($k' = k+1$), corresponds to the Lehrenfeld--Schöberl stabilization \cite{LEHRENFELD_2010}:
\begin{equation}
S_{\partial T}(p_T, p_{\partial T}) := \Pi_{\partial T}^k(p_T|_{\partial T}) - p_{\partial T}, \qquad \bd{S}_{\partial T}(\bd{v}_T, \bd{v}_{\partial T}) := \Pi_{\partial T}^k(\bd{v}_T|_{\partial T}) - \bd{v}_{\partial T},
\end{equation}
where $\Pi_{\partial T}^k$ is the local $L^2(\partial T)$-orthogonal projection onto $P^{k}(\cF_{\partial T})$. This stabilization will be used with the scaling $\alpha = 1$ and implicit time-stepping schemes.
\end{itemize}    

\paragraph{Coupling blocks.} The matrix $\coupling{} \in \bbm{R}^{N_{\Ff}^{k} \times L_{\Fs}^{k}}$ representing the coupling terms is defined so that 
\begin{equation}
\rm{Q}_{\F^\sc{f}}^\dagger \coupling{} \dofs{V}{F}{s} = (\bd{v}_{\Fs} {\cdot} \bd{n}_\Gamma, q_{\cal{F}^\sc{f}})_{{L^2(\Gamma)}},
\end{equation}
for all $q_{\cal{F}^\sc{f}} \in P^{k}(\Ff)$ with component vector $\rm{Q}_{\F^\sc{f}} \in \bbm{R}^{N_{\Ff}^{k}}$ and all $\bd{v}_{\Fs} \in \bd{P}^k(\cal{\Fs})$ with component vector $\dofs{\rm{V}}{F}{s} \in \bbm{R}^{L_{\Fs}^{k}}$. Notice that $\coupling{}$ is block-diagonal with a nonzero block only for all $F \in \cal{F}^{\Gamma}$.

\paragraph{Source terms.} The source terms $\dofs{F}{T}{f}(t) \in \bbm{R}^{N_{\Tf}^{k^\prime}}$ and $\dofs{F}{T}{s}(t) \in \bbm{R}^{L_{\Ts}^{k^\prime}}$ are time-dependent and correspond to the algebraic realization of the linear forms
\begin{subequations} \label{rhs}
\begin{alignat}{4}
& \dofs{F}{T}{f}^{\dagger}(t) \mass{}{f} \dofs{Q}{T}{f} && = \sum_{T \in \Tf} (f^\textsc{f}(t), q)_{L^2(T)}, \\
& \dofs{F}{T}{s}^{\dagger}(t) \mass{}{s} \dofs{W}{T}{s} && = \sum_{T \in \Ts} (\bd{f}^\textsc{s}(t), \bd{w})_{\bd{L}^2(T)},
\end{alignat}
\end{subequations}
for all $q \in P^{k^\prime}(\Tf)$ and all $\bd{w} \in \bd{P}^{k^\prime}(\Ts)$ with component vectors $\dofs{Q}{T}{f}$ and $\dofs{W}{T}{s}$, respectively, and $\mass{}{f}$ and $\mass{}{s}$ are the mass matrices associated with the canonical inner products in $L^2(\Omega^\sc{f})$ and $\bd{L}^2(\Omega^\sc{s})$, respectively.

Equation \eqref{algebraic_system} can be rewritten in a more compact form by regrouping all the cell unknowns on the one hand, and all the face unknowns on the other hand. With obvious notation, we obtain
\begin{equation}
\pmatset{4}{12pt} 
\pmatset{5}{12pt}
\begin{pmat}[{}]
\normalizecell{\mass{}{}} & 0 \cr
0 & 0  \cr 
\end{pmat}
\partial_t
\begin{pmat}[{}]
\rm{U}_\T \cr
\rm{U}_\F  \cr 
\end{pmat} + 
\pmatset{4}{12pt} 
\pmatset{5}{12pt}
\begin{pmat}[{}]
\normalizecell{\cal{K}_{\cal{T}}} & \normalizecell{\cal{K}_{\cal{TF}}} \cr
\normalizecell{{\cal{K}_{\cal{FT}}}} & \normalizecell{\cal{K}_{\cal{F}}}  \cr 
\end{pmat}
\begin{pmat}[{}]
\rm{U}_\T \cr
\rm{U}_\F  \cr 
\end{pmat} = 
\begin{pmat}[{}]
\rm{F}_\T \cr
0  \cr 
\end{pmat},
\label{compact_AR}
\end{equation}
where $\mass{}{}$ is the cell mass matrix, $\cal{K}_{\T}$, $\cal{K}_{\T\F}$, $\cal{K}_{\F\T}$, $\cal{K}_{\F}$, are the blocks of the stiffness matrix, $\rm{U}_\T$ and $\rm{U}_\F$ are the components of the vector of unknowns and $\rm{F}_\T$ is the cell source term (the face source term is null). A crucial observation is that both $\cal{K}_{\T}$ and $\cal{K}_{\F}$ are block diagonal. This important property will be exploited in Section 4 in the context of implicit and explicit time-stepping schemes. While the block-diagonal structure of $\cal{K}_\T$ is obvious, let us briefly motivate why $\cal{K}_\F$ is also block-diagonal. First, this is the case for all $F \in \F^{\circ \sc{f}} \cup \F^{\circ \sc{s}}$ since the stabilization bilinear forms are local to each interior face for both fluid and solid subdomains, with local diagonal blocks of size $\dim{P^k(F)}$ or $\dim{\bd{P}^k(F)}$, respectively. Furthermore, for all $F \in \F^{\G}$, the couplings are also local to the face, but the diagonal block in $\cal{K}_\F$ is of larger size, namely $\dim{P^k(F)} + \dim{\bd{P}^k(F)}$.

\section{Fully discrete schemes}

The time discretization is based on Runge--Kutta (RK) schemes. Butcher tableaux are a classical way to define RK schemes by means of the coefficients $\left\{a_{ij}\right\}_{1 \leq i, j \leq s}$, $\left\{b_i\right\}_{1 \leq i \leq s}$, and $\left\{c_i\right\}_{1 \leq i \leq s}$, where $s \geq 1$ is the number of stages. For explicit RK schemes with $s$ stages and order $s$ (ERK$(s)$), the matrix $\left\{a_{ij}\right\}_{1 \leq i, j \leq s}$ is strictly lower-triangular. For singly diagonal implicit RK schemes with $s$ stages and order $(s+1)$ (SDIRK$(s,s+1)$), the matrix is lower-triangular with $a_{11} = \ldots = a_{ss} := a_*$. The corresponding Butcher tableaux are as follows:
\begin{equation}
\renewcommand{\arraystretch}{1.3}
\begin{tabular}{c|cccc}
$c_1$ & $a_*$ & $0$ & $\cdots$ & $0$ \\
$c_2$ & $a_{21}$ & $a_*$ & $\ddots$ & $0$ \\
$\vdots$ & $\vdots$ & $\ddots$ & $\ddots$ & $\vdots$ \\
$c_s$ & $a_{s1}$ & $\cdots$ & $a_{s,s-1}$ & $a_*$ \\
\hline
& $b_1$ & $\cdots$ & $b_{s-1}$ & $b_s$
\end{tabular}
\hspace*{2cm}
\begin{tabular}{c|cccc}
$c_1$ & $0$ & $\cdots$ & $\cdots$ & $0$ \\
$c_2$ & $a_{21}$ & $0$ & $\cdots$ & $0$ \\
$\vdots$ & $\vdots$ & $\ddots$ & $\ddots$ & $\vdots$ \\
$c_s$ & $a_{s1}$ & $\cdots$ & $a_{s,s-1}$ & $0$ \\
\hline
& $b_1$ & $\cdots$ & $b_{s-1}$ & $b_s$
\end{tabular}
\end{equation}
To simplify the writing of SDIRK and ERK schemes, we define $a_{s+1,i} := b_i$ for all $i \in \{1,...,s\}$ and set $a_{s+1,s+1} := 0$. 

We now detail the time discretization of \eqref{compact_AR} by SDIRK and ERK schemes. We show that an effective SDIRK implementation is obtained by the local elimination of the cell unknowns, whereas an effective ERK implementation is obtained by the local elimination of the face unknowns. The outcome of this elimination is illustrated in \hyperref[fig::sc]{\Cref{fig::sc}}. Let $(t^n)_{n \in \{0,\ldots,N\}}$ with $t^0=0$ and $t^N=T_\rm{f}$ be the discrete time nodes, and let $\Delta t^n:=t^n-t^{n-1}$ be the time step. For simplicity, we consider that the time-step is constant and drop the superscript $n$.
