\begin{ndefinition}
Let $G = (V,T,P,S)$ be a linear core GG.
\begin{enumerate}
    \item For $p\colon A \ra x \in P$, $A\langle x\rangle$ is the \emph{rule tree} that represents $p$.
    \item\label{DT:2} The \emph{derivation trees} representing the derivations in $G$ are defined recursively as follows:
    \begin{enumerate}
        \item One-node tree with a node labeled $X$ is the derivation tree corresponding to $X \Ra^0 X$ in $G$,
              where $X \in V$. If $X = \eps$, we refer to the node  
              labeled $X$ as \emph{$\eps$-node} (\emph{$\eps$-leaf}); otherwise, we call it
              \emph{non-$\eps$-node} (\emph{non-$\eps$-leaf}).
        \item Let $d$ be the derivation tree with $\frontier(d) = uAv$ representing $X \Ra^* uAv\,[\rho]$
              and let $p\colon A \ra x \in P$. The derivation tree that represents
              \[
                X \Ra^* uAv\,[\rho] \Ra uxv\,[p]
              \]
              is obtained by replacing the $i$th non-$\eps$-leaf in $d$ labeled $A$, with the rule tree corresponding to $p$, $A\langle x\rangle$, where $i = |uA|$.
        \item\label{DT:2:3}
              Let $d$ be the derivation tree with $\frontier(d) = uABv$ representing $X \Ra^* uABv\,[\rho]$
              and let $p\colon AB \ra CD \in P$. The derivation tree that represents
              \[
                X \Ra^* uABv\,[\rho] \Ra uCDv\,[p]
              \]
              is obtained by replacing the $i$th and $(i+1)$th non-$\eps$-leaf in $d$ labeled $A$ and $B$
              with $A\langle C\rangle$ and $B\langle D\rangle$, respectively, where $i = |uA|$.
    \end{enumerate}
    \item A \emph{derivation tree} in $G$ is any tree $t$
          for which there is a derivation represented by $t$ (see item \ref{DT:2} in this definition).
\end{enumerate}

Note that the figure to illustrate the definition is postponed to Example \ref{ex:GG}. Moreover, after replacement in \ref{DT:2:3},
the nodes $A$ and $B$ are the parents of the new leaves $C$ and $D$, respectively,
and we say that $A$ and $B$ are \emph{context-dependent}, alternatively speaking, we say
that there is a context dependency between $A$ and $B$.
In a derivation tree, two nodes are \emph{context-independent} if they are not context-dependent.

Then, for any $p\colon A \ra x \in P$, $\prescript{}{G}\triangle(p)$ denotes the rule tree corresponding to $p$.
For any $A \Ra^* x\,[\rho]$ in $G$, where $A \in V-T$, $x \in V^*$, and $\rho \in P^*$,
$\prescript{}{G}\triangle(A \Ra^* x\,[\rho])$ denotes one of the derivation trees corresponding to $A \Ra^* x\,[\rho]$.
Just like we often write $A \Ra^* x$ instead of $A \Ra^* x\,[\rho]$, we sometimes simplify
$\prescript{}{G}\triangle(A \Ra^* x\,[\rho])$ to $\prescript{}{G}\triangle(A \Ra^* x)$ in what follows
if there is no danger of confusion.
Let $\prescript{}{G}\blacktriangle$ denote the set of all derivation trees in $G$.
Finally, by $\prescript{}{G}\triangle_x \in \prescript{}{G}\blacktriangle$,
we mean a derivation tree whose frontier is $x$, where $x \in L(G)$.

If a node is labeled with a terminal, it is called a \emph{terminal node}.
If a node is labeled with a nonterminal, it is called a \emph{nonterminal node}.
Analogously, we define the notions of a \emph{terminal child}, \emph{nonterminal child},
\emph{terminal sibling}, \emph{nonterminal sibling}. 
If a node is labeled with a nonterminal and has two \emph{nonterminal node} children, it is called a \emph{branching nonterminal node}.
Let $\alpha = (o,m_1,m_2,\dots,m_r)$ and $\beta = (o,n_1,n_2,\dots,n_s)$ be two neighboring paths,
where $r,s \geq 0$, $\alpha$ is the left neighboring path to $\beta$, and $m_r$ and $n_s$ are terminal nodes.
Then, there is a $t$-tuple $\gamma = (g_1,g_2,\dots,g_t)$ of nodes from $\alpha$
and $t$-tuple $\delta = (h_1,h_2,\dots,h_t)$ of nodes from $\beta$,
where $g_p < g_q$, for $1 \leq p < q \leq t$, $t < \min(r,s)$,
and $g_i$ and $h_i$ are context-dependent, for $1 \leq i \leq t$.
Let $\rho = p_1p_2\dots p_t$ be a string of non-context-free rules
corresponding to context dependencies between $\gamma$ and $\delta$.
We call $\rho$ the \emph{right context of $\alpha$} and the \emph{left context of $\beta$} or
the \emph{context of $\alpha$ and $\beta$}.
Consider a node $m_i \in \alpha$, where $1 \leq i \leq r$,
and two $(t-k+1)$-tuples of nodes $\sigma = (g_{k}, g_{k+1},\dots, g_t)$ and $\phi = (h_{k}, h_{k+1},\dots, h_t)$,
where $k$ is a minimal integer such that $m_i < g_{k}$.
Then, a string of non-context-free rules $\tau = p_kp_{k+1}\dots p_t$
corresponding to context dependencies between $\sigma$ and $\phi$
is called the \emph{right descendant context of $m_i$}, for some $1 \leq k \leq t$.
Analogously, we define the notion of the \emph{left descendant context} of a node $n_j$ in $\beta$,
for some $1 \leq j \leq s$.
\end{ndefinition}


\begin{ndefinition}
A labeled ordered tree $t$ is \emph{slow-branching} if any of its pairs of nonterminal neighboring paths
contains no more than two nonterminal nodes having two nonterminal children
and there is no reachable terminal node from nodes of the path between the root and any branching nonterminal node. 
A slow-branching labeled ordered tree is of \emph{degree $k$}
if it contains $k$ branching nonterminal nodes, $k \geq 1$.
\end{ndefinition}





