\section{Results}

\begin{theorem}
\label{th:L:kL}
A language $L$ is $k$-linear iff there is a constant $k \geq 0$, constant $u \geq 0$ and a linear core general grammar $G$
such that $L = L(G)$
and for every $x \in L(G)$, there is a slow-branching tree of degree~$k$ denoted by
$\prescript{}{G}\triangle_x \in \prescript{}{G}\blacktriangle$ that both following satisfies:
\begin{enumerate}
    \item\label{th:L:kL:1} any two nonterminal neighboring paths contain
                           no more than $u$ pairs of context-dependent nodes;
    \item\label{th:L:kL:2} all pairs of nodes occurring in non-neighboring paths are context-independent.
\end{enumerate}
\end{theorem}


\begin{proof}\emph{Construction.}
Consider any $u \geq 0$. Let $G = (V,T,P,S)$ be a GG such that $L(G) = L$.
Set $N = V - T$. Let $P_{cs} \subseteq P$ denote the set of all non-context-free rules of $G$.
Set
\[
    N' = \{ A_{l|r} \where A \in N,\ l,r \in (P_{cs} \cup \{\eps\})^u\}.
\]
Construct a grammar $G' = (V',T,P',S_{\eps|\eps})$, where $V' = N' \cup T$.
Set $P' = \emptyset$. Construct $P'$ by performing (\ref{construction:1}) through (\ref{construction:3}) given next.
\begin{enumerate}[(I)]
    \item\label{construction:1} For all $A \ra xEy \in P$, $A \in N$, $E \in N \cup \{\eps\}$, $x,y \in T^*$, and $l,r \in (P_{cs} \cup \{\eps\})^u$,
                                if $E \in \{\eps\}$ then add $A_{\eps|\eps} \ra xy$ to~$P'$ else add $A_{l|r} \ra xE_{l|r}y$ to~$P'$;
    \item\label{construction:2} for all $A \ra BC \in P$, where $A,B,C \in N$,
                                and $r,l,x \in (P_{cs} \cup \{\eps\})^u$,
                                add $A_{l|r} \ra B_{l|x}C_{x|r}$ to $P'$;
    \item\label{construction:3} for all $p\colon AB \ra CD \in P$, $A,B,C,D \in N$,
                                $x,z \in (P_{cs} \cup \{\eps\})^u$,
                                and $y \in (P_{cs} \cup \{\eps\})^{u-1}$,
                                add $A_{x|py} \ra C_{x|y}$ and $B_{py|z} \ra D_{y|z}$ to $P'$.
\end{enumerate}

\noindent
\emph{Basic idea.} Notice nonterminal symbols.
Since every pair of neighboring paths of $G$ contains a limited number of context-dependent nodes,
all of its context-dependencies are encoded in nonterminals.
$G'$ nondeterministically decides about all context-dependencies
while introducing a new pair of neighboring paths by rules from~(\ref{construction:2}).
A new pair of neighboring paths is introduced with every application~of
\[
    A_{l|r} \ra B_{l|x}C_{x|r},
\]
where $x$ encodes a new descendant context.
Context dependencies are realized later by context-free rules from~(\ref{construction:3}).

\vspace{1em}
\noindent

Since $P'$ contains no non-context-free rule and $G'$ is context-free.
Next, we prove $L(G) = L(G')$ by establishing Claims \ref{GG:sub:kL} through \ref{GG:sup:kL}.
Define the new homomorphism $\gamma: V' \ra V$, $\gamma(A_{l|r}) = A$,
for $A_{l|r} \in N'$, and $\gamma(a) = a$ otherwise.

\begin{nclaim}
\label{GG:sub:kL}
If $S \Ra^m w$ in $G$, where $m \geq 0$ and $w \in V^*$, then $S_{\eps|\eps} \Ra^* w'$ in $G'$,
where $w' \in V'^*$ and $\gamma(w') = w$.
\end{nclaim}


\begin{proof}
We prove this by induction on $m \geq 0$.

\ibasis
Let $m = 0$. That is $S \Ra^0 S$ in $G$.
Clearly, $S_{\eps|\eps} \Ra^0 S_{\eps|\eps}$ in $G'$, where $\gamma(S_{\eps|\eps}) = S$, so the basis holds.

\ihypothesis
Suppose that there exists $n \geq 0$ such that Claim \ref{GG:sub:kL} holds for~all $0 \leq m \leq n$.

\istep
Let $S \Ra^{n+1} w$ in $G$. Then, $S \Ra^n v \Ra w$,
where $v \in V^*$, and there exists $p \in P$ such that $v \Ra w\,[p]$.
By the induction hypothesis, $S_{\eps|\eps} \Ra^* v'$, where $\gamma(v') = v$, in $G'$.
Next, we consider the following three forms of $p$.

\begin{enumerate}[(I)]
    \item Let $p\colon A \ra xEy \in P$, for some $A \in N$ , $E \in N \cup \{\eps\}$, $x,y \in T^* $.

          If there is no nonterminal on the right-hand side of the rule, it implies that left descendant context and a right descendant context of $A$ is $\eps$, then, by the construction of $G'$, there exists a rule $p'\colon A_{\eps|\eps} \ra xy \in P'$, where $A_{\eps|\eps}  \in v'$.
          Otherwise, suppose $l$ and $r$ are
          a left descendant context and a right descendant context of $A$.
          By the construction of $G'$, there exists a rule $p'\colon A_{l|r} \ra xE_{l|r}y \in P'$, where $A_{l|r}  \in v'$.
          Then, there exists a derivation $v' \Ra w'\,[p']$ in $G'$, where $\gamma(w') =~w$.



    \item Let $p\colon A \ra BC \in P$, for some $A,B,C \in N$.
          Without any loss of generality, suppose $l$ and $r$ are
          a left descendant context and a right descendant context of $A$,
          and $x \in (P_{cs} \cup \{\eps\})^u$ is a context of neighboring paths beginning at this node.
          By the construction of $G'$, there exists a rule $p'\colon A_{l|r} \ra B_{l|x}C_{x|r} \in P'$, where $A_{l|r}, B_{l|x}, C_{x|r} \in v'$.
          Then, there exists a derivation $v' \Ra w'\,[p']$ in $G'$, where $\gamma(w') = w$.

    \item\label{claim:1:phase:case:4} Let $p\colon AB \ra CD \in P$, for some $A,B,C,D \in N$.
          By the assumption stated in Theorem \ref{th:L:kL},
          $A$ and $B$ occur in two neighboring paths denoted by $\alpha$ and $\beta$, respectively.
          Without any loss of generality, suppose that a context of $\alpha$ and $\beta$
          is a string $c \in (P_{cs} \cup \eps)^u$, where $c = pcd$,
          and $l$ is a left descendant context, $r$ is a right descendant context of $A$, $B$, respectively.
          By the construction of $G'$, there exist two rules
          \[
              p'_l\colon A_{l|pcd} \ra C_{l|cd},\ \ p'_r\colon B_{pcd|r} \ra D_{cd|r} \in P',
          \]
          where $A_{l|pcd}, C_{l|cd}, B_{pcd|r}, D_{cd|r} \in V'$.
          Then, there exists a derivation $v' \Ra^2 w'\,[p'_lp'_r]$ in $G'$, where $\gamma(w') = w$.
\end{enumerate}

\noindent
Notice (\ref{claim:1:phase:case:4}). The preservation of the context is achieved by nonterminal symbols.
Since the stored context is reduced symbol by symbol from left to right direction
in both $\alpha$ and $\beta$, $G'$ simulates the applications of non-context-free rules of~$G$.

We covered all possible forms of $p$, so the claim holds.
\end{proof}
\begin{nclaim}
\label{pre:GG:sup:kL}
Every $x \in L(G')$ can be derived in $G'$ as follows.
\[
    S_{\eps|\eps} = x_0 \Ra^{d_1} x_1 \Ra^{d_2} x_2 \Ra^{d_3} \cdots \Ra^{d_{h-1}} x_{h-1} \Ra^{d_h} x_{h} = x,
\]
for some $h \geq 0$, where $d_i \in \{1,2\}$, $1 \leq i \leq h$, so that
\begin{enumerate}
    \item if $d_i = 1$, then $x_{i-1} = uA_{l|r}v$, $x_i = uzv$, $x_{i-1} \Ra x_i\ [A_{l|r} \ra z]$,
          where $u,v \in V'^*$,\\ $z \in \{E_{l|r},B_{l|r},C_{l|x}D_{x|r},x,y\}$,
          for some $A_{l|r},B_{l|r},C_{l|x},D_{x|r} \in  N'$, $E_{l|r} \in (N' \cup \{\varepsilon\})$,
                $x,y \in T^*$;\vspace{1em}
    \item if $d_i = 2$, then $x_{i-1} = uA_{x|py}B_{py|z}v$, $x_i = uC_{x|y}D_{y|z}v$, and
        \[
          uA_{x|py}B_{py|z}v \Ra uC_{x|y}B_{py|z}v\ [A_{x|py} \ra C_{x|y}]
          \Ra uC_{x|y}D_{y|z}v\ [B_{py|z} \ra D_{y|z}],
        \]
          for some $u,v \in V'^*$ and $A_{x|py},B_{py|z},C_{x|y},D_{y|z} \in N'$.
\end{enumerate}
\end{nclaim}

\begin{proof}
Since $G'$ is context-free, without any loss of generality in every derivation of $G'$
we can always reorder applied rules to satisfy Claim \ref{pre:GG:sup:kL}.
%
\end{proof}

\begin{nclaim}
\label{GG:sup:kL}
Let $S_{\eps|\eps} \Ra^{d_1} x_1 \Ra^{d_2} \cdots \Ra^{d_{m-1}} x_{m-1} \Ra^{d_m} x_{m}$
in $G'$ be a derivation that satisfies Claim \ref{pre:GG:sup:kL}, for some $m \geq 0$.
Then, $S \Ra^* w$ in $G$, where $\gamma(x_m) = w$.
\end{nclaim}

\begin{proof}
We prove this by induction on $m \geq 0$.

\ibasis
Let $m = 0$. That is $S_{\eps|\eps} \Ra^0 S_{\eps|\eps}$ in $G'$.
Clearly, $S \Ra^0 S$ in $G$. Since $\gamma(S_{\eps|\eps}) = S$, the basis holds.

\ihypothesis
Suppose that there exists $n \geq 0$ such that Claim \ref{GG:sup:kL} holds for~all $0 \leq m \leq n$.

\istep
Let $S_{\eps|\eps} \Ra^{d_1} x_1 \Ra^{d_2} \cdots \Ra^{d_{n-1}} x_{n-1} \Ra^{d_n} x_{n} \Ra^{d_{n+1}} x_{n+1}$ in $G'$
be a derivation that satisfies Claim \ref{pre:GG:sup:kL}.
By the induction hypothesis, $S \Ra^* v$, $v \in V^*$, where $\gamma(x_{n}) = v$, in $G$.
Divide the proof into two parts according to~$d_{n+1}$.

\begin{enumerate}[(A)]
    \item Let $d_{n+1} = 1$. By the construction of $G'$,
          there exists a rule $p' \in P'$ such that $x_{n} \Ra^{d_{n+1}} x_{n+1}\,[p']$.
          Next, we consider the following two forms of~$p'$.
          \vspace{1em}
          \begin{enumerate}[(I)]
              \item Let $p'\colon A_{l|r} \ra xE_{l|r}y$ or $p'\colon  A_{\eps|\eps} \ra xy  \in P'$,
                    for some $A \in N$, $E \in N$, $x,y \in T^*$ and $l,r \in (P_{cs} \cup \{\eps\})^u$.
                    By the construction of $G'$, rule $p'$ was introduced by some rule $p\colon A \ra xEy \in P$ or $p\colon A \ra xy \in P$, respectively.
                    Then, there exists a derivation $v \Ra w\,[p]$, where $\gamma(x_{n+1}) = w$.

              \item Let $p'\colon A_{l|r} \ra B_{l|x}C_{x|r} \in P'$,
                    for some $A,B,C \in N$ and $l,r,x \in (P_{cs} \cup \{\eps\})^u$.
                    By the construction of $G'$, rule $p'$ was introduced by some rule $p\colon A \ra BC \in P$.
                    Then, there exists a derivation $v \Ra w\,[p]$, where $\gamma(x_{n+1}) = w$.
          \end{enumerate}
          \vspace{1em}
    \item Let $d_{n+1} = 2$. Then, $x_{n} \Ra^{d_{n+1}} x_{n+1}$ is equivalent to
          \[
              u_1A_{x|py}B_{py|z}u_2 \Ra u_1C_{x|y}B_{py|z}u_2\ [p'_1] \Ra u_1C_{x|y}D_{y|z}u_2\ [p'_2],
          \]
          where $x_{n} = u_1A_{x|py}B_{py|z}u_2$, $x_{n+1} = u_1C_{x|y}D_{y|z}u_2$, and
          \[
              p'_1\colon A_{x|py} \ra C_{x|y},\ p'_2\colon B_{py|z} \ra D_{y|z} \in P',
          \]
          for some $u_1,u_2 \in V'^*$ and $A_{x|py}$, $B_{py|z}$, $C_{x|y}$, $D_{y|z} \in N'$.
          By the construction of $G'$, rules $p'_1$ and $p'_2$ were introduced by some rule $p\colon AB \ra CD \in P$,
          Then, there exists a derivation $v \Ra w\,[p]$, where $\gamma(x_{n+1}) = w$.
\end{enumerate}

We covered all possibilities, so the claim holds.
%
\end{proof}


Observe that respective the derivation trees of the constructed context-free $G'$ remain slow-branching.

\begin{nclaim}
\label{GG:kLin}
The grammar $G'$ is $k$-linear.
\end{nclaim}

\begin{proof}
In construction (\ref{construction:3}) we replace the rules of the form $AB \ra CD$ with the rules of the form $A \ra B$, where $A,B,C,D \in N$.
Therefore, only the rules that are allowed to occur in the derivation $G'$ before the rules of the form $A \ra BC$ are the rules of the form $A \ra B$.
Rules of the form $A \ra B$  before the rules of the form $A \ra BC$ can be omitted by the trivial transformation of $G'$, similar to the algorithm on elimination of unit productions from Section 5 in \cite{Med20}.
Therefore, the grammar $G'$ is $k$-linear.
%TODO
\end{proof}

By Claim \ref{GG:kLin} $G'$ is $k$-linear.
By Claims \ref{GG:sub:kL} and \ref{GG:sup:kL},
$S \Ra^* w$ in $G$ iff $S_{\eps|\eps} \Ra^* w'$ in $G'$, where $\gamma(w') = w$.
If $S \Ra^* w$ in $G$ and $w \in T^*$, then $w \in L(G)$.
Since $\gamma(w') = w' = w$, for $w \in T^*$, $w' \in L(G')$.
Therefore, $L(G) = L(G')$ and Theorem \ref{th:L:kL} hold.
%
\end{proof}

Consider Theorem \ref{th:L:kL}. Observe that the \ref{th:L:kL:2}nd condition is superfluous whenever $G$ is propagating.

\begin{theorem}
\label{th:L:kL:P}
A language $L$ is $k$-linear iff there is a constant $k \geq 0$, constant $u \geq 0$ and a propagating linear core general grammar $G$
such that $L = L(G)$ and for every $x \in L(G)$,
there is a slow-branching tree of degree $k$ $\triangle_x \in \prescript{}{G}\blacktriangle$,
where any two nonterminal neighboring paths contain no more than $u$ pairs of context-dependent nodes.
\end{theorem}

\begin{proof}
Prove this by analogy with the proof of Theorem \ref{th:L:kL}.
%
\end{proof}

\begin{theorem}
\label{th:L:R}
A language $L$ is regular iff there is a constant $u \geq 0$ and a left linear core general grammar $G$ such that $L = L(G)$
and for every $x \in L(G)$, there is a tree 
$\triangle_x \in \prescript{}{G}\blacktriangle$ that satisfies:
\begin{enumerate}
    \item\label{th:L:R:1} any two nonterminal neighboring paths contain
                           no more than $u$ pairs of context-dependent nodes;
    \item\label{th:L:R:2} out of neighboring paths, any pair of nodes is context-independent.
\end{enumerate}
\end{theorem}

\begin{proof}
Prove this by analogy with the proof of Theorem \ref{th:L:kL}.
%
\end{proof}

\begin{theorem}
\label{th:L:R:P}
A language $L$ is regular iff there is a constant $u \geq 0$ and a propagating left linear core general grammar $G$
such that $L = L(G)$ and for every $x \in L(G)$,
there is a tree $\triangle_x \in \prescript{}{G}\blacktriangle$,
where any two nonterminal neighboring paths contain no more than $u$ pairs of context-dependent nodes.
\end{theorem}

\begin{proof}
Prove this by analogy with the proof of Theorem \ref{th:L:kL}.
\end{proof}


\section{Use}

In this section, we explain how to apply the results achieved in the previous section in order to demonstrate the metalinearness (or regularity) of a language, $L$. As a rule, this demonstration follows the next three-step proof scheme for metalinearness.

\begin{enumerate}
    \item Construct a linear core GG $G$.
    \item Prove $L(G) = L$.
    \item Prove that $G$ satisfies conditions from Theorem \ref{th:L:kL:2} or Theorem \ref{th:L:kL} depending on whether $G$ is context-sensitive.
\end{enumerate}

For regularity, we use a similar three-step scheme as following.

\begin{enumerate}
    \item Construct a left linear core GG $G$.
    \item Prove $L(G) = L$.
    \item Prove that $G$ satisfies conditions from Theorem \ref{th:L:R} or Theorem \ref{th:L:R:P} depending on whether $G$ is context-sensitive.
\end{enumerate}

Reconsider the grammar $G$ from Example \ref{ex:GG}. Following the proof scheme sketched above,  we next prove that $L(G)$ is $k$-linear.
Without any loss of generality, every terminal derivation of $G$ can be divided into the following 5 phases,
where each rule may be used only in a specific phase:

\noindent
\begin{center}
\begin{inparaenum}[(a)]
    \item\label{phase:a} \ref{rule:1}--\ref{rule:4}
    \item\label{phase:b} \ref{rule:5}--\ref{rule:9}
    \item\label{phase:c} \ref{rule:10}--\ref{rule:12}
    \item\label{phase:d} \ref{rule:13}--\ref{rule:17}
    \item\label{phase:e} \ref{rule:18}--\ref{rule:22}
\end{inparaenum}
\end{center}

Next, we describe these phases in greater detail. 

\begin{enumerate}[(a)]
    \item First, we generate the following string by rules \ref{rule:1} though  \ref{rule:4}.
          \[
            A_1A_2BC_1C_2
          \]
          Possibly applicable rules from (\ref{phase:b}) and (\ref{phase:c}) may be postponed to the next phases without affecting the derivation, since the rules in the previous phases cannot rewrite the nonterminals of the following phases.
          \vspace{1em}
    \item The rules (\ref{rule:5}) through (\ref{rule:9}) are context-free rules and nonterminals on the left-hand side of the rule are the same as on the right-hand side of the rule. Therefore, they are grouped into (\ref{phase:b}), since they only generate terminals. Possibly applicable rules from (\ref{phase:c}) may be postponed for the phase (\ref{phase:c})
          without affecting the derivation since the rules in the previous phases cannot rewrite nonterminals from the following phases.
          \[
            a^*A_1A_2a^*b^*Bc^*a^*C_1C_2b^*.
          \]
    \item The rules \ref{rule:10} and \ref{rule:12} are non context-free rules. The rules \ref{rule:10} through \ref{rule:12} are all rules without generating terminals. For the same reason as in (\ref{phase:a}) rules \ref{rule:1} to \ref{rule:4} from the phases (\ref{phase:d}) and (\ref{phase:e}) can be postponed to respective phases.
          \[
            a^*D_1D_2a^*b^*Ec^*a^*F_1F_2b^*.
          \]
    \item The rules \ref{rule:13} through \ref{rule:17} are alike rules in (\ref{phase:b})
          \[
            a^*0^*D_1D_21^*a^*b^*0^*E1^*c^*a^*0^*F_1F_21^*b^*.
          \]
    \item Since rules \ref{rule:18} and \ref{rule:22} are erasing rules and
          they can always be postponed until the end of any successful derivation.
          \[
            a^*0^*1^*a^*b^*0^*1^*c^*a^*0^*1^*b^*.
          \]
\end{enumerate}




Grammar $G$ is obviously a linear core GG.

Only rules in the step (\ref{phase:a}) include branching of nonterminals, no terminals are generated and the branching in the step (\ref{phase:a}) is a slow-branching since the degree derivation tree is $4$ and, therefore, $u$ is always $4$.
Therefore, the slow-branching condition is fulfilled.

Let us now show that for any $x \in L(G)$, there is $\prescript{}{G}\triangle_x \in \prescript{}{G}\blacktriangle$,
where any two neighboring paths contain no more than a one pair of context-dependent nodes.

Every pair of context-dependent nodes in $\prescript{}{G}\triangle_x$
corresponds to one non-context-free rule in $S \Ra^* x$.
Consider the five phases sketched above. Observe that all phases except (\ref{phase:c})
contain only non context-free rules, so we only have to investigate (\ref{phase:c}).
On the other hand, (\ref{phase:c}) contain no rule of the form $A \ra BC$,
thus the number of neighboring paths remains unchanged.

In (\ref{phase:c})  rule \ref{rule:10} and \ref{rule:12} introduce context dependency between two pairs of neighboring paths. After the application of these two rules, we cannot reach the nonterminals again on the left-hand side of rules \ref{rule:10} and \ref{rule:12}. Therefore, these context-dependencies can occur only once between a pair of neighboring paths.


No other non-context-free rule is applied; therefore, no other context-dependent pair of nodes can occur.
Then, every pair of neighboring paths may contain at most one context-dependent pair of nodes introduced in phase
(\ref{phase:c}).



Since $G$ is a linear core GG, where for every $x \in L(G)$,
there is $\prescript{}{G}\triangle_x \in \prescript{}{G}\blacktriangle$,
where any two neighboring paths contain no more than one pair of context-dependent nodes,
by Theorem \ref{th:L:kL}, $L(G)$ is $k$-linear.

Unfortunately, although we are able to transform any GG into KNF and, that is, linear core GG, the question whether the conditions in Theorems \ref{th:L:kL} through \ref{th:L:R:P} are satisfied is obviously undecidable. To invent an algorithm that gives at least approximate results is part of a future research.


\section{Final Remarks and Open Problems}

Before closing this paper, we bring the reader's attention to an open question. More specifically, consider a more lenient definition of slow-branching tree as follows.

\begin{ndefinition}
\label{def:alt}
A labeled ordered tree $t$ is \emph{slow-branching} if any of its pairs of nonterminal neighboring paths
contains no more than two nonterminal nodes having two nonterminal children. 
A slow-branching labeled ordered tree is of \emph{degree $k$}
if it contains $k$ branching nonterminal nodes, $k \geq 1$.
\end{ndefinition}

It is obvious that the newly provided Definition \ref{def:alt} is insufficient to prove that a grammar restricted by a slow-branching derivation tree is $k$-linear. However, it is possible to apply different restrictions to  Definition \ref{def:alt} with its own advantages or demonstrate similar result to Theorem \ref{th:L:kL} to prove that it is $k$-linear. Such a discovery would require further studies.




