\begin{algorithm}
\begin{algorithmic}[1]
\vspace{0.25cm}
\Require  $\mathcal{I},S,q^-$
\Ensure  $q^*$
\State $\gamma:=$ greatest (positive) slope defined by pairs of points of $S$ that 
 are not vertically aligned \label{line:opt-1}
\If{the decision problem for $q^-+\frac{1}{\gamma}$ has a NO answer}
\State stop and return $q^-$
\Else
