\section{Proof of \textbf{Proposition \ref{prop:ave-channel-gain-SD}}}
\label{proof-prop:ave-channel-gain-SD}
In this section, we derive the average channel gain for the SD scheme in detail. Since the distance between the reference pinching antenna of each waveguide and the UE is random, we assume that  $\phi_k$ follows a uniform distribution of $[0,2\pi]$.
For clarity, let 
\begin{equation}\label{eq:waveguides_channel_vector_sum}
G{e^{ - j\Omega }} = \sum\limits_{k = 1}^K \sqrt{{\frac{1}{{{L_{G,k}^\beta}}}}{e^{ - j{\phi _k}}}}.
\end{equation}

Now, we have that the channel gain can be expressed as follows:
\begin{equation}\label{eq:standaloe_channel_power_Gain_derive}
\begin{gathered}
E\left\{ {{{\left| {{h_S}} \right|}^2}} \right\} = E\left\{ {{{\left| {\sqrt{\frac{\eta {P_{S,B}}}{{L_B^\alpha }}} \left\| {{{{\bm{\tilde h}}}_B}} \right\| + \sqrt {\eta {N_G}{P_{S,G}}} G{e^{ - j\Omega }}} \right|}^2}} \right\} \hfill \\
= E\left\{ {\frac{{\eta {P_{S,B}}}}{{L_B^{\alpha }}}{{\left\| {{{{\bm{\tilde h}}}_B}} \right\|}^2}} \right\} \hfill \\
 + E\left\{\eta \sqrt{\frac{{{P_{S,B}}{N_G}{P_{S,G}}} }{{L_B^\alpha }}} \left\| {{{{\bm{\tilde h}}}_B}} \right\|G\cos \left( \Omega  \right) \right\} \hfill\\
+ E\left\{ {\eta {N_G}{P_{S,B}}{G^2}} \right\}. \hfill  \\
\end{gathered} 
\end{equation}

For the first term of \eqref{eq:standaloe_channel_power_Gain_derive}, it is known that $E\left\{ {{{\left\| {{{{\bm{\tilde h}}}_B}} \right\|}^2}} \right\} = {N_B}$ with ${{{{\bm{\tilde h}}}_B}}$ being the normalized channel coefficient, we have
\begin{equation}\label{eq:standalone_first_term}
E\left\{ {\frac{{\eta {P_{S,B}}}}{{L_B^{\alpha }}}{{\left\| {{{{\bm{\tilde h}}}_B}} \right\|}^2}} \right\} = \frac{{\eta {N_B}{P_{S,B}}}}{{L_B^{\alpha }}}.
\end{equation}

For the second term  of \eqref{eq:standaloe_channel_power_Gain_derive}, we can prove that $\Omega$ follows a uniform distribution over $\left(0,2\pi \right) $, i.e., $\Omega \sim U\left( 0, 2\pi \right) $, as follows. 

\begin{enumerate}

\item  Given $a_1$, $a_2$, and two random variables ${\omega _1}$ and $\omega_2$, which both follow uniform distributions over $\left( 0, 2\pi \right) $, we can define a random variable (RV) $ G_1 {e^{j \Omega_1 }} = {a_1}{e^{j{\omega _1}}} + {a_2}{e^{j{\omega _2}}}$. Then we can define the RV $\hat \Omega_1 = \bmod \left( {{{ \Omega }_1} ,2\pi } \right)$ with support on $\left( {0,2\pi } \right)$. \label{step-1}

\item Based on the properties of vector addition in a two-dimensional plane, we can conclude that the conditional probability density function (CPDF) of $\hat \Omega_1$ depends on the absolute difference between $\hat \Omega_1$ and $\omega_1$, thus its CPDF with $\omega_1$ can be denoted as ${f_{{{\hat \Omega }_1},{\omega _1}}}\left( \Phi  \right) = F \left( {\Delta \Phi } \right)$, where $\Delta \Phi  = \bmod \left( {\Phi  - {\omega _1},2\pi } \right)$.  \label{step-2}

\item Note that for any given $\Phi$, the range of $\Delta \Phi$ is $\left[ 0, 2\pi\right]$ when $\omega_1$ varies in $\left[ 0, 2\pi\right]$. Based on the definition of PDF, we have $\int\limits_0^{2\pi } {F\left( {\Delta \Phi } \right)} d\Phi  = \int\limits_0^{2\pi } {F\left( {\Delta \Phi } \right)} d{\omega _1} = 1$. Since $\omega_1 \sim U\left(0,2\pi\right)$, the PDF of $\hat \Omega_1$ can be given by 
\begin{equation}
\begin{gathered}
  {f_{{{\hat \Omega }_1}}}\left( \Phi  \right) = \int\limits_0^{2\pi } {{f_{{{\hat \Omega }_1},{\omega _1}}}\left( \Phi  \right)\frac{1}{{2\pi }}d{\omega _1}}  \hfill \\
 = \frac{1}{{2\pi }}\int\limits_0^{2\pi } {F \left( {\Delta \Phi } \right)d{\omega _1}} = \frac{1}{{2\pi }}.  \hfill \\ 
\end{gathered} 
\end{equation} 
We thus proved that $\bmod \left( {\Omega_1 ,2\pi } \right)$ follows a uniform distribution over $\left( {0,2\pi } \right)$. \label{step-3}

\item  Set ${ G_k}{e^{j{{ \Omega }_k}}} = { G_{k-1}}{e^{j{{ \Omega }_{k-1}}}} + {a_{k+1}}{e^{j{\omega_{k+1}}}}$ and repeat the above proof in step \ref{step-1} $\sim$ \ref{step-3} for $k=2,\ldots,K-1$. We can prove that ${G_{K - 1}}{e^{j{\Omega _{K - 1}}}} = \sum\nolimits_{k = 1}^K {{a_k}{e^{j{\omega _k}}}} $ follows a uniform distribution over $\left( {0,2\pi } \right)$.  \label{step-4} 

\item Let ${a_k} = \sqrt{\frac{1}{{{L_{G,k}^\beta}}}}$ and ${\omega _k} =  - {\phi _k}$. Combining with \eqref{eq:waveguides_channel_vector_sum}, it is proved that $\Omega$ follows a uniform distribution over $\left( {0,2\pi } \right)$.  \label{step-6}
\end{enumerate}

Therefore, we have that $E\left\{ {\cos \left( \Omega  \right)} \right\}=0$. Furthermore, note that  ${\left\| {{{{\bm{\tilde h}}}_B}} \right\|}$, $G$, and ${\cos \left( \Omega  \right)}$ are uncorrelated, thus the second term of \eqref{eq:standaloe_channel_power_Gain_derive} is zero.

Now we move to the third term of \eqref{eq:standaloe_channel_power_Gain_derive}.  We start by proving the following equation:
\begin{equation}
E\left\{ {{G^2}} \right\} = \sum\nolimits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}}}
\end{equation}
which can be  derived following the below calculations. 
{\small
\begin{align}
&G{e^{ - j\Omega }} = \sum\limits_{k = 1}^K {\sqrt{\frac{1}{{{L_{G,k}^\beta}}}}\cos \left( {{\phi _k}} \right)}  - i\sum\limits_{k = 1}^K {\sqrt{\frac{1}{{{L_{G,k}^\beta}}}}\sin \left( {{\phi _k}} \right)}  \hfill, \\
&{G^2} = {\left( {\sum\limits_{k = 1}^K {\sqrt\frac{1}{{{L_{G,k}^\beta}}}\cos \left( {{\phi _k}} \right)} } \right)^2} + {\left( {\sum\limits_{k = 1}^K {\sqrt\frac{1}{{{L_{G,k}^\beta}}}\sin \left( {{\phi _k}} \right)} } \right)^2} \hfill ,\\
&E\left\{ {{G^2}} \right\} = \sum\limits_{k = 1}^K {E\left\{ {\frac{1}{{L_{G,k}^{\beta}}}\cos {{\left( {{\phi _k}} \right)}^2}} \right\}}  + \sum\limits_{k = 1}^K {E\left\{ {\frac{1}{{L_{G,k}^{\beta}}}\sin {{\left( {{\phi _k}} \right)}^2}} \right\}}  \hfill ,\\
&E\left\{ {{G^2}} \right\} = \frac{1}{2}\sum\limits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}}}  + \frac{1}{2}\sum\limits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}} = } \sum\limits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}}}  \hfill ,\label{eq:G_square}
\end{align}
}
where \eqref{eq:G_square} is obtained follows from $\phi_k \sim U\left( 0, 2\pi\right) $. Therefore, the third term of \eqref{eq:standaloe_channel_power_Gain_derive} is given by
\begin{equation}\label{eq:standalone_third_term}
E\left\{ {\frac{{\eta {N_G}}}{{\left( {{N_B} + K} \right)}}{G^2}} \right\} = \frac{{\eta {N_G}}}{{\left( {{N_B} + K} \right)}}\sum\limits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}}} .
\end{equation}

By summing \eqref{eq:standalone_first_term} and \eqref{eq:standalone_third_term}, we can obtain
\begin{equation}\label{eq:standalone_channel_power_Gain_temp}
E\left\{ {{{\left| {{h_S}} \right|}^2}} \right\} = \frac{{\eta {N_B}{P_{S,B}}}}{{L_B^{\alpha }}} + \eta {N_G}{P_{S,G}}\sum\limits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}}}.
\end{equation}

By substituting ${P_{S,B}} = \frac{{{N_B}}}{{{N_B} + K}}$ and ${P_{S,G}} = \frac{1}{{{N_B} + K}}$ into \eqref{eq:standalone_channel_power_Gain_temp}, the average channel gain under the SD scheme can finally be obtained as 
\begin{equation}
E\left\{ {{{\left| {{h_{S}}} \right|}^2}} \right\} = \frac{{\eta N_B^2}}{{L_B^{\alpha }\left( {{N_B} + K} \right)}} + \frac{{\eta {N_G}}}{{\left( {{N_B} + K} \right)}}\sum\limits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}}}.
\end{equation}
% \qed

\section{Proof of {\textbf{Proposition \ref{prop:scd-pa-channel}}} }
\label{proof-prop:scd-pa-channel}
Let the downlink channel gain of waveguide RF port $k$ be denoted as ${p_k} = \frac{{\eta {N_G}}}{{L_{G,k}^{\beta}}}$. Assume the total transmit power is $1$, with the power allocation ratio for each port being ${w_k}$ and $\sum\nolimits_{k = 1}^K {{w_1} = 1}$. According to Equation \eqref{eq:waveguide_phase_align}, the transmitted signals from all waveguides can be coherently combined at the receiver, resulting in an equivalent channel gain of ${\left( {\sum\nolimits_{k = 1}^K {\sqrt {{p_i}{w_i}} } } \right)^2}$. We then formulate the following optimization problem
\begin{equation}
\begin{gathered}
\mathop {\arg \max }\limits_{{w_k}} {\left( {\sum\limits_{k = 1}^K {\sqrt {{p_k}{w_k}} } } \right)^2} \hfill \\
s.t.\;\sum\limits_{k = 1}^K {{w_k} = 1} ,{w_k} \geqslant 0 \hfill,
\end{gathered} 
\end{equation}
which is a convex optimization problem. Using the method of Lagrange multipliers, we can conclude that the maximum channel gain $\sum\nolimits_{k = 1}^K {{p_k}} $ is achieved when the power allocation coefficients satisfy 
\begin{equation}
w_k^* = \frac{{{p_k}}}{{\sum\nolimits_{k = 1}^K {{p_k}} }} = \frac{1}{{\sum\nolimits_{k = 1}^K {\frac{{\eta {N_G}}}{{L_{G,k}^{\beta}}}} }}\frac{{\eta {N_G}}}{{L_{G,k}^{\beta}}}.
\end{equation}

\section{Proof of \textbf{Proposition \ref{prop:svdscheme}}}
\label{proof-prop:svdscheme}
The derivation of \eqref{eq:semi_cooperative_channel_power_Gain} is given as follows.
{\small
\begin{equation}
\begin{gathered}
E\left\{ {{{\left| {{h_C}} \right|}^2}} \right\} \hfill \\
= E\left\{ {{{\left| {\sqrt {\frac{\eta {P_{C,B}}}{L_B^\alpha}} \left\| {{{{\bm{\tilde h}}}_B}} \right\| + \sqrt {\eta {P_{C,G}}\sum\limits_{k = 1}^K {\frac{{{N_G}}}{{L_{G,k}^{\beta}}}} } {e^{ - j{\phi _1}}}} \right|}^2}} \right\} \hfill \\
= \frac{{\eta {P_{C,B}}}}{{L_B^{\alpha }}}E\left\{ {{{\left\| {{{{\bm{\tilde h}}}_B}} \right\|}^2}} \right\} \hfill \\
+ E\left\{ {\frac{\eta }{{\sqrt{ L_B^\alpha} }}\sqrt {{P_{C,B}}{P_{C,G}}\sum\limits_{k = 1}^K {\frac{{{N_G}}}{{L_{G,k}^{\beta}}}} } \left\| {{{{\bm{\tilde h}}}_B}} \right\|\cos \left( {{\phi _1}} \right)} \right\} \hfill\\
+ \eta {P_{C,G}}\sum\limits_{k = 1}^K {\frac{{{N_G}}}{{L_{G,k}^{\beta}}}}  \hfill \\
= \frac{{\eta {N_B}{P_{C,B}}}}{{L_B^{\alpha }}} + \eta {N_G}{P_{C,G}}\sum\limits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}}}  \hfill 
\end{gathered} 
\end{equation}
}
The last equality holds because $\phi_1 \sim U\left(0, 2\pi \right) $ and the cross-product term is zero. With ${P_{S,B}} = \frac{{{N_B}}}{{{N_B} + K}}$ and ${P_{S,G}} = \frac{1}{{{N_B} + K}}$, the average channel gain under the SD scheme is obtained as 
\begin{equation}
E\left\{ {{{\left| {{h_C}} \right|}^2}} \right\} = \frac{{\eta N_B^2}}{{\left( {{N_B} + K} \right)L_B^{\alpha }}} + \frac{{\eta {N_G}K}}{{\left( {{N_B} + K} \right)}}\sum\limits_{k = 1}^K {\frac{1}{{L_{G,k}^{\beta}}}}.
\end{equation}

