	\RestyleAlgo{ruled}
	\LinesNumbered
	\begin{algorithm}[ht!]
		\caption{PSA-CMA-ES with Reformulated Step-size Correction}\label{alg:CMA-ES}
		\KwInput{\(\textbf{m}^{(0)} \in \mathbb{R}^{n}, \sigma^{(0)} \in \mathbb{R}_{+}\), $\kappa$, $\mathrm{L}$, $a,b$, $g_{\text{max}}, \epsilon$}
		\KwOutput{\(c_{m} = 1, \sum_{i=1}^{\mu}w_i = 1, \alpha = 1.4, \beta = 0.4, \lambda_{\text{min}} = \lambda_{\text{def}}, \lambda_{\text{max}} = 512 \, \lambda_{\text{def}}\)}
		\KwResult{\(\textbf{C}^{(0)} = \textbf{I}, \textbf{p}_{c}^{(0)} = \mathbf{0}, \textbf{p}_{\sigma}^{(0)} = \mathbf{0}, \textbf{p}_{\theta}^{(0)} = \mathbf{0}, \gamma_{c}^{(0)} = 0, \gamma_{\sigma}^{(0)} = 0, \gamma_{\theta}^{(0)} = 0, \lambda^{(0)} = \lambda_{r}^{(0)} = \lambda_{\text{def}}, g=0\)}

		\While{ $g<g_{\text{max}}$ or $\left|f\left( \textbf{m}^{(g+1)}\right) - f\left( \textbf{m}^{(g)}\right) \right| >\epsilon $}{
			\footnotesize\ttfamily{//(re-)compute parameters depending on \(\lambda_r\)}\\
			\(\mu \leftarrow \lfloor \lambda_{r}/2 \rfloor\)\\
			\(w_{i} \leftarrow \dfrac{\ln(\frac{\lambda+1}{2}) - \ln(i)}{\sum_{i=1}^{\mu} [\ln(\frac{\lambda+1}{2}) - \ln(i)]} \text{ for } i = 1,\dots,\mu; \text{ and } 0 \text{ otherwise} \)\\
		%	\(w_{i} \leftarrow 0 \quad (i = \mu + 1,\dots,\lambda_{r})\)\\
			\(\mu_{w} \leftarrow 1/\sum_{i=1}^{\mu} w_{i}^{2}\)\\   
			\(c_{\sigma} \leftarrow (\mu_{w} + 2)/(n + \mu_{w} + 5)\)\\   
			\(d_{\sigma} \leftarrow 1 + 2\max(0,\sqrt{(\mu_{\text{eff}}-1)/(n+1)} - 1) + c_{\sigma}\)\\   
			\(c_{c} \leftarrow (4 + \mu_{\text{eff}}/n)/(n+4+2\mu_{\text{eff}}/n)\)\\ 
			\(c_{1} \leftarrow 2/((n+1.3)^{2} + \mu_{\text{eff}})\)\\

			\(\textbf{x}^{(g+1)}_i \sim \textbf{m}^{(g)} + \sigma^{(g)}N(\textbf{0},\textbf{C}^{(g)}), \text{ for } i=1,...,\lambda.\)\\
			\footnotesize\ttfamily{Perform CMA-ES iteration (\ref{eq:2}), (\ref{eq:5}) and (\ref{eq:cm_update}) of Section \ref{sec:PSA-CMA-ES}}\\

			\(\textbf{m}' \leftarrow \textbf{m}, \textbf{C}' \leftarrow \textbf{C}, \sigma' \leftarrow \sigma\);  \footnotesize\ttfamily{//Keep old values}\\

			\footnotesize\ttfamily{Update evolution paths  (\ref{eq:4}), (\ref{eq:pc}) and (\ref{eq:p_theta}) of Section \ref{sec:PSA-CMA-ES}}\\

			\(\gamma^{(g+1)}_{\sigma} = (1-c_{\sigma})^{2}\gamma^{(g)}_{\sigma} + c_{\sigma}(2 - c_{\sigma})\); \footnotesize\ttfamily{//Update normalization factors}\\
			\(	\gamma^{(g+1)}_{c} = (1-c_{c})^{2}\gamma^{(g)}_{c} + h^{(g+1)}_{\sigma} c_{c}(2 - c_{c})\)\\
			\(\gamma^{(g+1)}_{\theta} = (1 - \beta)^{2}\gamma^{(g)}_{\theta} + \beta(2 - \beta)\)\\

			\footnotesize\ttfamily{Update population size (\ref{eq:pop-size_update}), and (\ref{eq:pop-size_boundary}) of Section \ref{sec:PSA-CMA-ES}}\\

			\footnotesize\ttfamily{//Reformulated step-size correction}\\
			\eIf{\(||\textbf{p}_{\sigma}|| \geq \mathbb{E}\left[||\mathcal{N}(\textbf{0},\textit{I})||\right]\)}{
				\(\sigma^{(g+1)} = \sigma^{(g+1)}\);
			}{
				\eIf{\(|\lambda^{(g+1)} - \lambda^{(g)}|< \mathrm{L}\)}{
					\(\sigma^{(g+1)} = \sigma^{(g+1)} \cdot \kappa \frac{\rho\left(\lambda^{(g+1)}_{r}\right)}{\rho\left(\lambda^{(g)}_{r}\right)}\)
				}{
					\(\sigma^{(g+1)} = \sigma^{(g+1)} \cdot \frac{\rho\left(\lambda^{(g+1)}_{r}\right)}{\rho\left(\lambda^{(g)}_{r}\right)}\); \\
					\footnotesize\ttfamily{ Here \(\rho\) is a function of \(\lambda^{(g)}_{r}\) and \(\rho(\lambda^{(g)}_{r}) = \frac{\left(-\sum_{i=1}^{\lambda_{r}}w_i \mathbb{E}[\mathcal{N}_{i:\lambda_{r}}]\right)\cdot n \cdot \mu_{\text{w}}}{n-1+\left(\left(-\sum_{i=1}^{\lambda_{r}}w_i \mathbb{E}[\mathcal{N}_{i:\lambda_{r}}]\right)^{2}\mu_{\text{w}}\right)}\)}
				}
			}
			\(g \leftarrow g+1\)

		}
	\end{algorithm}



